    "provenance": {
      "type": "object",
      "description": "何から作られたか。**`generatedFromCommit` ではなく `inputDigest` で固定してください。** artifact を含めてコミットすると HEAD は変わりますが、入力は変わっていないので `inputDigest` は変わりません",
      "required": [
        "generatorVersion",
        "generatedFromCommit",
        "workingTreeDirty",
        "revisionOverride",
        "artifactKind",
        "inputDigestAlgorithm",
        "inputDigest",
        "inputDigestScope",
        "inputFiles",
        "command",
        "artifactDate"
      ],
      "additionalProperties": false,
      "properties": {
        "generatorVersion": {
          "type": "integer",
          "minimum": 1,
          "description": "生成器の版。出力の形を変えたときだけ上がる。データが変わっただけでは上がらない (それは inputDigest が表す)"
