        },
        "note": {
          "type": "string"
        },
        "detail": {
          "type": "object",
          "description": "根拠の内訳。実在の単一品と、複数の部品から組み立てた構成 profile を取り違えさせないための欄",
          "required": [
            "partIdentityBasis",
            "externalGeometryBasis",
            "terminalLayoutBasis",
            "breakContactBasis",
            "internalContactGeometryBasis",
            "electricalContinuityValidation",
            "acousticValidation",
            "constructedProfile",
            "constructedFrom"
          ],
          "additionalProperties": false,
          "properties": {
            "partIdentityBasis": {
              "type": "string"
            },
            "externalGeometryBasis": {
              "type": "string"
            },
            "terminalLayoutBasis": {
              "type": "string"
            },
            "breakContactBasis": {
              "type": "string"
            },
            "internalContactGeometryBasis": {
              "type": "string"
            },
            "electricalContinuityValidation": {
              "type": "string"
            },
            "acousticValidation": {
              "type": "string"
            },
            "constructedProfile": {
              "type": "boolean",
              "description": "true なら複数の部品から組み立てたもので、実在の単一品ではない"
            },
            "constructedFrom": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "grade": {
      "enum": [
        "FACT",
        "DERIVED",
        "ASSUMPTION",
        "UNKNOWN"
      ]
    },
    "interval": {
      "type": "object",
      "required": [
        "intervalId",
        "nominalStartMm",
        "nominalEndMm",
        "normalizedStart",
        "normalizedEnd",
        "contacts",
        "circuitEdges",
        "circuitNets",
        "terminalToPlugNet",
        "breakStates",
        "mechanicalFlags",
        "electricalTopology",
        "acousticAnnotation",
        "evidenceGrade",
