          "type": "number",
          "minimum": 0,
          "maximum": 1
        },
        "normalizedEnd": {
          "type": "number",
          "minimum": 0,
          "maximum": 1
        },
        "contacts": {
          "type": "array",
          "items": {
            "type": "object",
            "required": [
              "contactId",
              "terminalId",
              "state",
              "connectedNets",
              "evidenceGrade"
            ],
            "additionalProperties": false,
            "properties": {
              "contactId": {
                "type": "string"
              },
              "terminalId": {
                "type": "string"
              },
              "state": {
                "type": "string"
              },
              "connectedNets": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
