 "type": "object",
 "required": [
  "schemaVersion",
  "schemaId",
  "contractMigration",
  "mechanicalInsertion",
  "profileId",
  "variantId",
  "plug",
  "jack",
  "plugBasis",
  "jackBasis",
  "provenance",
  "sourceRevision",
  "generatedAt",
  "fullInsertionDepthMm",
  "stepMm",
  "coordinateSystem",
  "dataLicense",
  "modelLimitations",
  "assumptionSummary",
  "intervals",
  "events",
  "sensitivitySummary",
  "absentTopologies"
 ],
 "additionalProperties": false,
 "properties": {
