      }
     }
    },
    "terminalToPlugNet": {
     "type": "object",
     "additionalProperties": {
      "type": "array",
      "items": {
       "type": "string"
      }
     }
    },
    "breakStates": {
     "type": "object",
     "additionalProperties": {
      "type": [
       "string",
       "null"
      ]
     }
    },
    "mechanicalFlags": {
     "type": "object",
     "required": [
      "anyBridged",
      "anyWrongSegment",
      "anyUnstable"
     ],
     "additionalProperties": false,
     "properties": {
      "anyBridged": {
       "type": "boolean"
      },
      "anyWrongSegment": {
       "type": "boolean"
      },
      "anyUnstable": {
       "type": "boolean"
      }
     }
    },
    "electricalTopology": {
     "type": "object",
     "description": "**電気的な事実。** どう聞こえるかは含まない (それは acousticAnnotation)。2026-08-03 まで topologyClass は acousticAnnotation の中にあり、電気の分類と聴感の仮説が同じ入れ物に同居していた",
     "required": [
      "topologyClass",
      "reasonCode",
      "openSignals",
      "confidenceBoundary"
     ],
     "additionalProperties": false,
     "properties": {
      "topologyClass": {
       "enum": [
        "all-expected-functions-match",
        "no-path",
        "one-sided",
        "on-insulator",
        "wrong-conductor",
        "signal-to-signal-short",
        "signal-to-return-short",
        "ground-open-differential",
        "ground-open-nondifferential"
       ],
       "description": "**v2 で `fully-seated` を `all-expected-functions-match` へ改めた。**旧名は「プラグ肩が当たった」と読めたが、実体は reasonCode のとおり ALL_EXPECTED_FUNCTIONS_MATCH でしかない。機械的な完全挿入との差は `mechanicalInsertion.gapMm` にある"
      },
      "reasonCode": {
       "type": "string",
       "description": "なぜその分類になったか。文言ではなく機械可読な符号。表示文を変えても変わらない"
      },
      "openSignals": {
       "type": "array",
       "description": "どこにも届いていない機能。端子が存在するのに導体へ届いていないものだけ",
       "items": {
        "enum": [
         "L",
         "R",
         "GND",
         "MIC"
        ]
       }
      },
      "confidenceBoundary": {
       "type": "boolean",
       "description": "判定の境目に近いか。接触が不安定、またはブレーク接点が判定不能なときに立つ"
      }
     }
    },
    "acousticAnnotation": {
     "type": "object",
     "description": "**未検証の聴感の仮説であって DSP 係数ではない。** これをフィルタ係数・ゲイン・クロストーク量へ直接変換してはならない。電気的な分類は electricalTopology にある",
     "required": [
      "audibleHypothesis",
      "electricalRisk",
      "confidence"
     ],
     "additionalProperties": false,
     "properties": {
      "audibleHypothesis": {
       "type": [
        "string",
        "null"
       ]
      },
      "stabilityOverlay": {
       "type": [
        "string",
        "null"
       ]
      },
      "electricalRisk": {
       "enum": [
        "none",
        "protection-dependent",
        "short-circuit"
       ]
      },
      "confidence": {
       "enum": [
        "low",
        "medium",
        "high"
       ]
      }
     }
    },
    "evidenceGrade": {
     "$ref": "#/definitions/grade",
     "description": "この区間の結論を支える最も弱い根拠区分"
    },
    "uncertainty": {
     "type": "object",
     "required": [
      "boundaryResolutionMm",
      "systematicShiftMm",
      "notes"
     ],
     "additionalProperties": false,
     "properties": {
      "boundaryResolutionMm": {
       "type": "number",
       "description": "区間境界の分解能。走査刻みそのもの"
      },
      "systematicShiftMm": {
       "type": [
        "number",
        "null"
       ],
       "description": "全区間へ一律にかかりうる系統的なずれ"
      },
      "notes": {
       "type": "array",
       "items": {
        "type": "string"
       }
      }
     }
    },
    "safetyFlags": {
     "type": "object",
     "required": [
      "shortsSignalToReturn",
      "shortsSignalToSignal"
     ],
     "additionalProperties": false,
     "properties": {
      "shortsSignalToReturn": {
       "type": "boolean"
      },
      "shortsSignalToSignal": {
       "type": "boolean"
      }
     }
    }
   }
  }
 }
}

{
 "$schema": "http://json-schema.org/draft-07/schema#",
 "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/measurement-record.v1.schema.json",
 "title": "trs-jack-3d measurement records v1",
 "description": "**実測記録の正本。**`verifiedPhysical` はこの台帳から機械で決まる（条文 = docs/VERIFIED_PHYSICAL_GATE.md・判定器 = scripts/measurementGate.mjs）。**記録が 0 件なら false のままで、それが正しい状態である。**空だからといって埋める必要はない（実測は募集するが必須にしていない → docs/VERIFICATION_PLAN.md 冒頭）。",
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "schemaId",
  "purpose",
  "why",
  "gateDocument",
  "gateVersion",
  "verifiedBy",
  "records"
 ],
 "properties": {
  "schemaVersion": { "const": 1 },
  "schemaId": { "const": "trs-jack-3d-measurement-records.v1" },
  "purpose": { "type": "string", "minLength": 1 },
  "why": { "type": "string", "minLength": 1 },
  "gateDocument": { "const": "docs/VERIFIED_PHYSICAL_GATE.md" },
  "gateVersion": { "type": "integer", "minimum": 1 },
  "verifiedBy": {
   "type": "string",
   "minLength": 1,
   "description": "**この台帳と profile の食い違いを、どの検査が捕まえるか。**書いただけの表にしないため"
  },
  "records": {
   "type": "array",
   "description": "**古い順に並べる。**取り下げても消さない（retracted: true にする）。消すと、その記録で一度 true になっていた事実が追えなくなる",
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "recordId",
     "observation",
     "variantId",
     "measuredBy",
     "measuredOn",
     "instrument",
     "parts",
     "valuesMm"
    ],
    "properties": {
     "recordId": { "type": "string", "pattern": "^MR[0-9]{4}$" },
     "observation": {
      "enum": [
       "L_FIRST_CONTACT_SHOULDER_GAP_MM",
       "RING_BREAK_OPEN_DEPTH_MM",
       "TIP_BREAK_OPEN_DEPTH_MM"
      ],
      "description": "**観測点の定義は scripts/measurementGate.mjs の OBSERVATIONS が正本。**ここは形だけを見る"
     },
     "variantId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9-]+\\|[A-Za-z0-9-]+$",
      "description": "**測った組み合わせ。**観測点の定義と一致しない記録は判定器が弾く"
     },
     "measuredBy": {
      "type": "string",
      "minLength": 1,
      "description": "**誰の記録かを追えるようにする。**氏名でなくハンドルや Issue 番号でよい"
     },
     "measuredOn": { "type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" },
     "instrument": {
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "resolutionMm"],
      "properties": {
       "kind": { "type": "string", "minLength": 1 },
       "resolutionMm": {
        "type": "number",
        "exclusiveMinimum": 0,
        "description": "**必須。**分解能が分からない値は、ばらつきが許容内かを判断できない"
       },
       "model": { "type": "string" }
      }
     },
     "parts": {
      "type": "object",
      "additionalProperties": false,
      "required": ["jack", "plug"],
      "properties": {
       "jack": { "type": "string", "minLength": 1 },
       "jackLot": { "type": "string" },
       "plug": { "type": "string", "minLength": 1 },
       "plugLot": { "type": "string" }
      }
     },
     "valuesMm": {
      "type": "array",
      "minItems": 3,
      "items": { "type": "number", "exclusiveMinimum": 0 },
      "description": "**生値をそのまま並べる。3 回以上。**平均だけの記録は受け取らない。ばらつきが見えないと、その値がどれくらい信用できるか誰にも分からない"
     },
     "note": { "type": "string" },
     "retracted": { "type": "boolean" },
     "retractedReason": { "type": "string" },
     "sourceUrl": { "type": "string", "description": "Issue や PR など、提供のやりとりが残っている場所" }
    }
   }
  }
 }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/real-jack-comparison.v1.schema.json",
  "title": "実在部品の図面と本モデルの仮定の突き合わせ v1",
  "description": "npm run compare:real-jack の出力。**この artifact の目的は反証を保持することである。** 唯一入手できた実在 4極ジャックの断面図 (pro-SIGNAL PS000001) を入れると、このプロジェクトの看板だった左右差分の区間が消える。その結果を消させないための構造になっている。",
  "type": "object",
  "required": [
    "schemaVersion",
    "generatedAt",
    "variantId",
    "stepMm",
    "question",
    "referencePart",
    "contactPositions",
    "scaleCheck",
    "result",
    "whyItDisappears",
    "decision",
    "lumbergTerminalScenario",
    "testerPredictions",
    "limitations"
  ],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": { "const": 1 },
    "generatedAt": { "type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" },
    "variantId": { "type": "string" },
    "stepMm": { "type": "number", "exclusiveMinimum": 0 },
    "question": { "type": "string", "minLength": 20 },
    "referencePart": {
      "type": "object",
      "required": ["partNumber", "representativeness"],
      "additionalProperties": true,
      "properties": {
        "partNumber": { "type": "string" },
        "representativeness": {
          "type": "string",
          "minLength": 10,
          "description": "**1 件の図面を 3.5mm ジャック一般へ広げない。** 代表性を主張していないことを明文で持つ"
        }
      }
    },
    "contactPositions": {
      "type": "object",
      "required": ["unit", "datum", "assumed", "drawing", "deltaMm"],
      "additionalProperties": false,
      "properties": {
        "unit": { "type": "string" },
        "datum": { "type": "string" },
        "assumed": { "$ref": "#/definitions/positions" },
        "drawing": { "$ref": "#/definitions/positions" },
        "deltaMm": { "$ref": "#/definitions/positions" }
      }
    },
    "scaleCheck": {
      "type": "object",
      "description": "図面が縮尺どおりで、同じ基準面を使っていることの照合。ここが崩れると比較の前提そのものが崩れる",
      "required": ["method", "measuredFromDrawingMm", "predictedByModelMm"],
      "additionalProperties": true,
      "properties": {
        "method": { "type": "string" },
        "measuredFromDrawingMm": { "type": "array", "minItems": 1, "items": { "type": "number" } },
        "predictedByModelMm": { "type": "array", "minItems": 1, "items": { "type": "number" } }
      }
    },
    "result": {
      "type": "object",
      "required": ["assumed", "drawing", "verdict"],
      "additionalProperties": false,
      "properties": {
        "assumed": { "$ref": "#/definitions/sideResult" },
        "drawing": { "$ref": "#/definitions/sideResult" },
        "verdict": { "type": "string", "minLength": 10 }
      }
    },
    "whyItDisappears": { "type": "object", "additionalProperties": true },
    "decision": {
      "type": "object",
      "required": ["chosen", "rejected", "reasoning"],
      "additionalProperties": false,
      "properties": {
        "chosen": {
          "enum": ["compare-only", "replace-assumption", "add-variant"],
          "description": "compare-only = 比較対象として持つだけで、モデルの値は差し替えない"
        },
        "rejected": { "type": "array", "items": { "type": ["string", "object"] } },
        "reasoning": { "type": ["string", "array", "object"] }
      }
    },
    "lumbergTerminalScenario": {
      "type": "object",
      "description": "**実在資料 2 件が逆を指している。** PS000001 は区間なし、Lumberg 1503 28 の端子位置は区間あり。片方だけ残して「決着した」と書けないようにする",
      "required": ["terminalsFromNoseMm", "caveat", "fullInsertionOk", "differenceWindows"],
      "additionalProperties": true,
      "properties": {
        "terminalsFromNoseMm": { "type": "object", "additionalProperties": { "type": "number" } },
        "caveat": { "type": "string", "minLength": 10 },
        "fullInsertionOk": { "type": "boolean" },
        "differenceWindows": { "type": "array", "items": { "$ref": "#/definitions/window" } }
      }
    },
    "testerPredictions": {
      "type": "object",
      "required": ["note", "variantId", "assumed", "drawing"],
      "additionalProperties": false,
      "properties": {
        "note": { "type": "string" },
        "variantId": { "type": "string" },
        "assumed": { "$ref": "#/definitions/predictionSet" },
        "drawing": { "$ref": "#/definitions/predictionSet" }
      }
    },
    "limitations": {
      "type": "array",
      "minItems": 1,
      "description": "**空にできない。** 未確認事項を消させない",
      "items": { "type": "string" }
    }
  },
  "definitions": {
    "positions": {
      "type": "object",
      "additionalProperties": { "type": "number" }
    },
    "window": {
      "type": "object",
      "required": ["fromMm", "toMm"],
      "additionalProperties": true,
      "properties": { "fromMm": { "type": "number" }, "toMm": { "type": "number" } }
    },
    "sideResult": {
      "type": "object",
      "required": ["differenceWindows"],
      "additionalProperties": true,
      "properties": {
        "differenceWindows": { "type": "array", "items": { "$ref": "#/definitions/window" } }
      }
    },
    "predictionSet": {
      "type": "object",
      "description": "実物で確かめるときの対抗予測。役割ごとに肩からの隙間を出す",
      "additionalProperties": {
        "type": "object",
        "required": ["shoulderGapMm"],
        "additionalProperties": true,
        "properties": { "shoulderGapMm": { "type": "number" } }
      }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/source-input-manifest.v1.schema.json",
  "title": "trs-jack-3d source input manifest v1",
  "description": "artifact の入力ファイルを tag source と独立に検算するための一覧。**この manifest 自身は証明ではない。**tag source archive を取って自分で計算すること",
  "type": "object",
  "required": [
    "schemaVersion",
    "generatedAt",
    "generatedFromCommit",
    "purpose",
    "inputScope",
    "inputFilesTotal",
    "inconsistentAcrossArtifacts",
    "mismatchedWithWorkingTreeAtBuild",
    "inputFiles",
    "verificationRecipe",
    "note"
  ],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "generatedBy": {
      "type": "string"
    },
    "generatedAt": {
      "type": "string",
      "pattern": "^\\d{4}-\\d{2}-\\d{2}$"
    },
    "generatedFromCommit": {
      "type": "string",
      "pattern": "^([0-9a-f]{40}|UNKNOWN)$"
    },
    "purpose": {
      "type": "string"
    },
    "inputScope": {
      "type": "object",
      "description": "**この一覧が「全部」なのかを確かめるための範囲**（v0.3.0 フォローアップ P1-2）。件数と sha256 だけでは記録漏れを見つけられない——落ちている入力があっても、残った分は全部一致する。範囲を渡せば受け手は自分の source を歩いて探せる",
      "additionalProperties": false,
      "required": [
        "file",
        "sha256",
        "recursiveDirectories",
        "requiredExactFiles",
        "allowedGeneratedInputs",
        "excludedOutputs",
        "notCovered",
        "verifyCommand"
      ],
      "properties": {
        "file": {
          "const": "source-input-scope.v1.json"
        },
        "sha256": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "recursiveDirectories": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string"
          }
        },
        "requiredExactFiles": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string"
          }
        },
        "allowedGeneratedInputs": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "excludedOutputs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string"
          }
        },
        "notCovered": {
          "type": "array",
          "minItems": 1,
          "description": "**inputDigest が覆っていないもの。**「一致した」は「これらも同じだった」を意味しない",
          "items": {
            "type": "object",
            "required": [
              "what",
              "why",
              "consequence"
            ],
            "properties": {
              "what": {
                "type": "string"
              },
              "why": {
                "type": "string"
              },
              "consequence": {
                "type": "string"
              }
            }
          }
        },
        "verifyCommand": {
          "type": "string"
        }
      }
    },
    "inputFilesTotal": {
      "type": "integer",
      "minimum": 1
    },
    "inconsistentAcrossArtifacts": {
      "type": "integer",
      "minimum": 0,
      "description": "同じパスが artifact 間で違う sha256 で現れた数。**0 でなければどれかが古い入力から作られている**"
    },
    "mismatchedWithWorkingTreeAtBuild": {
      "type": "integer",
      "minimum": 0
    },
    "inputFiles": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "path",
          "role",
          "recordedSha256",
          "consistentAcrossArtifacts",
          "actualSha256AtBuild",
          "matchesWorkingTree",
          "consumedBy"
        ],
        "additionalProperties": false,
        "properties": {
          "path": {
            "type": "string"
          },
          "role": {
            "type": "string"
          },
          "recordedSha256": {
            "oneOf": [
              {
                "type": "string",
                "pattern": "^[0-9a-f]{64}$"
              },
              {
                "type": "array",
                "minItems": 2,
                "items": {
                  "type": "string",
                  "pattern": "^[0-9a-f]{64}$"
                }
              }
            ],
            "description": "**配列なら artifact 間で食い違っている。**先勝ちで潰さず両方を残す"
          },
          "consistentAcrossArtifacts": {
            "type": "boolean"
          },
          "actualSha256AtBuild": {
            "oneOf": [
              {
                "type": "string",
                "pattern": "^[0-9a-f]{64}$"
              },
              {
                "type": "null"
              }
            ]
          },
          "matchesWorkingTree": {
            "type": "boolean"
          },
          "consumedBy": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "string"
            }
          }
        }
      }
    },
    "verificationRecipe": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string"
      }
    },
    "note": {
      "type": "string"
    }
  }
}

