     "items": {
      "type": "string"
     }
    },
    "excludedOutputs": {
     "type": "array",
     "minItems": 1,
     "items": {
      "type": "string"
     }
    },
    "notCovered": {
     "type": "array",
     "minItems": 1,
     "description": "**inputDigest が覆っていないもの。**「一致した」は「これらも同じだった」を意味しない",
     "items": {
      "type": "object",
      "required": [
       "what",
       "why",
       "consequence"
      ],
      "properties": {
       "what": {
        "type": "string"
       },
       "why": {
        "type": "string"
       },
       "consequence": {
        "type": "string"
       }
      }
     }
    },
    "verifyCommand": {
     "type": "string"
    }
   }
  },
  "inputFilesTotal": {
   "type": "integer",
   "minimum": 1
  },
  "inconsistentAcrossArtifacts": {
   "type": "integer",
   "minimum": 0,
   "description": "同じパスが artifact 間で違う sha256 で現れた数。**0 でなければどれかが古い入力から作られている**"
  },
  "mismatchedWithWorkingTreeAtBuild": {
   "type": "integer",
   "minimum": 0
  },
  "inputFiles": {
   "type": "array",
   "minItems": 1,
   "items": {
    "type": "object",
    "required": [
     "path",
     "role",
     "recordedSha256",
     "consistentAcrossArtifacts",
     "actualSha256AtBuild",
     "matchesWorkingTree",
     "consumedBy"
    ],
    "additionalProperties": false,
    "properties": {
     "path": {
      "type": "string"
     },
     "role": {
      "type": "string"
     },
     "recordedSha256": {
      "oneOf": [
       {
        "type": "string",
        "pattern": "^[0-9a-f]{64}$"
       },
       {
        "type": "array",
        "minItems": 2,
        "items": {
         "type": "string",
         "pattern": "^[0-9a-f]{64}$"
        }
       }
      ],
      "description": "**配列なら artifact 間で食い違っている。**先勝ちで潰さず両方を残す"
     },
     "consistentAcrossArtifacts": {
      "type": "boolean"
     },
     "actualSha256AtBuild": {
      "oneOf": [
       {
        "type": "string",
        "pattern": "^[0-9a-f]{64}$"
       },
       {
        "type": "null"
       }
      ]
     },
     "matchesWorkingTree": {
      "type": "boolean"
     },
     "consumedBy": {
      "type": "array",
      "minItems": 1,
      "items": {
       "type": "string"
      }
     }
    }
   }
  },
  "verificationRecipe": {
   "type": "array",
   "minItems": 1,
   "items": {
    "type": "string"
   }
  },
  "note": {
   "type": "string"
  },
  "contractMigration": {
   "type": "object",
   "description": "**版と契約変更の対応表。**旧語彙を読む消費側が沈黙ではなくエラーになるためのもの。判定は docs/SCHEMA_VERSIONING_POLICY.md の条文（新 schema が許す言語が旧 schema の言語に収まるか）による。**artifact の中身では判定しない**——同じ変更でも、その版の artifact が新しい値を使っているかで答えが反転してしまうため。正本は contract-migration.v1.json",
   "required": [
    "schemaId",
    "previousSchemaId",
    "fromSchemaVersion",
    "toSchemaVersion",
    "breaking",
    "policy",
    "consumerAction",
    "renamedAssets",
    "history"
   ],
   "additionalProperties": false,
   "properties": {
    "schemaId": {
     "const": "source-input-manifest.v2"
    },
    "previousSchemaId": {
     "const": "source-input-manifest.v1"
    },
    "fromSchemaVersion": {
     "const": 1
    },
    "toSchemaVersion": {
     "const": 2
    },
    "breaking": {
     "const": true
    },
    "policy": {
     "type": "object",
     "required": [
      "document",
      "policyVersion",
      "decisionRule"
     ],
     "additionalProperties": false,
     "properties": {
      "document": {
       "const": "docs/SCHEMA_VERSIONING_POLICY.md"
      },
      "policyVersion": {
       "type": "integer",
       "minimum": 1
      },
      "decisionRule": {
       "const": "language-subset"
      },
      "note": {
       "type": "string"
      }
     }
    },
    "consumerAction": {
     "type": "string",
     "minLength": 1
    },
    "renamedAssets": {
     "type": "array",
     "minItems": 1,
     "description": "**条文の外（第6条）。**配布名は schema の言語に現れないので、名前で引く下流は schema 検査に到達する前に「ファイルが無い」で止まる",
     "items": {
      "type": "object",
      "required": [
       "from",
       "to",
       "reason"
      ],
      "additionalProperties": false,
      "properties": {
       "from": {
        "type": "string"
       },
       "to": {
        "type": "string"
       },
       "reason": {
        "type": "string"
       }
      }
     }
    },
    "history": {
     "type": "array",
     "minItems": 1,
     "description": "**契約が変わった release を古い順に並べる。**版を据え置いたまま変えた回は versionWasHeld: true で残す。それが条文違反の記録である",
     "items": {
      "type": "object",
      "required": [
       "shippedIn",
       "previousRelease",
       "previousSchemaPath",
       "currentSchemaPath",
       "schemaVersionAtTheTime",
       "versionWasHeld",
       "policyVerdict",
       "changes"
      ],
      "additionalProperties": false,
      "properties": {
       "shippedIn": {
        "type": "string",
        "pattern": "^v[0-9]+\\.[0-9]+\\.[0-9]+$"
       },
       "previousRelease": {
        "type": "string",
        "pattern": "^v[0-9]+\\.[0-9]+\\.[0-9]+$"
       },
       "previousSchemaPath": {
        "type": "string",
        "description": "**previousRelease 時点でのこの schema のパス。**版を上げるとファイル名が変わるので、記録側に持たせないと機械で突き合わせられない"
       },
       "currentSchemaPath": {
        "type": "string"
       },
       "schemaVersionAtTheTime": {
        "type": "integer",
        "minimum": 1
       },
       "schemaVersionShouldHaveBeen": {
        "type": "integer",
        "minimum": 1,
        "description": "据え置いた回にだけ入る。**条文に照らして本来あるべきだった版**"
       },
       "versionWasHeld": {
        "type": "boolean"
       },
       "policyVerdict": {
        "enum": [
         "BUMP",
         "HOLD_RECORD",
         "HOLD"
        ]
       },
       "recordedRetroactivelyIn": {
        "type": "string",
        "pattern": "^v[0-9]+\\.[0-9]+\\.[0-9]+$",
        "description": "**いつ遡って書いたか。**当時の判断記録ではないことを隠さない"
       },
       "note": {
        "type": "string"
       },
       "changes": {
        "type": "array",
        "minItems": 1,
        "items": {
         "type": "object",
         "required": [
          "kind",
          "effect",
          "schemaPointer",
          "reason"
         ],
         "additionalProperties": false,
         "properties": {
          "kind": {
           "enum": [
            "field-added",
            "field-removed",
            "field-renamed",
            "field-reshaped",
            "enum-value-added",
            "enum-value-removed",
            "enum-value-renamed",
            "type-widened",
            "type-narrowed",
            "constraint-tightened",
            "constraint-loosened",
            "const-changed",
            "meaning-changed",
            "description-only"
           ]
          },
          "effect": {
           "enum": [
            "WIDEN",
            "NARROW",
            "NEUTRAL",
            "UNDECIDABLE"
           ],
           "description": "**scripts/schemaLanguageDiff.mjs の判定をそのまま入れる。**記録と実物がずれたらテストが落ちる"
          },
          "schemaPointer": {
           "type": "string",
           "pattern": "^/",
           "description": "**artifact ではなく schema への JSON Pointer。**実在することを機械で確かめる"
          },
          "instancePath": {
           "type": "string",
           "description": "人が読むための位置。$.a.b[].c 形式"
          },
          "added": {
           "type": "array",
           "items": {
            "type": "string"
           }
          },
          "removed": {
           "type": "array",
           "items": {
            "type": "string"
           }
          },
          "from": {
           "type": [
            "string",
            "number",
            "boolean"
           ]
          },
          "to": {
           "type": [
            "string",
            "number",
            "boolean"
           ]
          },
          "reason": {
           "type": "string",
           "minLength": 1
          }
         }
        }
       }
      }
     }
    }
   }
  }
 }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/source-input-scope.v1.schema.json",
  "title": "trs-jack-3d source input scope v1",
  "description": "artifact の inputDigest が覆う入力の範囲。**生成側 (provenance.ts) と検証側 (verifyReleaseSourceInputs.mjs) が同じこの 1 か所から読む。**片方だけに書かれた範囲は、もう片方から見えないまま穴になる",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "schemaId",
    "purpose",
    "recursiveDirectories",
    "requiredExactFiles",
    "allowedGeneratedInputs",
    "excludedOutputs",
    "generators",
    "commonInputs",
    "notCovered"
  ],
  "properties": {
    "schemaVersion": { "const": 1 },
    "schemaId": { "const": "trs-jack-3d-source-input-scope.v1" },
    "purpose": { "type": "string", "minLength": 1 },
    "why": { "type": "string", "minLength": 1 },

    "recursiveDirectories": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "description": "**配下のファイルは全部が入力。**ここに 1 つでもディレクトリを挙げたら、その中の未記録ファイルは MISMATCH になる",
      "items": { "type": "string", "pattern": "^[^/].*[^/]$" }
    },

    "requiredExactFiles": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "description": "**個別に必ず入力になるファイル。**source にあるのに manifest へ記録されていなければ MISMATCH",
      "items": { "type": "string", "pattern": "^[^/].*[^/]$" }
    },

    "allowedGeneratedInputs": {
      "type": "array",
      "uniqueItems": true,
      "description": "**生成物だが入力として読んでよいもの。**excludedOutputs の唯一の例外。ここを増やすときは、なぜ自己参照にならないかを書く",
      "items": { "type": "string" }
    },

    "excludedOutputs": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "description": "**入力にしてはいけないディレクトリ接頭辞。**allowedGeneratedInputs 以外がここの下から入力に記録されていたら自己参照の事故",
      "items": { "type": "string", "pattern": "^[^/].*[^/]$" }
    },
    "excludedOutputsNote": { "type": "string" },

    "generators": {
      "type": "object",
      "minProperties": 1,
      "description": "requiredExactFiles を役割別に見た射影。**別の一覧ではない**",
      "additionalProperties": {
        "type": "object",
        "additionalProperties": false,
        "required": ["schema", "generator", "usesGeneratedInputs"],
        "properties": {
          "schema": { "type": "string" },
          "generator": { "type": "string" },
          "usesGeneratedInputs": {
            "type": "boolean",
            "description": "allowedGeneratedInputs を読むか。**自分自身が出力の生成器は必ず false**"
          },
          "note": { "type": "string" }
        }
      }
    },
    "generatorsNote": { "type": "string" },

    "commonInputs": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "description": "どの生成器も読む入力。requiredExactFiles の部分集合でなければならない",
      "items": { "type": "string" }
    },
    "commonInputsNote": { "type": "string" },

    "notCovered": {
      "type": "array",
      "minItems": 1,
      "description": "**inputDigest が覆っていないもの。**空にしてはいけない——覆えないものは必ずあり、無いと書くのは嘘になる。「digest が一致した」を「全部同じだった」と読ませないための欄",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["what", "why", "consequence"],
        "properties": {
          "what": { "type": "string", "minLength": 1 },
          "why": { "type": "string", "minLength": 1 },
          "consequence": {
            "type": "string",
            "minLength": 1,
            "description": "**覆っていないことで何が起きるか。**「対象外」とだけ書くと、読み手は影響が無いと解釈する"
          }
        }
      }
    },
    "notCoveredNote": { "type": "string" }
  }
}

{
 "$schema": "http://json-schema.org/draft-07/schema#",
 "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/source-snapshot.v1.schema.json",
 "title": "trs-jack-3d source snapshot v1",
 "description": "通信が無い受け手が、inputDigest を自分で計算し直して manifest と突き合わせるための入力の写し。**これは producer の申告であって、受け手の独立検証を置き換えない。**こちらが渡したファイルを、こちらが記録した hash と照合するだけなので、**producer が両方を同時に偽れば一致する。**独立検証には GitHub の tag source archive を使うこと。",
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "schemaId",
  "generatedBy",
  "generatedAt",
  "generatedFromCommit",
  "isSelfConsistencyOnly",
  "producerClaimOnly",
  "replacesRecipientVerification",
  "isSourceOfTruthForInputDigest",
  "inputDigestSourceOfTruth",
  "whatThisProves",
  "whatThisDoesNotProve",
  "independentVerificationRecipe",
  "excluded",
  "recordedInputsTotal",
  "filesTotal",
  "files"
 ],
 "properties": {
  "schemaVersion": { "const": 1 },
  "schemaId": { "const": "trs-jack-3d-source-snapshot.v1" },
  "generatedBy": { "type": "string" },
  "generatedAt": { "type": "string" },
  "generatedFromCommit": { "type": "string", "pattern": "^([0-9a-f]{40}|UNKNOWN)$" },
  "isSelfConsistencyOnly": {
   "const": true,
   "description": "**この写しで確かめられるのは「記録した hash が、記録した中身と合っているか」だけである。**"
  },
  "producerClaimOnly": {
   "type": "string",
   "minLength": 1,
   "description": "**producer の申告であることを、artifact 自身の言葉で書く。**"
  },
  "replacesRecipientVerification": {
   "const": false,
   "description": "受け手の独立検証を置き換えない"
  },
  "isSourceOfTruthForInputDigest": {
   "const": false,
   "description": "**inputDigest の正本にしない。**正本は source-input-manifest.json のまま"
  },
  "inputDigestSourceOfTruth": { "const": "artifacts/source-input-manifest.json" },
  "whatThisProves": { "type": "string", "minLength": 1 },
  "whatThisDoesNotProve": { "type": "string", "minLength": 1 },
  "independentVerificationRecipe": {
   "type": "array",
   "minItems": 1,
   "description": "**通信がある受け手はこちらを使うこと。**tag source から取れば循環しない",
   "items": { "type": "string" }
  },
  "excluded": {
   "type": "array",
   "minItems": 1,
   "description": "**入れていないもの。**「全部入っている」と読まれないようにする",
   "items": {
    "type": "object",
    "required": ["what", "why"],
    "additionalProperties": false,
    "properties": { "what": { "type": "string" }, "why": { "type": "string" } }
   }
  },
  "recordedInputsTotal": {
   "type": "integer",
   "minimum": 1,
   "description": "source-input-manifest に載っている入力のうち、この写しに入っている件数"
  },
  "filesTotal": { "type": "integer", "minimum": 1 },
  "files": {
   "type": "array",
   "minItems": 1,
   "items": {
    "type": "object",
    "required": ["path", "sha256", "isRecordedInput", "bytes", "content"],
    "additionalProperties": false,
    "properties": {
     "path": { "type": "string", "minLength": 1 },
     "sha256": { "type": "string", "pattern": "^[0-9a-f]{64}$" },
     "isRecordedInput": {
      "type": "boolean",
      "description": "source-input-manifest に入力として載っているか。**false のものは inputDigest に入らない**（生成器・schema の読み物）"
     },
     "bytes": { "type": "integer", "minimum": 0 },
     "content": { "type": "string" }
    }
   }
  }
 }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/source-verification-result.v1.schema.json",
  "title": "trs-jack-3d source verification result v1",
  "description": "**こちらで verify:release-source-inputs を回した記録。自己申告である。**受け手の独立検証を置き換えない。判定の境界（取れなかった／合わなかった／検証していない）を受け手が読み取れるようにするためのもの",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "schemaId",
    "isSelfReport",
    "replacesRecipientVerification",
    "note",
    "tool",
    "sourceOrigin",
    "generatedFromCommit",
    "releaseCommit",
    "generatedAt",
    "status",
    "exitCode",
    "unrecordedInputDetection",
    "counts",
    "howToVerifyYourself"
  ],
  "properties": {
    "schemaVersion": { "const": 1 },
    "schemaId": { "const": "trs-jack-3d-source-verification-result.v1" },

    "isSelfReport": {
      "const": true,
      "description": "**必ず true。**この artifact が独立検証を名乗れる状況は存在しない——作った側が作った側を検証した記録だから"
    },
    "replacesRecipientVerification": {
      "const": false,
      "description": "**必ず false。**受け手が自分で回すこと。同梱の verifyReleaseSourceInputs.mjs でできる"
    },
    "note": { "type": "string", "minLength": 1 },

    "tool": {
      "type": "object",
      "additionalProperties": false,
      "required": ["script", "toolVersion", "sha256"],
      "properties": {
        "script": { "type": "string" },
        "toolVersion": { "type": "integer", "minimum": 1 },
        "sha256": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$",
          "description": "**同梱の script と同じものか受け手が確かめられるように。**違っていたら、この記録は今の道具の出力ではない"
        }
      }
    },

    "sourceOrigin": {
      "type": "string",
      "description": "何と突き合わせたか。`working-tree` は生成時の作業ツリー。**tag の source ではない**"
    },
    "generatedFromCommit": { "type": "string", "pattern": "^([0-9a-f]{40}|UNKNOWN)$" },
    "releaseCommit": {
      "type": ["string", "null"],
      "description": "**null が正しい。**artifact は自分を含む commit の hash を持てない。受け手が tag に対して回せば、その値で検証できる"
    },
    "generatedAt": { "type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$" },

    "status": {
      "type": "string",
      "enum": ["OK", "MISMATCH", "SOURCE_UNAVAILABLE", "MANIFEST_UNAVAILABLE", "NOTHING_TO_VERIFY"],
      "description": "**取れなかった (SOURCE_UNAVAILABLE) と合わなかった (MISMATCH) を潰していない。**0 件を OK にしないため NOTHING_TO_VERIFY も別にしてある。/ **この v1 では ARCHIVE_INVALID を表現できない（既知の欠け・2026-08-06 外部監査 P0-D）。**同梱の verifyReleaseSourceInputs.mjs は v5 からこの status を出す（取れたが archive が壊れているか敵対的）。enum へ足すと受理する文書が増えて言語が広がるため v2 になり、下流の lock が止まる (docs/SCHEMA_VERSIONING_POLICY.md・判定は scripts/schemaLanguageDiff.mjs で実測)。**生成器は表現できない status を近い値へ丸めず、そこで止まる** (scripts/buildReleaseEvidence.mjs)。受け手が道具を直接回した場合の stdout はこの schema の対象ではなく、ARCHIVE_INVALID がそのまま出る"
    },
    "exitCode": { "type": "integer", "enum": [0, 1, 2] },

    "unrecordedInputDetection": {
      "type": "object",
      "required": ["performed"],
      "properties": {
        "performed": {
          "type": "boolean",
          "description": "**記録漏れの探索を実行したか。**false なら「候補 0 件」ではなく「探していない」"
        },
        "scopeSource": { "type": ["string", "null"] }
      }
    },

    "counts": {
      "type": "object",
      "additionalProperties": false,
      "required": ["checked", "matched", "mismatched", "missingInSource", "unrecordedInputCandidates", "selfReferencingInputs"],
      "properties": {
        "checked": { "type": "integer", "minimum": 0 },
        "matched": { "type": "integer", "minimum": 0 },
        "mismatched": { "type": "integer", "minimum": 0 },
        "missingInSource": { "type": "integer", "minimum": 0 },
        "unrecordedInputCandidates": { "type": "integer", "minimum": 0 },
        "selfReferencingInputs": { "type": "integer", "minimum": 0 }
      }
    },

    "howToVerifyYourself": {
      "type": "array",
      "minItems": 1,
      "description": "**受け手が同じことを自分でやるための手順。**これが無いと、この artifact はただの自慢になる",
      "items": { "type": "string" }
    }
  }
}

{
 "$schema": "http://json-schema.org/draft-07/schema#",
 "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/source-verifier-cli-result.v1.schema.json",
 "title": "trs-jack-3d source verifier CLI result v1",
 "description": "同梱の verifyReleaseSourceInputs.mjs が標準出力へ書く JSON の契約。**受け手が回した結果**の形であって、こちらが回した記録（source-verification-result.v1）とは別物である。出る status が違う——作業ツリーを読む経路では archive 系が出ないため、記録側の enum を CLI の一覧として読むと取りこぼす。この schema は**実際に出るものだけ**を書く。出ない値を enum へ入れると、schema が「出うる」と嘘をつく。",
 "type": "object",
 "required": [
  "schemaVersion",
  "schemaId",
  "kind",
  "toolVersion",
  "exitCode",
  "stableReasonCode",
  "archivePolicy",
  "status",
  "manifest"
 ],
 "properties": {
  "schemaVersion": { "const": 1 },
  "schemaId": { "const": "trs-jack-3d-source-verifier-cli-result.v1" },
  "kind": { "const": "source-verifier-cli-result" },
  "toolVersion": {
   "type": "integer",
   "minimum": 16,
   "description": "この契約を名乗るのは v16 以降。**判定の意味を変えたら上げる**ので、受け手はこれで挙動を見分けられる。"
  },
  "exitCode": {
   "type": "integer",
   "enum": [0, 1, 2],
   "description": "0=OK / 1=不一致か工程未了 / 2=source・manifest を取れない、範囲の外、壊れている。**JSON を保存したあとで終了コードを復元できない**ので出力にも入れる。"
  },
  "status": {
   "type": "string",
   "enum": [
    "OK",
    "MISMATCH",
    "VERIFICATION_INCOMPLETE",
    "ARCHIVE_INVALID",
    "ARCHIVE_UNSUPPORTED",
    "SOURCE_UNAVAILABLE",
    "MANIFEST_UNAVAILABLE",
    "NOTHING_TO_VERIFY"
   ],
   "description": "**`OK` は必須の工程が全部終わったときだけ。**記録漏れの探索をしていなければ VERIFICATION_INCOMPLETE になる（v0.3.0 より前の tag はこれに当たる）。**監査の草案にある INTERNAL_ERROR は入れていない**——この道具は出さないため。出さない値を enum へ書くと、受け手が来ない分岐を実装することになる。"
  },
  "stableReasonCode": {
   "type": ["string", "null"],
   "pattern": "^[A-Z][A-Z0-9_]*$",
   "description": "止めた理由の、文章とは別の**変わらない名前**。文章は版ごとに書き換わるので、機械で分岐するならこちらを見る。`OK` / `MISMATCH` では null。欄名・型・パスの具体値は detail に入る（**欄ごとの code は作らない**）。"
  },
  "reason": { "type": "string", "description": "人が読む説明。**分岐に使わない**（版ごとに書き換わる）" },
  "detail": { "type": ["object", "null"] },
  "archivePolicy": {
   "type": "object",
   "description": "**この道具が受け入れる archive の範囲。**受け手が「何を通す道具か」を機械で読めるようにする。ここに無い形は status で止まる。",
   "required": ["acceptedHeaderFormats", "prefixUsedOnlyFor", "acceptedTypeflags", "endOfArchiveConvention", "limits"],
   "properties": {
    "acceptedHeaderFormats": {
     "type": "array",
     "items": { "type": "string", "enum": ["posix-ustar", "old-gnu", "v7", "unknown"] },
     "description": "**形式そのものは拒まない。**345..499 を prefix として読むのは POSIX ustar のときだけで、他の形式でそこが非空なら止める（読み手ごとに名前が変わるため）。"
    },
    "prefixUsedOnlyFor": { "const": "posix-ustar" },
    "acceptedTypeflags": {
     "type": "array",
     "items": { "type": "string" },
     "description": "**許可表**（除外表ではない）。載っていない型は ARCHIVE_UNSUPPORTED で止まる。"
    },
    "endOfArchiveConvention": { "type": "string" },
    "limits": { "type": "object" }
   }
  },
  "incompletePhases": {
   "type": "array",
   "items": { "type": "string" },
   "description": "**終わっていない必須工程。**空でなければ status は OK にならない。`unrecorded-input-detection`（範囲定義が無い・読めない・manifest の記録と違う）と `scope-not-pinned-to-manifest`（--allow-unpinned-scope で古い tag を検算した）が出る。"
  },
  "rootTransform": {
   "type": "object",
   "required": ["stripped"],
   "properties": {
    "stripped": {
     "type": ["string", "null"],
     "description": "剥がした先頭 1 階層の名前。GitHub の tarball は `trs-jack-3d-<sha>/` を持つ。**剥がした事実を出さないと、パスが一致したことの意味を受け手が確かめられない。**"
    }
   }
  },
  "origin": { "type": "string", "description": "source をどこから取ったか（git-archive / dir / archive / github-tarball）" },
  "networkUsed": { "type": "boolean", "description": "既定は false。--fetch github を明示したときだけ true" },
  "manifest": { "type": "string" },
  "tag": { "type": ["string", "null"] },
  "fetch": { "type": "string" },
  "selfReported": {
   "type": "object",
   "description": "**manifest がそう名乗っているだけの値。**下の independentVerification と混ぜない"
  },
  "independentVerification": {
   "type": "object",
   "description": "**この実行で計算し直した結果。**",
   "required": ["checked", "matched", "mismatched"],
   "properties": {
    "checked": { "type": "integer", "minimum": 0 },
    "matched": { "type": "integer", "minimum": 0 },
    "mismatched": { "type": "integer", "minimum": 0 },
    "missingInSource": { "type": "integer", "minimum": 0 },
    "recordedInconsistent": { "type": "integer", "minimum": 0 },
    "unrecordedInputCandidates": { "type": "integer", "minimum": 0 },
    "selfReferencingInputs": { "type": "integer", "minimum": 0 }
   }
  },
  "unrecordedInputDetection": {
   "type": "object",
   "required": ["performed"],
   "description": "**探したのか、探さなかったのか。**探していないのに候補 0 件を合格の根拠にしないため、performed を先に見る。",
   "properties": {
    "performed": { "type": "boolean" },
    "scopeSource": { "type": ["string", "null"] },
    "boundTo": {
     "type": ["string", "null"],
     "description": "範囲定義がどの記録に縛られているか。null なら manifest が範囲を記録していない古い版で、その場合 status は OK にならない。"
    },
    "scopeSha256": { "type": "string", "pattern": "^[0-9a-f]{64}$" },
    "stableReasonCode": { "type": "string", "pattern": "^[A-Z][A-Z0-9_]*$" }
   }
  },
  "mismatches": { "type": "array" },
  "unrecordedInputCandidates": { "type": "array", "items": { "type": "string" } },
  "selfReferencingInputs": { "type": "array", "items": { "type": "string" } },
  "notCoveredByDigest": {
   "type": ["array", "null"],
   "description": "範囲定義が「覆えない」と自己申告しているもの（Node の版・ロケール・環境変数など）。**一致は、これらが同じだったことを意味しない。**"
  },
  "notes": { "type": "array", "items": { "type": "string" } },
  "note": { "type": "string" }
 }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/test-counts.v1.schema.json",
  "title": "テスト件数 v1",
  "description": "npm run test:count の出力。docs/TEST_RESULTS.md の件数と機械照合し、npm run check:vacuity の下限としても使う。",
  "type": "object",
  "required": [
    "schemaVersion",
    "generatedAt",
    "note",
    "total",
    "byFile",
    "skipped",
    "allPassed",
    "failed",
    "exitCode",
    "testCommand",
    "runner",
    "runnerVersion",
    "nodeVersion",
    "generatedFromCommit"
  ],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "generatedAt": {
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
    },
    "note": {
      "type": "string"
    },
    "total": {
      "type": "integer",
      "minimum": 1
    },
    "byFile": {
      "type": "object",
      "minProperties": 1,
      "additionalProperties": {
        "type": "integer",
        "minimum": 0
      }
    },
    "skipped": {
      "type": "integer",
      "minimum": 0,
      "description": "飛ばされたテストの件数。**0 でないと check:vacuity が落ちる。** skip は「通った」ではなく「見ていない」"
    },
    "allPassed": {
      "type": "boolean"
    },
    "failed": {
      "type": "integer",
      "minimum": 0,
      "description": "**同じ実行から取る。**allPassed だけでは「なぜ false か」が残らない"
    },
    "failedSuites": {
      "type": "integer",
      "minimum": 0
    },
    "exitCode": {
      "type": "integer",
      "description": "vitest の終了コード。テストは通ったが runner が落ちた場合を区別する"
    },
    "testCommand": {
      "type": "string"
    },
    "runner": {
      "type": "string"
    },
    "runnerVersion": {
      "type": "string"
    },
    "nodeVersion": {
      "type": "string"
    },
    "generatedFromCommit": {
      "type": "string",
      "pattern": "^([0-9a-f]{40}|UNKNOWN)$"
    }
  }
}

{
 "$schema": "http://json-schema.org/draft-07/schema#",
 "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/test-counts.v2.schema.json",
