   "description": "実物の導通測定。**model sweep と同じ項目に混ぜない。**未実施の間は null"
  },
  "notes": {
   "type": "array",
   "minItems": 1,
   "items": {
    "type": "string"
   }
  },
  "windowEndConvention": {
   "const": "EXCLUSIVE",
   "description": "`endExclusiveMm` は含まない側の端。profile の `nominalEndMm` と一致する"
  },
  "contractMigration": {
   "type": "object",
   "description": "**版と契約変更の対応表。**旧語彙を読む消費側が沈黙ではなくエラーになるためのもの。判定は docs/SCHEMA_VERSIONING_POLICY.md の条文（新 schema が許す言語が旧 schema の言語に収まるか）による。**artifact の中身では判定しない**——同じ変更でも、その版の artifact が新しい値を使っているかで答えが反転してしまうため。正本は contract-migration.v1.json",
   "required": [
    "schemaId",
    "previousSchemaId",
    "fromSchemaVersion",
    "toSchemaVersion",
    "breaking",
    "policy",
    "consumerAction",
    "renamedAssets",
    "history"
   ],
   "additionalProperties": false,
   "properties": {
    "schemaId": {
     "const": "topology-robustness.v3"
    },
    "previousSchemaId": {
     "const": "topology-robustness.v2"
    },
    "fromSchemaVersion": {
     "const": 2
    },
    "toSchemaVersion": {
     "const": 3
    },
    "breaking": {
     "const": true
    },
    "policy": {
     "type": "object",
     "required": [
      "document",
      "policyVersion",
      "decisionRule"
     ],
     "additionalProperties": false,
     "properties": {
      "document": {
       "const": "docs/SCHEMA_VERSIONING_POLICY.md"
      },
      "policyVersion": {
       "type": "integer",
       "minimum": 1
      },
      "decisionRule": {
       "const": "language-subset"
      },
      "note": {
       "type": "string"
      }
     }
    },
    "consumerAction": {
     "type": "string",
     "minLength": 1
    },
    "renamedAssets": {
     "type": "array",
     "minItems": 1,
     "description": "**条文の外（第6条）。**配布名は schema の言語に現れないので、名前で引く下流は schema 検査に到達する前に「ファイルが無い」で止まる",
     "items": {
      "type": "object",
      "required": [
       "from",
       "to",
       "reason"
      ],
      "additionalProperties": false,
      "properties": {
       "from": {
        "type": "string"
       },
       "to": {
        "type": "string"
       },
       "reason": {
        "type": "string"
       }
      }
     }
    },
    "history": {
     "type": "array",
     "minItems": 1,
     "description": "**契約が変わった release を古い順に並べる。**版を据え置いたまま変えた回は versionWasHeld: true で残す。それが条文違反の記録である",
     "items": {
      "type": "object",
      "required": [
       "shippedIn",
       "previousRelease",
       "previousSchemaPath",
       "currentSchemaPath",
       "schemaVersionAtTheTime",
       "versionWasHeld",
       "policyVerdict",
       "changes"
      ],
      "additionalProperties": false,
      "properties": {
       "shippedIn": {
        "type": "string",
        "pattern": "^v[0-9]+\\.[0-9]+\\.[0-9]+$"
       },
       "previousRelease": {
        "type": "string",
        "pattern": "^v[0-9]+\\.[0-9]+\\.[0-9]+$"
       },
       "previousSchemaPath": {
        "type": "string",
        "description": "**previousRelease 時点でのこの schema のパス。**版を上げるとファイル名が変わるので、記録側に持たせないと機械で突き合わせられない"
       },
       "currentSchemaPath": {
        "type": "string"
       },
       "schemaVersionAtTheTime": {
        "type": "integer",
        "minimum": 1
       },
       "schemaVersionShouldHaveBeen": {
        "type": "integer",
        "minimum": 1,
        "description": "据え置いた回にだけ入る。**条文に照らして本来あるべきだった版**"
       },
       "versionWasHeld": {
        "type": "boolean"
       },
       "policyVerdict": {
        "enum": [
         "BUMP",
         "HOLD_RECORD",
         "HOLD"
        ]
       },
       "recordedRetroactivelyIn": {
        "type": "string",
        "pattern": "^v[0-9]+\\.[0-9]+\\.[0-9]+$",
        "description": "**いつ遡って書いたか。**当時の判断記録ではないことを隠さない"
       },
       "note": {
        "type": "string"
       },
       "changes": {
        "type": "array",
        "minItems": 1,
        "items": {
         "type": "object",
         "required": [
          "kind",
          "effect",
          "schemaPointer",
          "reason"
         ],
         "additionalProperties": false,
         "properties": {
          "kind": {
           "enum": [
            "field-added",
            "field-removed",
            "field-renamed",
            "field-reshaped",
            "enum-value-added",
            "enum-value-removed",
            "enum-value-renamed",
            "type-widened",
            "type-narrowed",
            "constraint-tightened",
            "constraint-loosened",
            "const-changed",
            "meaning-changed",
            "description-only"
           ]
          },
          "effect": {
           "enum": [
            "WIDEN",
            "NARROW",
            "NEUTRAL",
            "UNDECIDABLE"
           ],
           "description": "**scripts/schemaLanguageDiff.mjs の判定をそのまま入れる。**記録と実物がずれたらテストが落ちる"
          },
          "schemaPointer": {
           "type": "string",
           "pattern": "^/",
           "description": "**artifact ではなく schema への JSON Pointer。**実在することを機械で確かめる"
          },
          "instancePath": {
           "type": "string",
           "description": "人が読むための位置。$.a.b[].c 形式"
          },
          "added": {
           "type": "array",
           "items": {
            "type": "string"
           }
          },
          "removed": {
           "type": "array",
           "items": {
            "type": "string"
           }
          },
          "from": {
           "type": [
            "string",
            "number",
            "boolean"
           ]
          },
          "to": {
           "type": [
            "string",
            "number",
            "boolean"
           ]
          },
          "reason": {
           "type": "string",
           "minLength": 1
          }
         }
        }
       }
      }
     }
    }
   }
  }
 },
 "definitions": {
  "window": {
   "type": "object",
   "required": [
    "startMm",
    "lastSampleMm",
    "endExclusiveMm",
    "widthMm"
   ],
   "additionalProperties": false,
   "description": "**「終わり」を 2 つに分けてある。**`lastSampleMm` は観測の最後の点、`endExclusiveMm` は区間の終端",
   "properties": {
    "startMm": {
     "type": "number",
     "description": "区間の始まり。profile の nominalStartMm と一致する"
    },
    "lastSampleMm": {
     "type": "number",
     "description": "目標クラスが観測された最後の標本位置。**区間の終端ではない**"
    },
    "endExclusiveMm": {
     "type": "number",
     "description": "lastSampleMm + stepMm。**profile の nominalEndMm と一致する**"
    },
    "widthMm": {
     "type": "number",
     "exclusiveMinimum": 0,
     "description": "endExclusiveMm − startMm"
    }
   }
  }
 }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/topology-search.v1.schema.json",
  "title": "目標トポロジー探索の結果 v1",
  "description": "npm run search:topology の出力。**見つからないことも結果として保存する。** 反証を消させないための構造になっている (件数を出した分類は必ず標本も出す・廃止した集計は removedMeasures に残す)。",
  "type": "object",
  "required": [
    "schemaVersion",
    "generatedBy",
    "targetCode",
    "searchSpace",
    "representativenessDisclaimer",
    "found",
    "foundWithWorkingJack",
    "usableWitnesses",
    "realizability",
    "brokenJackWitnesses",
    "witnessCount",
    "witnessCountByVariant",
    "usableWitnessCount"
  ],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": { "const": 1 },
    "generatedBy": { "type": "string" },
    "targetCode": { "type": "string" },
    "searchSpace": {
      "type": "object",
      "required": ["variants", "axesByJack", "axesUsedPerVariant", "variantBasis", "coarseStepMm", "configurationsTried", "buildFailed"],
      "additionalProperties": false,
      "properties": {
        "variants": { "type": "array", "minItems": 1, "items": { "type": "string" } },
        "axesByJack": {
          "type": "object",
          "description": "走査軸。shipped は実行時の既定値で、check:stale がこれを現在のモデルと突き合わせる",
          "additionalProperties": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "required": ["key", "levels", "shipped"],
              "additionalProperties": false,
              "properties": {
                "key": { "type": "string" },
                "levels": { "type": "array", "minItems": 2, "items": { "type": "number" } },
                "shipped": { "type": "number" }
              }
            }
          }
        },
        "axesUsedPerVariant": {
          "type": "object",
          "additionalProperties": { "type": "array", "minItems": 1, "items": { "type": "string" } }
        },
        "variantBasis": {
          "type": "object",
          "description": "variant ごとの土台。断り書きが 1 本だと 3極×3極の話に見えてしまう",
          "additionalProperties": {
            "type": "object",
            "required": ["variantId", "basePartOrConstructedProfile", "sourceBasis", "unverifiedAssumptions", "representativenessDisclaimer"],
            "additionalProperties": false,
            "properties": {
              "variantId": { "type": "string" },
              "basePartOrConstructedProfile": { "type": "string" },
              "sourceBasis": { "type": "string" },
              "unverifiedAssumptions": { "type": "array", "items": { "type": "string" } },
              "representativenessDisclaimer": { "type": "string" }
            }
          }
        },
        "coarseStepMm": { "type": "number", "exclusiveMinimum": 0 },
        "configurationsTried": { "type": "integer", "minimum": 0 },
        "buildFailed": { "type": "integer", "minimum": 0 }
      }
    },
    "representativenessDisclaimer": { "type": "string", "minLength": 20 },
    "found": { "type": "boolean" },
    "foundWithWorkingJack": { "type": "boolean" },
    "usableWitnesses": { "$ref": "#/definitions/category" },
    "brokenJackWitnesses": { "$ref": "#/definitions/category" },
    "removedMeasures": {
      "type": "array",
      "description": "廃止した集計。**黙って消すと「前は別の数字があった」ことが分からなくなる。**",
      "items": {
        "type": "object",
        "required": ["key", "removedOn", "reason"],
        "additionalProperties": false,
        "properties": {
          "key": { "type": "string" },
          "removedOn": { "type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" },
          "reason": { "type": "string", "minLength": 40 }
        }
      }
    },
    "realizability": {
      "type": "object",
      "description": "**「作れるか」の答えではない。** モデル上どこまで絞れるかである",
      "required": ["note", "heuristic", "passesPadWidthHeuristic", "matchesCurrentNominalParameters", "counterEvidence"],
      "additionalProperties": false,
      "properties": {
        "note": { "type": "string", "minLength": 40 },
        "heuristic": {
          "type": "object",
          "required": ["name", "thresholdMm", "source", "manufacturingVerified"],
          "additionalProperties": true,
          "properties": {
            "name": { "type": "string" },
            "thresholdMm": { "type": "number", "exclusiveMinimum": 0 },
            "source": {
              "type": ["string", "null"],
              "description": "出典。**無ければ null。** 探索用の閾値であることを隠さない"
            },
            "manufacturingVerified": {
              "const": false,
              "description": "**true にできない。** 材料・応力・耐久性・成形・公差・接触圧・工程のいずれも確認していない"
            }
          }
        },
        "passesPadWidthHeuristic": { "$ref": "#/definitions/count" },
        "matchesCurrentNominalParameters": {
          "type": "object",
          "required": ["total", "byVariant", "samples"],
          "additionalProperties": false,
          "properties": {
            "total": { "type": "integer", "minimum": 0 },
            "byVariant": { "$ref": "#/definitions/byVariant" },
            "samples": { "type": "array", "items": { "$ref": "#/definitions/witness" } }
          }
        },
        "counterEvidence": {
          "type": "object",
          "description": "**反対証拠を同じ可視性で置く。** 成立件数だけを載せない",
          "required": ["note", "ref"],
          "additionalProperties": false,
          "properties": {
            "note": { "type": "string", "minLength": 40 },
            "ref": { "type": "string" }
          }
        }
      }
    },
    "witnessCount": { "type": "integer", "minimum": 0 },
    "witnessCountByVariant": { "$ref": "#/definitions/byVariant" },
    "usableWitnessCount": { "type": "integer", "minimum": 0 },
    "robustIntervalWidthMmAmongUsable": { "type": ["number", "null"] },
    "robustIntervalWidthMm": { "type": ["number", "null"] },
    "sensitivity": {
      "type": "array",
      "description": "軸ごとに、どの水準が witness に現れたか。shippedValueAppearsInWitness が false なら既定値では成立しない",
      "items": {
        "type": "object",
        "required": ["key", "shipped", "levelsTried", "valuesAmongWitnesses", "valuesAmongUsableWitnesses", "shippedValueAppearsInWitness"],
        "additionalProperties": false,
        "properties": {
          "key": { "type": "string" },
          "shipped": { "type": "number" },
          "levelsTried": { "type": "array", "minItems": 1, "items": { "type": "number" } },
          "valuesAmongWitnesses": { "type": "array", "items": { "type": "number" } },
          "valuesAmongUsableWitnesses": { "type": "array", "items": { "type": "number" } },
          "shippedValueAppearsInWitness": { "type": "boolean" }
        }
      }
    },
    "requiredAssumptions": { "type": "array", "items": { "type": ["string", "object"] } },
    "notFoundReason": { "type": ["string", "null"] }
  },
  "definitions": {
    "byVariant": {
      "type": "object",
      "additionalProperties": { "type": "integer", "minimum": 0 }
    },
    "count": {
      "type": "object",
      "required": ["total", "byVariant"],
      "additionalProperties": false,
      "properties": {
        "total": { "type": "integer", "minimum": 0 },
        "byVariant": { "$ref": "#/definitions/byVariant" }
      }
    },
    "category": {
      "type": "object",
      "description": "件数を出した分類は、必ず標本も出す。切り捨てた件数も明示する",
      "required": ["note", "total", "byVariant", "samples", "droppedFromListing"],
      "additionalProperties": false,
      "properties": {
        "note": { "type": "string" },
        "total": { "type": "integer", "minimum": 0 },
        "byVariant": { "$ref": "#/definitions/byVariant" },
        "samples": { "type": "array", "items": { "$ref": "#/definitions/witness" } },
        "droppedFromListing": { "type": "integer", "minimum": 0 }
      }
    },
    "witness": {
      "type": "object",
      "required": ["variantId", "overrides", "constructed", "evidenceGrade", "fullInsertionOk", "matchesCurrentNominalParameters", "passesPadWidthHeuristic", "windows", "robustIntervalWidthMm"],
      "additionalProperties": false,
      "properties": {
        "variantId": { "type": "string" },
        "overrides": { "type": "object", "additionalProperties": { "type": "number" } },
        "constructed": { "type": "boolean" },
        "evidenceGrade": {
          "const": "ASSUMPTION",
          "description": "**構成は実在部品ではない。** ここが FACT や DERIVED になることはない"
        },
        "fullInsertionOk": { "type": "boolean" },
        "matchesCurrentNominalParameters": { "type": "boolean" },
        "passesPadWidthHeuristic": { "type": "boolean" },
        "windows": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["fromMm", "toMm"],
            "additionalProperties": false,
            "properties": { "fromMm": { "type": "number" }, "toMm": { "type": "number" } }
          }
        },
        "robustIntervalWidthMm": { "type": "number", "minimum": 0 }
      }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://github.com/Driedsandwich/trs-jack-3d/schemas/trs-jack-3d-release-index.v1.schema.json",
  "title": "trs-jack-3d release index v1",
  "description": "release asset の索引。**下流が報告文から値を手で転記しなくて済むようにするためのもの。**v0.2.0 では下流が lock を手入力で作っており、転記ミスの余地があった",
  "type": "object",
  "required": [
    "schemaVersion",
    "releaseTag",
    "artifactGenerationCommit",
    "artifactGenerationCommits",
    "profileSchemaVersion",
    "profileSchemaId",
    "profiles",
    "assets",
    "notes",
    "evidenceBuiltAtCommit",
    "releaseCommit"
  ],
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "generatedBy": {
      "type": "string"
    },
    "generatedAt": {
      "type": "string",
      "pattern": "^\\d{4}-\\d{2}-\\d{2}$"
    },
    "releaseTag": {
      "oneOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "description": "**null なら未 tag。**evidence をコミットしてから tag を打つので、生成時点では知りようがない"
    },
    "releaseCommit": {
      "oneOf": [
        {
          "type": "string",
          "pattern": "^([0-9a-f]{40}|UNKNOWN)$"
        },
        {
          "type": "null"
        }
      ],
      "description": "**null なら未 tag。**RELEASE_COMMIT で渡されたときだけ入る"
    },
    "artifactGenerationCommit": {
      "type": "string",
      "pattern": "^([0-9a-f]{40}|UNKNOWN)$",
      "description": "**profile の生成 commit。**下流の lock が既定で照合する値。全 artifact が同じ commit で生成されるとは限らないので、正確には artifactGenerationCommits を見ること"
    },
    "artifactGenerationCommits": {
      "type": "array",
      "minItems": 1,
      "description": "**生成 commit は 1 つではない。**release 工程が 2 段階のため、profile と感度・頑健性で違う",
      "items": {
        "type": "object",
        "required": [
          "commit",
          "assets"
        ],
        "additionalProperties": false,
        "properties": {
          "commit": {
            "type": "string",
            "pattern": "^([0-9a-f]{40}|UNKNOWN)$"
          },
          "assets": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "string"
            }
          }
        }
      }
    },
    "profileSchemaVersion": {
      "type": "integer",
      "minimum": 1
    },
    "profileSchemaId": {
      "type": "string"
    },
    "profiles": {
      "type": "object",
      "minProperties": 1,
      "additionalProperties": {
        "type": "object",
        "required": [
          "filename",
          "profileId",
          "inputDigest",
          "sha256",
          "generatedFromCommit",
          "sensitivityAsset"
        ],
        "additionalProperties": false,
        "properties": {
          "filename": {
            "type": "string"
          },
          "profileId": {
            "type": "string"
          },
          "inputDigest": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$"
          },
          "sha256": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$"
          },
          "generatedFromCommit": {
            "type": "string",
            "pattern": "^([0-9a-f]{40}|UNKNOWN)$"
          },
          "sensitivityAsset": {
            "type": "object",
            "required": [
              "filename",
              "sha256",
              "inputDigest",
              "generatedFromCommit"
            ],
            "additionalProperties": false,
            "properties": {
              "filename": {
                "type": "string"
              },
              "sha256": {
                "type": "string",
                "pattern": "^[0-9a-f]{64}$"
              },
              "inputDigest": {
                "type": "string",
                "pattern": "^[0-9a-f]{64}$"
              },
              "generatedFromCommit": {
                "type": "string",
                "pattern": "^([0-9a-f]{40}|UNKNOWN)$"
              }
            }
          }
        }
      }
    },
    "assets": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "filename",
          "sha256",
          "role"
        ],
        "additionalProperties": false,
        "properties": {
          "filename": {
            "type": "string",
            "description": "**配布名。契約の一部である。**下流の lock はこれでファイルを引く"
          },
          "sha256": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$"
          },
          "role": {
            "type": "string"
          },
          "generatedFromCommit": {
            "type": "string",
            "pattern": "^([0-9a-f]{40}|UNKNOWN)$",
            "description": "**この asset を生成した commit。asset ごとに違いうる。**release commit と混同しないこと"
          },
          "inputDigest": {
            "type": "string",
            "pattern": "^[0-9a-f]{64}$",
            "description": "入力の指紋。固定にはこちらを使う"
          },
          "profileId": {
            "type": "string"
          }
        }
      },
      "description": "**この索引自身は含まない**（自己参照になる）。索引の sha256 は SHA256SUMS が持つ"
    },
    "notes": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string"
      }
    },
    "evidenceBuiltAtCommit": {
      "type": "string",
      "pattern": "^([0-9a-f]{40}|UNKNOWN)$",
      "description": "この索引を作った時点の HEAD"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
