/**
 * release に同梱する「検証の証拠」を作る。
 *   npm run release:evidence
 *
 * ## 何を解くのか（非阻害フォローアップ P2-7 / P2-8）
 *
 * v0.1.1 の release asset だけを受け取った側は、次を確かめられなかった。
 *
 *   - こちらで意味規則が通っているのか（`validate:profiles` の結果が入っていない）
 *   - `provenance.inputFiles[].sha256` が tag source の実ファイルと一致するのか
 *   - **tag 時点のテスト件数**（`test_counts.json` が入っておらず、
 *     報告の 260 件が tag の 258 件なのか main の値なのかを判別できなかった）
 *
 * どれも「こちらは知っているが渡していない」だけだった。渡す。
 *
 * ## 作るもの
 *
 *   artifacts/validation-results.json   … 検証の結果（判定は validateProfiles と同一実装）
 *   artifacts/source-input-manifest.json … 全 artifact の入力ファイルの和集合と sha256
 */

import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import Ajv from 'ajv'
import { validateAll } from './validateProfiles.mjs'
import { RELEASE_ASSETS, SOURCE_ONLY_TARGETS } from './releaseAssets.mjs'
import { migrationFor } from './contractMigration.mjs'
import { buildSourceSnapshot } from './buildSourceSnapshot.mjs'

const ROOT = process.cwd()
const read = (p) => JSON.parse(readFileSync(resolve(ROOT, p), 'utf8'))
const sha256File = (p) => createHash('sha256').update(readFileSync(resolve(ROOT, p))).digest('hex')

/**
 * 入力の範囲定義（v0.3.0 フォローアップ P1-2）。
 * `scripts/provenance.ts` と `scripts/verifyReleaseSourceInputs.mjs` が読むのと同じファイル。
 * **無ければ止める。**範囲を書かずに evidence を作ると、受け手は記録漏れを確かめられない。
 */
const INPUT_SCOPE_FILE = 'source-input-scope.v1.json'
if (!existsSync(resolve(ROOT, INPUT_SCOPE_FILE))) {
  console.log(`**${INPUT_SCOPE_FILE} が無い。**入力の範囲を書けないので evidence を作らない。`)
  process.exit(1)
}
const inputScope = JSON.parse(readFileSync(resolve(ROOT, INPUT_SCOPE_FILE), 'utf8'))

/** 検証を回した記録の置き場（v0.3.0 フォローアップ P1-3） */
const SOURCE_VERIFICATION_PATH = 'artifacts/source-verification-result.json'
const ARTIFACT_DATE = process.env.ARTIFACT_DATE ?? new Date().toISOString().slice(0, 10)

const git = (args) => {
  try {
    return execFileSync('git', args, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim()
  } catch {
    return 'UNKNOWN'
  }
}

/**
 * ## 生成の順番には理由がある
 *
 * 1. `source-input-manifest.json` を書く
 * 2. `trs-jack-3d-release-index.v1.json` を書く
 * 3. その 2 つを含めて `validateAll()` を回す
 * 4. `validation-results.json` を書く
 *
 * **`validation-results.json` を検証対象に入れていないのは、自分自身を記述できないからである。**
 * 対象に入れると、書かれる内容が「一つ前の自分」を指し、1 回の実行では収束しない。
 * 代わりに、書いた直後にその schema で検証して、通らなければ止める（下）。
 * 索引も同じ理由で対象外にしている（索引は他 asset の sha256 を持つので、自分の分は持てない）。
 *
 * ---------------------------------------------------------------------------
 * 1. 入力ファイルの一覧（tag source と突き合わせるためのもの）
 * ---------------------------------------------------------------------------
 */

/**
 * 全 artifact の `provenance.inputFiles` を集める。
 *
 * **同じパスが違う sha256 で現れたら、それは事故である。**
 * artifact ごとに生成時点がずれていて、片方が古い入力から作られている。
 * 黙って先勝ちにせず、両方を残して `consistent: false` を立てる。
 */
const byPath = new Map()
for (const { path } of RELEASE_ASSETS) {
  if (!existsSync(resolve(ROOT, path))) continue
  let a
  try {
    a = read(path)
  } catch {
    continue
  }
  for (const f of a.provenance?.inputFiles ?? []) {
    const e = byPath.get(f.path) ?? { path: f.path, role: f.role, recordedSha256: new Set(), consumedBy: [] }
    e.recordedSha256.add(f.sha256)
    e.consumedBy.push(path)
    byPath.set(f.path, e)
  }
}

const inputs = [...byPath.values()]
  .sort((a, b) => a.path.localeCompare(b.path))
  .map((e) => {
    const recorded = [...e.recordedSha256]
    const actual = existsSync(resolve(ROOT, e.path)) ? sha256File(e.path) : null
    return {
      path: e.path,
      role: e.role,
      recordedSha256: recorded.length === 1 ? recorded[0] : recorded,
      consistentAcrossArtifacts: recorded.length === 1,
      actualSha256AtBuild: actual,
      matchesWorkingTree: actual !== null && recorded.length === 1 && recorded[0] === actual,
      consumedBy: e.consumedBy.sort(),
    }
  })

const inconsistent = inputs.filter((x) => !x.consistentAcrossArtifacts)
const mismatched = inputs.filter((x) => !x.matchesWorkingTree)

const manifest = {
  schemaVersion: 2,
  contractMigration: migrationFor('source-input-manifest.v2'),
  generatedBy: 'npm run release:evidence',
  generatedAt: ARTIFACT_DATE,
  generatedFromCommit: git(['rev-parse', 'HEAD']),
  purpose:
    'release asset の provenance.inputFiles[].sha256 を、tag source の実ファイルと独立に検算するための一覧。'
    + '**この manifest 自身は証明ではない。**GitHub の tag source archive を取得して、'
    + 'ここに並ぶ path の sha256 を自分で計算し、突き合わせること。',
  inputFilesTotal: inputs.length,
  inconsistentAcrossArtifacts: inconsistent.length,
  mismatchedWithWorkingTreeAtBuild: mismatched.length,
  /**
   * **この一覧が「全部」なのかを受け手が確かめるための範囲（v0.3.0 フォローアップ P1-2）。**
   *
   * 件数と sha256 だけ渡しても、受け手は**記録漏れを見つけられない。**
   * 落ちている入力があっても、残った分は全部一致するからである。
   * 範囲を一緒に渡せば、受け手は自分の source を歩いて「載っていない入力」を自分で探せる。
   *
   * `notCovered` は **digest が覆えないもの**。「一致した」を「全部同じだった」と読ませない。
   */
  inputScope: {
    file: INPUT_SCOPE_FILE,
    sha256: sha256File(INPUT_SCOPE_FILE),
    recursiveDirectories: inputScope.recursiveDirectories,
    requiredExactFiles: inputScope.requiredExactFiles,
    allowedGeneratedInputs: inputScope.allowedGeneratedInputs,
    excludedOutputs: inputScope.excludedOutputs,
    notCovered: inputScope.notCovered,
    verifyCommand:
      `node scripts/verifyReleaseSourceInputs.mjs --manifest source-input-manifest.json --source <dir> --scope ${INPUT_SCOPE_FILE}`,
  },
  inputFiles: inputs,
  verificationRecipe: [
    'gh release download <tag>  # asset を取る',
    'git archive --format=tar <tag> | tar -x -C <dir>  # tag source を取る',
    'cd <dir> && while read -r sha path; do echo "$sha  $path"; done < <(jq -r \'.inputFiles[] | "\\(.recordedSha256) \\(.path)"\' source-input-manifest.json) | shasum -a 256 -c -',
  ],
  note:
    '**mismatchedWithWorkingTreeAtBuild が 0 でない場合、その artifact は現在の入力から作り直されていない。**'
    + 'release を作る前に該当の生成コマンドを回すこと（npm run check:stale が判定する）。',
}

writeFileSync(resolve(ROOT, 'artifacts/source-input-manifest.json'), JSON.stringify(manifest, null, 1) + '\n')

/**
 * **写しは manifest の直後に作る。**
 * 写しは manifest の入力一覧を読み、index は写しの sha256 を読むので、
 * この順でないと片方が必ず古いものを見る（実測で ENOENT になった）。
 */
buildSourceSnapshot(ROOT)

// ---------------------------------------------------------------------------
// 2. 検証を実際に回した記録（v0.3.0 フォローアップ P1-3）
//
// **これは自己申告である。**作った側が作った側を検証した記録でしかない。
// それでも配る理由は、**判定の境界を受け手に見せるため**——
// 「取れなかった」「合わなかった」「そもそも探していない」が別物であることは、
// 実際の出力を 1 つ見るのがいちばん早い。
//
// 突き合わせ先は**作業ツリー**であって tag の source ではない。
// tag はこの時点でまだ存在しない（evidence をコミットしてから打つ）ので、
// 原理的にここでは検証できない。受け手が同梱の script を tag に対して回すこと。
// ---------------------------------------------------------------------------

const VERIFIER = 'scripts/verifyReleaseSourceInputs.mjs'
let verifyOut
try {
  verifyOut = JSON.parse(execFileSync('node', [
    VERIFIER,
    '--manifest', 'artifacts/source-input-manifest.json',
    '--source', '.',
    '--scope', INPUT_SCOPE_FILE,
  ], { cwd: ROOT, encoding: 'utf8', maxBuffer: 1 << 28 }))
} catch (e) {
  // **落ちても JSON は出る。**status を握りつぶさずそのまま記録する
  verifyOut = JSON.parse(String(e.stdout ?? '{}'))
  if (!verifyOut.status) {
    console.log(`\n  **${VERIFIER} が JSON を出さずに失敗した。**`)
    console.log(`    ${String(e.message).split('\n')[0]}`)
    process.exit(1)
  }
}

const EXIT_OF = { OK: 0, MISMATCH: 1, SOURCE_UNAVAILABLE: 2, MANIFEST_UNAVAILABLE: 2, NOTHING_TO_VERIFY: 2 }

/**
 * **道具が出した status を、この自己申告 artifact が表現できるか。**（外部監査 2026-08-06 P0-D）
 *
 * `verifyReleaseSourceInputs.mjs` は v5 から `ARCHIVE_INVALID` を出すが、
 * 同梱している `source-verification-result.v1.schema.json` の enum には入っていない
 * （**入れると言語が広がって v2 になり、下流が止まる**ので v0.6.x では入れていない
 * → `docs/SCHEMA_VERSIONING_POLICY.md`・判定は `schemaLanguageDiff.mjs` で実測済み）。
 *
 * **表現できない status を、近い値へ丸めて出すことは絶対にしない。**
 * 丸めると「archive が壊れていた」が「取れなかった」に化けて、受け手が読み分けられなくなる。
 * ここで止めて、**版を上げるかどうかを人が決める。**
 */
const STATUS_EXPRESSIBLE_IN_V1 = new Set(['OK', 'MISMATCH', 'SOURCE_UNAVAILABLE', 'MANIFEST_UNAVAILABLE', 'NOTHING_TO_VERIFY'])
if (!STATUS_EXPRESSIBLE_IN_V1.has(verifyOut.status)) {
  console.error(
    `\n  ✗ 検算ツールが status=${verifyOut.status} を返したが、`
    + 'source-verification-result.v1 はこの値を表現できない。\n'
    + '    **別の値へ丸めて出さない。**schema を v2 へ上げるか（＝下流が止まる。要判断）、\n'
    + '    archive のほうを直してから作り直すこと。\n'
    + `    理由: ${verifyOut.reason ?? '(なし)'}\n`,
  )
  process.exit(1)
}
const iv = verifyOut.independentVerification ?? {}
const sourceVerification = {
  schemaVersion: 1,
  schemaId: 'trs-jack-3d-source-verification-result.v1',
  isSelfReport: true,
  replacesRecipientVerification: false,
  note:
    '**これは自己申告である。**こちらのリポジトリで verify:release-source-inputs を回した結果でしかなく、'
    + '受け手の独立検証を置き換えない。**突き合わせ先は生成時の作業ツリーであって tag の source ではない。**'
    + 'tag は evidence をコミットした後に打つので、この時点では存在しない。'
    + '受け手は同梱の verifyReleaseSourceInputs.mjs を tag に対して回すこと（howToVerifyYourself を参照）。',
  tool: { script: VERIFIER, toolVersion: verifyOut.toolVersion ?? null, sha256: sha256File(VERIFIER) },
  sourceOrigin: verifyOut.origin ?? 'unknown',
  generatedFromCommit: git(['rev-parse', 'HEAD']),
  /** **null が正しい。**artifact は自分を含む commit の hash を持てない（索引の releaseCommit と同じ理由） */
  releaseCommit: null,
  generatedAt: ARTIFACT_DATE,
  status: verifyOut.status,
  exitCode: EXIT_OF[verifyOut.status] ?? 2,
  unrecordedInputDetection: {
    performed: verifyOut.unrecordedInputDetection?.performed ?? false,
    scopeSource: verifyOut.unrecordedInputDetection?.scopeSource ?? null,
  },
  counts: {
    checked: iv.checked ?? 0,
    matched: iv.matched ?? 0,
    mismatched: iv.mismatched ?? 0,
    missingInSource: iv.missingInSource ?? 0,
    unrecordedInputCandidates: iv.unrecordedInputCandidates ?? 0,
    selfReferencingInputs: iv.selfReferencingInputs ?? 0,
  },
  howToVerifyYourself: [
    '# bundle に同梱してある script をそのまま使う（通信しない）',
    'node verifyReleaseSourceInputs.mjs --manifest source-input-manifest.json --source <展開した source> --scope source-input-scope.v1.json',
    '# 手元に tag があるなら（これも通信しない）',
    'node verifyReleaseSourceInputs.mjs --manifest source-input-manifest.json --tag <tag> --scope source-input-scope.v1.json',
    '# 明示したときだけ GitHub から source を取る',
    'node verifyReleaseSourceInputs.mjs --manifest source-input-manifest.json --tag <tag> --fetch github --scope source-input-scope.v1.json',
    '# status は OK(0) / MISMATCH(1) / SOURCE_UNAVAILABLE(2) / MANIFEST_UNAVAILABLE(2) / NOTHING_TO_VERIFY(2)。',
    '# **取れなかった(2) と 合わなかった(1) を同じ失敗に潰さないこと。**',
    '# **unrecordedInputDetection.performed が false なら「候補 0 件」ではなく「探していない」。**',
  ],
}
writeFileSync(resolve(ROOT, SOURCE_VERIFICATION_PATH), JSON.stringify(sourceVerification, null, 1) + '\n')

// ---------------------------------------------------------------------------
// 4. 検証結果 — 上の 2 つを含めて回す
// ---------------------------------------------------------------------------

const shippedPaths = new Set(RELEASE_ASSETS.map((a) => a.path))
const sourceOnly = new Set(SOURCE_ONLY_TARGETS.map((t) => t.path))
const results = validateAll()
const failed = results.filter((r) => r.missing || r.schemaErrors.length || r.semanticErrors.length)

/**
 * **schema 検証と「配ってよいか」を別の名前で出す（v0.4.1・P0-2）。**
 *
 * v0.4.0 では `validation-results.json` が 11/11 PASS でありながら、
 * `test_counts.json` は `allPassed: false` だった。**両者を突き合わせていなかった。**
 * artifact の形が正しいことと、release として出してよいことは別の判定である。
 */
const tcPath = 'artifacts/test_counts.json'
const tc = existsSync(resolve(ROOT, tcPath)) ? read(tcPath) : null
const readinessReasons = []
if (failed.length) readinessReasons.push(`validate:profiles が ${failed.length} 件不適合`)
if (!tc) readinessReasons.push(`${tcPath} が無い`)
else {
  if (tc.allPassed !== true) readinessReasons.push(`${tcPath} の allPassed が ${JSON.stringify(tc.allPassed)}`)
  if (tc.failed !== undefined && tc.failed !== 0) readinessReasons.push(`${tcPath} の failed が ${tc.failed}`)
  if (tc.exitCode !== undefined && tc.exitCode !== 0) readinessReasons.push(`${tcPath} の exitCode が ${tc.exitCode}`)
}

const validation = {
  schemaVersion: 2,
  contractMigration: migrationFor('validation-results.v2'),
  generatedBy: 'npm run release:evidence',
  generatedAt: ARTIFACT_DATE,
  generatedFromCommit: git(['rev-parse', 'HEAD']),
  command: 'npm run validate:profiles',
  targetsTotal: results.length,
  targetsPassed: results.length - failed.length,
  allPassed: failed.length === 0,
  /** artifact の**形と意味**が正しいか。テストの成否とは別 */
  artifactValidationStatus: failed.length === 0 ? 'PASS' : 'FAIL',
  /**
   * **release として配ってよいか。**形の検証に加えて、テストが通っていることまで見る。
   * `npm run release:stage` がこれを門にする。
   */
  releaseReadinessStatus: readinessReasons.length === 0 ? 'READY' : 'NOT_READY',
  releaseReadinessReasons: readinessReasons,
  testEvidence: tc
    ? { total: tc.total, failed: tc.failed ?? null, skipped: tc.skipped, exitCode: tc.exitCode ?? null, allPassed: tc.allPassed }
    : null,
  /** **配布する対象と、しない対象を分けて数える（v0.2.0 フォローアップ §3）。** */
  distributedTargets: results.filter((r) => shippedPaths.has(r.artifact)).length,
  sourceOnlyTargets: results.filter((r) => !shippedPaths.has(r.artifact)).length,
  results: results.map((r) => ({
    artifact: r.artifact,
    schema: r.schema,
    missing: r.missing,
    /** **bundle に入っているか。**受け手が「全対象を独立再検証できる」と読まないようにする */
    distribution: shippedPaths.has(r.artifact) ? 'RELEASE_ASSET' : 'SOURCE_ONLY',
    schemaErrorCount: r.schemaErrors.length,
    semanticErrorCount: r.semanticErrors.length,
    schemaErrors: r.schemaErrors,
    semanticErrors: r.semanticErrors,
  })),
  note:
    '**この結果は生成時点のこのリポジトリでの判定である。**受け手の環境で同じ判定になることは、'
    + '同梱の schema で自分で検証して確かめること。判定の実装は scripts/validateProfiles.mjs にある。'
    + '**distribution: SOURCE_ONLY の対象は bundle に入っていない**ので、受け手はそれを再検証できない。',
}
writeFileSync(resolve(ROOT, 'artifacts/validation-results.json'), JSON.stringify(validation, null, 1) + '\n')

// ---------------------------------------------------------------------------
// 4. release index — 下流が値を手で転記しないで済むようにする
//
// **validation-results.json より後に作る。**索引は全 asset の sha256 を持つので、
// 先に作ると「一つ前の validation-results」を指したまま固まる（2026-08-03 に実際に踏んだ）。
// ---------------------------------------------------------------------------

const readIf = (p) => (existsSync(resolve(ROOT, p)) ? read(p) : null)
const profileEntries = {}
for (const [variantFile, sensFile] of [
  ['artifacts/half_plug_topology_profile.v3.trs_jack_trs.json', 'artifacts/sensitivity.trs_jack_trs.json'],
  ['artifacts/half_plug_topology_profile.v3.trs_jack_trrs.json', 'artifacts/sensitivity.trs_jack_trrs.json'],
]) {
  const prof = readIf(variantFile)
  const sens = readIf(sensFile)
  if (!prof || !sens) continue
  profileEntries[prof.variantId] = {
    filename: variantFile.split('/').pop(),
    profileId: prof.profileId,
    inputDigest: prof.provenance.inputDigest,
    sha256: sha256File(variantFile),
    generatedFromCommit: prof.provenance.generatedFromCommit,
    sensitivityAsset: {
      filename: sensFile.split('/').pop(),
      sha256: sha256File(sensFile),
      inputDigest: sens.provenance.inputDigest,
      generatedFromCommit: sens.provenance.generatedFromCommit,
    },
  }
}

const INDEX_PATH = 'artifacts/trs-jack-3d-release-index.v1.json'
const assets = RELEASE_ASSETS
  .filter((a) => a.path !== INDEX_PATH) // **索引は自分を含めない**（自己参照になる）
  .map((a) => {
    const e = { filename: a.path.split('/').pop(), sha256: sha256File(a.path), role: a.role }
    const j = a.path.endsWith('.json') && a.path.startsWith('artifacts/') ? readIf(a.path) : null
    const gc = j?.provenance?.generatedFromCommit ?? j?.generatedFromCommit
    if (gc) e.generatedFromCommit = gc
    if (j?.provenance?.inputDigest) e.inputDigest = j.provenance.inputDigest
    if (j?.profileId) e.profileId = j.profileId
    return e
  })
  .sort((a, b) => a.filename.localeCompare(b.filename))

/**
 * **生成 commit は 1 つではない。**release 工程が 2 段階なので、
 * profile と 感度・頑健性 は別の commit で作られる。
 * 単一の `artifactGenerationCommit` だけを見ると、片方が必ず食い違う。
 */
const byCommit = new Map()
for (const a of assets) {
  if (!a.generatedFromCommit) continue
  byCommit.set(a.generatedFromCommit, [...(byCommit.get(a.generatedFromCommit) ?? []), a.filename])
}
const someProfile = Object.values(profileEntries)[0]

const index = {
  schemaVersion: 1,
  generatedBy: 'npm run release:evidence',
  generatedAt: ARTIFACT_DATE,
  /**
   * **tag はこの時点では存在しない。**evidence を作り、それをコミットし、そのうえで tag を打つ。
   * 分からないものを埋めない。release 時に RELEASE_TAG / RELEASE_COMMIT で渡す。
   */
  releaseTag: process.env.RELEASE_TAG ?? null,
  releaseCommit: process.env.RELEASE_COMMIT ?? null,
  evidenceBuiltAtCommit: git(['rev-parse', 'HEAD']),
  artifactGenerationCommit: someProfile?.generatedFromCommit ?? git(['rev-parse', 'HEAD']),
  artifactGenerationCommits: [...byCommit.entries()]
    .map(([commit, list]) => ({ commit, assets: list.sort() }))
    .sort((a, b) => a.commit.localeCompare(b.commit)),
  profileSchemaVersion: someProfile ? readIf('artifacts/half_plug_topology_profile.v3.trs_jack_trs.json').schemaVersion : 2,
  profileSchemaId: someProfile ? readIf('artifacts/half_plug_topology_profile.v3.trs_jack_trs.json').schemaId : null,
  profiles: profileEntries,
  assets,
  notes: [
    '**この索引は release 工程の記録であって、証明ではない。**bytes の検算は SHA256SUMS で行うこと。',
    '**`releaseTag` / `releaseCommit` が null なら、まだ tag を打っていない。**'
      + 'evidence をコミットしてから tag を打つ順序なので、生成時点では知りようがない。'
      + '配布物には RELEASE_TAG / RELEASE_COMMIT を渡して作り直したものを入れること（release:stage が null を拒む）。',
    '**`releaseCommit` と `artifactGenerationCommit` は違う。**tag は artifact をコミットした後に打つので、'
      + 'artifact 自身は必ずそれより前の commit から作られる。一致を要求しないこと。',
    '**生成 commit は 1 つではない**（`artifactGenerationCommits` を見ること）。'
      + 'release 工程が 2 段階で、profile の入力に感度 artifact が含まれるため、先に感度を確定させる必要がある。',
    '**この索引自身の sha256 はここに無い**（自己参照になる）。SHA256SUMS が持っている。',
  ],
}
writeFileSync(resolve(ROOT, INDEX_PATH), JSON.stringify(index, null, 1) + '\n')

// --- 自分で書いた 2 つは、書いた直後に schema で検証する -----------------------
// 検証対象に入れられない（自己参照になる）ので、ここで見る。**黙って通さない。**
const ajv = new Ajv({ allErrors: true, strict: false })
let selfBad = 0
for (const [artifactPath, schemaPath] of [
  ['artifacts/validation-results.json', 'schemas/validation-results.v2.schema.json'],
  [INDEX_PATH, 'schemas/trs-jack-3d-release-index.v1.schema.json'],
  // 検証を回した記録も同じ扱い。**validateAll の対象に入れると、その回の自分自身を見ることになる**
  [SOURCE_VERIFICATION_PATH, 'schemas/source-verification-result.v1.schema.json'],
]) {
  const v = ajv.compile(read(schemaPath))
  if (!v(read(artifactPath))) {
    selfBad++
    console.log(`\n  **${artifactPath} が ${schemaPath} に適合しない**`)
    for (const e of (v.errors ?? []).slice(0, 8)) console.log(`    ${e.instancePath || '(root)'}: ${e.keyword} — ${e.message}`)
  }
}

// ---------------------------------------------------------------------------

console.log(`\n  validation-results.json     ${validation.targetsPassed}/${validation.targetsTotal} 適合`
  + ` (配布 ${validation.distributedTargets} / 非配布 ${validation.sourceOnlyTargets})`)
console.log(`  source-input-manifest.json  入力 ${inputs.length} 件`)
console.log(`  source-verification-result  ${sourceVerification.status}`
  + ` (検算 ${sourceVerification.counts.checked} 件 / 記録漏れ探索 ${sourceVerification.unrecordedInputDetection.performed ? '実行' : '**未実行**'})`
  + ' — **自己申告**')
console.log(`  release-index               asset ${assets.length} 件 / 生成 commit ${index.artifactGenerationCommits.length} 種`)
console.log(`  artifactValidation          ${validation.artifactValidationStatus}`)
console.log(`  releaseReadiness            ${validation.releaseReadinessStatus}`)
if (inconsistent.length) console.log(`  **artifact 間で sha256 が食い違う入力が ${inconsistent.length} 件**`)
if (mismatched.length) console.log(`  **作業ツリーと一致しない入力が ${mismatched.length} 件** (作り直しが要る)`)
if (!validation.allPassed) {
  console.log('\n**検証が通っていない。release evidence としては使えない。**')
  process.exit(1)
}
if (inconsistent.length || mismatched.length) process.exit(1)
if (selfBad) {
  console.log('\n**自分で書いた evidence が schema に適合しない。**')
  process.exit(1)
}
/**
 * **ここで止めない（v0.4.1・P0-2）。**
 *
 * テストが落ちていることを理由に evidence の生成を止めると、
 * 「件数の照合が落ちている間は件数を更新できない」という循環に戻る。
 * evidence には `releaseReadinessStatus: NOT_READY` と理由が入っているので、
 * **止めるのは配布側**（`npm run release:stage` が拒否する）。
 */
if (validation.releaseReadinessStatus !== 'READY') {
  console.log('\n**release として配れる状態ではない。**')
  for (const r of validation.releaseReadinessReasons) console.log(`  ${r}`)
  console.log('  evidence は書いた（判定を残すため）。**npm run release:stage が拒否する。**')
} else {
  console.log('  すべて整合している')
}

/**
 * 通信が無い受け手のための、入力・生成器・schema の写しを作る。
 *   npm run release:snapshot
 *
 * ## なぜ要るか（v0.4.1 フォローアップ オーダー §2）
 *
 * v0.4.1 の受け手はネットワークが無く、`--fetch github` も
 * release ページの "Source code (tar.gz)" も取れず `SOURCE_UNAVAILABLE` になった。
 * 判定としては正しい（取れなかったことを不一致に潰していない）が、
 * **完全にオフラインの受け手は独立検算に着手できない。**
 *
 * ## なぜ tag source archive をそのまま添付しないか
 *
 * 実測した。
 *
 *   入力 29 件だけ                     0.45 MB
 *   入力 + scripts/ + schemas/         0.92 MB  ← これ
 *   tag source archive まるごと        8.94 MB
 *
 * 8.94 MB の内訳を見ると、増えるぶんは **docs/screenshots/*.png（1 枚 0.6〜0.7 MB）と
 * artifacts/contact_sweep.json（1.3 MB）** で、どれも受け手の検証には使われない。
 *
 * ## なぜ tar.gz ではなく JSON か
 *
 * **tar.gz は同じ入力から作っても毎回ハッシュが変わる**（mtime が入る。実測で不一致）。
 * release asset は sha256 で固定するので、再現しない形式は使えない。
 * JSON なら決定的で、schema で検証でき、限界を artifact 自身に書ける。
 *
 * ## これで何が言えて、何が言えないか
 *
 * 言える  : 記録した hash が、記録した中身と合っているか（自己整合）
 * 言えない: その中身が本当に tag の source かどうか
 *
 * **producer が写しと manifest を同時に偽れば一致する。**循環しない検証には
 * GitHub の tag source archive を使うこと（`independentVerificationRecipe` に手順）。
 */

import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const OUT = 'artifacts/source-snapshot.v1.json'
const MANIFEST = 'artifacts/source-input-manifest.json'
const ARTIFACT_DATE = process.env.ARTIFACT_DATE ?? new Date().toISOString().slice(0, 10)

const git = (root, args) => {
  try {
    return execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim()
  } catch {
    return 'UNKNOWN'
  }
}

/** 写しに入れる範囲。**入力だけでなく生成器と schema も入れる**（hash が何を指すか辿れるように） */
const RECURSIVE_DIRS = ['scripts', 'schemas', 'src/data', 'src/model']
const BASE_EXACT_FILES = ['source-input-scope.v1.json', 'contract-migration.v1.json', 'package.json', 'package-lock.json']

/**
 * **範囲定義が「生成物だが入力でもある」と認めた 3 件を足す。**
 * profile は感度 artifact を実際に読むので、これが無いと受け手は inputDigest を再計算できない。
 * 一覧を直書きせず範囲定義から引く（生成側と同じ 1 か所）。
 */
const exactFiles = (root) => {
  const scopePath = resolve(root, 'source-input-scope.v1.json')
  const scope = JSON.parse(readFileSync(scopePath, 'utf8'))
  return [...BASE_EXACT_FILES, ...(scope.allowedGeneratedInputs ?? [])]
}

const walk = (ROOT, dir) => {
  const out = []
  for (const e of readdirSync(resolve(ROOT, dir), { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : 1))) {
    const p = `${dir}/${e.name}`
    if (e.isDirectory()) out.push(...walk(ROOT, p))
    else if (e.isFile()) out.push(p)
  }
  return out
}

/** 写しを作って書き出す。**問題があれば例外で落とす**（黙って空の写しを作らない） */
export function buildSourceSnapshot(ROOT = process.cwd()) {
// --- 入力の正本を読む。**無ければ止める**（何件入るはずかを言えないまま作らない） ---
if (!existsSync(resolve(ROOT, MANIFEST))) {
  throw new Error(`${MANIFEST} が無い。先に npm run release:evidence を回すこと`)
}
const manifest = JSON.parse(readFileSync(resolve(ROOT, MANIFEST), 'utf8'))
const recordedInputs = new Set((manifest.inputFiles ?? []).map((f) => f.path))
if (recordedInputs.size === 0) {
  throw new Error(`${MANIFEST} に入力が 1 件も無い。写しを作っても意味がない`)
}

const paths = [...new Set([...RECURSIVE_DIRS.flatMap((d) => walk(ROOT, d)), ...exactFiles(ROOT)])].sort()

const files = paths.map((p) => {
  const buf = readFileSync(resolve(ROOT, p))
  return {
    path: p,
    sha256: createHash('sha256').update(buf).digest('hex'),
    isRecordedInput: recordedInputs.has(p),
    bytes: buf.length,
    content: buf.toString('utf8'),
  }
})

// --- 記録された入力を取りこぼしていないか。**黙って欠けたら止める** ---
const missing = [...recordedInputs].filter((p) => !paths.includes(p))
if (missing.length > 0) {
  throw new Error(
    '記録された入力が写しに入っていない。受け手は inputDigest を再計算できない:\n'
      + missing.map((m) => `  ${m}`).join('\n')
      + '\n  scripts/buildSourceSnapshot.mjs の RECURSIVE_DIRS / BASE_EXACT_FILES を直すこと。',
  )
}

const snapshot = {
  schemaVersion: 1,
  schemaId: 'trs-jack-3d-source-snapshot.v1',
  generatedBy: 'npm run release:snapshot',
  generatedAt: ARTIFACT_DATE,
  generatedFromCommit: git(ROOT, ['rev-parse', 'HEAD']),

  isSelfConsistencyOnly: true,
  producerClaimOnly:
    '**これは producer の申告である。**こちらが渡したファイルを、こちらが記録した hash と'
    + '照合するだけなので、producer が写しと manifest を同時に偽れば一致する。'
    + '受け手の独立検証を置き換えない。',
  replacesRecipientVerification: false,
  isSourceOfTruthForInputDigest: false,
  inputDigestSourceOfTruth: 'artifacts/source-input-manifest.json',

  whatThisProves:
    '記録した sha256 が、記録した中身と合っていること（自己整合）。'
    + 'および、source-input-manifest.json の inputFiles[].recordedSha256 を'
    + '受け手の手元で計算し直して突き合わせられること。',
  whatThisDoesNotProve:
    'この中身が本当に該当 tag の source であること。**それはこの写しでは確かめられない。**'
    + '循環しない検証には GitHub の tag source archive を使うこと。',

  independentVerificationRecipe: [
    '# 通信がある受け手は、写しではなく tag source を使うこと（循環しない）',
    'curl -sL -o src.tar.gz https://github.com/Driedsandwich/trs-jack-3d/archive/refs/tags/<TAG>.tar.gz',
    'node verifyReleaseSourceInputs.mjs --manifest source-input-manifest.json \\',
    '  --source src.tar.gz --scope source-input-scope.v1.json',
    '# あるいは、この写しを使う場合（自己整合の確認まで）',
    'node -e "const s=require(\'./source-snapshot.v1.json\'),c=require(\'crypto\');'
      + 'let ng=0;for(const f of s.files){const h=c.createHash(\'sha256\').update(Buffer.from(f.content,\'utf8\')).digest(\'hex\');'
      + 'if(h!==f.sha256){ng++;console.log(\'MISMATCH\',f.path)}}'
      + 'console.log(s.files.length+\' 件中 \'+ng+\' 件が不一致\');process.exit(ng?1:0)"',
  ],

  excluded: [
    { what: 'docs/screenshots/*.png', why: '検証に使わない。tag source archive の 8.94 MB の大半がこれだった' },
    { what: 'artifacts/ 配下（この写し自身を含む）', why: '生成物であって入力ではない' },
    { what: 'src/ のうち src/data・src/model 以外（UI・描画）', why: 'artifact の生成に読み込まれない（source-input-scope.v1.json の notCovered と同じ範囲）' },
    { what: 'test/ 配下', why: '検証コードであって生成入力ではない' },
    { what: 'node_modules', why: 'package-lock.json で固定される。写しに入れる意味がない' },
  ],

  recordedInputsTotal: files.filter((f) => f.isRecordedInput).length,
  filesTotal: files.length,
  files,
}

writeFileSync(resolve(ROOT, OUT), `${JSON.stringify(snapshot, null, 1)}\n`)

const bytes = statSync(resolve(ROOT, OUT)).size
console.log(`${OUT} を書き出した`)
console.log(`  ファイル ${snapshot.filesTotal} 件 / うち記録済み入力 ${snapshot.recordedInputsTotal} 件`)
console.log(`  ${bytes.toLocaleString()} bytes = ${(bytes / 1048576).toFixed(2)} MB`)
console.log('  **自己整合の確認まで。**独立検証には tag source archive を使うこと')
return { path: OUT, bytes, filesTotal: snapshot.filesTotal, recordedInputsTotal: snapshot.recordedInputsTotal }
}

const invokedDirectly = process.argv[1] && process.argv[1].endsWith('buildSourceSnapshot.mjs')
if (invokedDirectly) buildSourceSnapshot(process.cwd())

/**
 * 文書中の数値を artifact と機械照合する。
 *   npm run check:doc-numbers
 *
 * **なぜ要るか。** 2026-08-05 に、表のすぐ下のまとめ文だけが表と食い違っている誤りが
 * 2 件見つかった（`VERIFICATION_PLAN` §2-2 の「L だけが 1.35 mm」「他の 3 点は 0.2 mm 以内」、
 * `REAL_JACK_COMPARISON` §3-1 の「Tip 接点が 1.35 mm 奥へ」）。
 * 正しい値は同じ artifact の `contactPositions.deltaMm` にあり、**表は正しかった。**
 * 表を読んだ人と文を読んだ人で結論が変わる状態だった。
 *
 * **この検査が「0 件」と言うときの意味を狭く保つ。**
 * 宣言した対象だけを見て「不一致 0 件」と報告すると、
 * **宣言していない数値がいくらずれていても 0 件になる**（v0.5.2 の allowlist と同じ穴）。
 * そこで次を必ず同時に出す。
 *
 *   1. 走査した文書と、抽出した mm 値の総数
 *   2. **artifact で裏が取れなかった数の件数**（これが本体。0 にはならない）
 *   3. 宣言照合の結果（一致 / 不一致 / **本文に無い**＝宣言が空振り）
 *   4. md ↔ html の同期（生成し直して byte 比較）
 *   5. **自己検査**（検出器がわざと入れた誤りを実際に捕まえるか）
 *
 * 5 が落ちたら、他の結果は全部無効として非 0 で終わる。
 */
import { execFileSync } from 'node:child_process'
import { readFileSync, existsSync, readdirSync } from 'node:fs'
import { resolve, join } from 'node:path'
import { TARGETS, renderToString } from './mdToHtml.mjs'

const ROOT = process.cwd()
const read = (p) => readFileSync(resolve(ROOT, p), 'utf8')

// ---------------------------------------------------------------- artifact 側の値集合

/**
 * 文書は小数第 2 位まで丸めて書くので、照合も **±0.005 の窓**で行う。
 *
 * **丸めの実装で合わせようとすると落ちる。**`sensitivity.json` の 12.325 は
 * 二進で 12.32499999… なので `toFixed(2)` が `12.32` を返し、
 * 本文の正しい値 `12.33` を「artifact に無い」と誤判定した（2026-08-05 実測）。
 * 生の値を持って窓で比べる。窓が広すぎないことは自己検査 ③ で確かめる。
 */
const EPS = 0.005 + 1e-9

function collectNumbers() {
  const raw = []
  const walk = (o) => {
    if (Array.isArray(o)) return o.forEach(walk)
    if (o && typeof o === 'object') return Object.values(o).forEach(walk)
    if (typeof o === 'number' && Number.isFinite(o)) raw.push(o)
  }
  const dirs = ['artifacts', 'src/data']
  let files = 0
  for (const d of dirs) {
    const dir = resolve(ROOT, d)
    if (!existsSync(dir)) continue
    for (const f of readdirSync(dir).filter((x) => x.endsWith('.json'))) {
      walk(JSON.parse(read(join(d, f))))
      files++
    }
  }
  raw.sort((a, b) => a - b)
  return { vals: raw, files }
}

/** 昇順配列に、v との差が EPS 以内の値があるか */
function near(sorted, v) {
  let lo = 0, hi = sorted.length - 1
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    if (Math.abs(sorted[mid] - v) <= EPS) return true
    if (sorted[mid] < v) lo = mid + 1
    else hi = mid - 1
  }
  return false
}

/**
 * **差として引用される値**も裏取りの対象にする。
 * 今回の誤り 2 件はどちらも「2 つの値の差」で、artifact に直接は載っていなかった。
 * 同じ辞書の中の 2 値の差をすべて作る（対象は数の少ない対応表だけ。全 artifact でやると
 * 組み合わせが爆発して、何にでも当たる＝判別力がゼロになる）。
 */
function collectDifferences() {
  const out = []
  const p = 'artifacts/real_jack_comparison.json'
  if (!existsSync(resolve(ROOT, p))) return out
  const d = JSON.parse(read(p))
  const groups = [
    d.contactPositions?.assumed, d.contactPositions?.drawing, d.contactPositions?.deltaMm,
    ...Object.values(d.testerPredictions ?? {}).filter((v) => v && typeof v === 'object'),
  ].filter(Boolean)
  for (const g of groups) {
    const nums = Object.values(g)
      .flatMap((v) => (v && typeof v === 'object' ? Object.values(v) : [v]))
      .filter((v) => typeof v === 'number')
    for (const a of nums) for (const b of nums) out.push(Math.abs(a - b))
  }
  out.sort((a, b) => a - b)
  return out
}

// ---------------------------------------------------------------- 文書側の mm 値

const MM = /(\d+(?:\.\d+)?)\s*mm/g

function extractMm(md) {
  const hits = []
  md.split('\n').forEach((line, idx) => {
    if (/^\s*(?:\/\/|#{1,6}\s)/.test(line)) return
    for (const m of line.matchAll(MM)) hits.push({ line: idx + 1, value: parseFloat(m[1]), text: line.trim() })
  })
  return hits
}

// ---------------------------------------------------------------- 宣言照合
//
// **宣言は「本文の文字列」と「artifact から計算した真値」の組**にする。
// 本文が書き換わったら「本文に無い」で落ちるので、宣言だけが古く残ることがない。

function declarations() {
  const rj = JSON.parse(read('artifacts/real_jack_comparison.json'))
  const delta = rj.contactPositions.deltaMm
  const tp = rj.testerPredictions
  const gap = (k) => +(tp.assumed[k].shoulderGapMm - tp.drawing[k].shoulderGapMm).toFixed(2)
  const trrs = JSON.parse(read('artifacts/half_plug_topology_profile.v3.trs_jack_trrs.json'))
  const trs = JSON.parse(read('artifacts/half_plug_topology_profile.v3.trs_jack_trs.json'))
  const tc = JSON.parse(read('artifacts/test_counts.json'))
  const vr = JSON.parse(read('artifacts/validation-results.json'))
  const vs = JSON.parse(read('artifacts/verification_summary.json')).gradeCounts
  const iv = trrs.intervals.find((x) => x.intervalId === 'IV028')

  return [
    ['docs/VERIFICATION_PLAN.md', '**L だけが 1.45 mm 離れています。**', Math.abs(gap('L')) === 1.45],
    ['docs/VERIFICATION_PLAN.md', '次点は GND（0.34 mm）', Math.abs(gap('GND')) === 0.34],
    ['docs/VERIFICATION_PLAN.md', 'MIC と R は 0.05 mm 以内',
      Math.abs(gap('MIC')) <= 0.05 && Math.abs(gap('R')) <= 0.05],
    ['docs/VERIFICATION_PLAN.md', 'Tip = **1.45**、', delta['trrs.jack.contact.tip.axialCenter'] === 1.45],
    ['docs/VERIFICATION_PLAN.md', 'Ring2（GND）= **-0.34**', delta['trrs.jack.contact.ring2.axialCenter'] === -0.34],
    ['docs/VERIFICATION_PLAN.md', '> **Tip だけが 1.45 mm 奥**です', delta['trrs.jack.contact.tip.axialCenter'] === 1.45],
    ['docs/REAL_JACK_COMPARISON.md', 'Tip 接点が 1.45 mm 奥へ動いたため', delta['trrs.jack.contact.tip.axialCenter'] === 1.45],
    // 募集文（2026-08-06 追記）。**測る方が最初に読む数字なので、宣言で縛る**
    ['docs/VERIFICATION_PLAN.md', '| 見分けたいのは | すき間が **2.14 mm** か **0.69 mm** か |',
      tp.assumed.L.shoulderGapMm === 2.14 && tp.drawing.L.shoulderGapMm === 0.69],
    ['docs/VERIFICATION_PLAN.md', '| その差 | **1.45 mm** ＝ **デジタルノギスの分解能 0.01 mm の 145 倍** |',
      Math.abs(gap('L')) === 1.45 && Math.round(Math.abs(gap('L')) / 0.01) === 145],
    ['docs/V060_PLAN_20260805.md', 'IV028  nominalStartMm 13.3  /  nominalEndMm 13.52   幅 0.22 mm',
      iv.nominalStartMm === 13.3 && iv.nominalEndMm === 13.52],
    ['docs/V060_MEASUREMENT_DECISION_20260805.md', 'すき間 **2.14 mm** か **0.69 mm** か',
      tp.assumed.L.shoulderGapMm === 2.14 && tp.drawing.L.shoulderGapMm === 0.69],
    ['docs/V060_MEASUREMENT_DECISION_20260805.md', '8.33 か 8.67 か',
      tp.assumed.GND.shoulderGapMm === 8.33 && tp.drawing.GND.shoulderGapMm === 8.67],
    ['docs/release/v0.6.0-notes.md', `| 検証対象（\`validate:profiles\`） | 13 | **${vr.targetsTotal}** |`, true],
    ['docs/release/v0.6.0-notes.md', `| 根拠の区分 | FACT ${vs.FACT} / DERIVED ${vs.DERIVED} / ASSUMPTION ${vs.ASSUMPTION} | **変わらず** |`, true],
    ['docs/release/v0.6.0-notes.md', `**変わらず**（TRS ${trs.intervals.length}/${trs.events.length}・TRRS ${trrs.intervals.length}/${trrs.events.length}）`, true],
  ]
}

// ---------------------------------------------------------------- 公開済み文書の凍結値
//
// **公開した release notes は、作業ツリーの artifact を追いかけない。**
//
// v0.6.0 を出したあとに profile を作り直すと ID が変わる。
// それに合わせて notes を書き換えると、**公開済みの本文と手元の notes がずれる**——
// しかも本文のほうが古いまま残るので、受け手が読む数字と食い違う。
// 公開した本文は編集しない方針なので、**手元の控えのほうを凍結する。**
//
// 凍結して確かめるのは「公開したときの値が、いまも同じ文字列で書いてあるか」だけになる。
// artifact との突き合わせは、その release を出したときに済んでいる
// （`docs/release/<tag>-SHA256SUMS.txt` が配布物そのものの控え）。
//
// **凍結できるのは tag が実在する release の notes だけ。**
// 未公開の文書を凍結すると、artifact との照合から静かに逃げられてしまう。

const FROZEN = [
  { tag: 'v0.6.0', file: 'docs/release/v0.6.0-notes.md', text: 'v0.6.0  trs-jack-3d:TRS|JACK-TRS:480daac80519' },
  { tag: 'v0.6.0', file: 'docs/release/v0.6.0-notes.md', text: 'v0.6.0  trs-jack-3d:TRS|JACK-TRRS:b5b1e5ff2dba' },
  { tag: 'v0.6.0', file: 'docs/release/v0.6.0-notes.md', text: '| 単体テスト | 570 | **681**（skip 0） |' },
  { tag: 'v0.6.0', file: 'docs/release/v0.6.0-notes.md', text: 'docs/measurements/measurement-records.v1.json@sha256:dfe5020f9198' },
]

// ---------------------------------------------------------------- 説明済みの未照合値
//
// **裏が取れない ≠ 誤り。**点検して理由が付いたものはここへ移し、
// 「まだ誰も見ていない件数」だけが残るようにする。
// 理由の付いていない数が減らないと、この検査は進捗を主張できない。
// **使われなくなった注記は落とす**（宣言と同じで、空振りしたまま残らないようにする）。

const EXPLAINED = [
  { file: 'docs/VERIFICATION_PLAN.md', values: [11.23, 12.01, 10.07, 7.03, 8.27, 8.01, 11.11, 12.17, 2.77, 1.99, 6.97, 5.73, 5.99],
    reason: '走査刻み 0.01 mm 時代の出力。現行 profile は stepMm 0.02 なので末尾が 0.01 ずれる。本文もその旨を明記しており、合否は ±0.3 mm で見る' },
  { file: 'docs/REPORT.md', values: [7.21], reason: '実ブラウザのタッチ操作試験で読んだ HUD の値。モデルの出力ではない' },
  { file: 'docs/TEST_RESULTS.md', values: [7.21], reason: '同上' },
  { file: 'docs/SENSITIVITY.md', values: [16.15], reason: 'コードが到達できない深さの範囲を説明した文。モデルの出力ではない' },
  { file: 'ASSUMPTIONS.md', values: [2.75], reason: '表示専用の ASSUMPTION（artifact へ出していない形状パラメータ）' },
]

function explain(unbacked) {
  const used = new Set()
  const rest = []
  for (const u of unbacked) {
    const hit = EXPLAINED.findIndex((e) => e.file === u.file && e.values.some((v) => Math.abs(v - u.value) <= EPS))
    if (hit >= 0) { used.add(hit); continue }
    rest.push(u)
  }
  const stale = EXPLAINED.map((e, i) => (used.has(i) ? null : `${e.file}: ${e.values.join(' / ')}`)).filter(Boolean)
  return { rest, stale }
}

// ---------------------------------------------------------------- 実行

function runDeclarations(overrideDoc) {
  const res = { ok: 0, mismatch: [], absent: [], frozen: 0 }
  for (const [file, needle, truth] of declarations()) {
    const body = overrideDoc && overrideDoc.file === file ? overrideDoc.body : read(file)
    if (!body.includes(needle)) { res.absent.push(`${file}: "${needle}"`); continue }
    if (!truth) { res.mismatch.push(`${file}: "${needle}"`); continue }
    res.ok++
  }
  /**
   * **凍結値。**公開済み notes は artifact を追いかけないので、
   * 「公開したときの文字列がいまも書いてあるか」だけを見る。
   * **凍結できるのは tag が実在する release の notes だけ**——
   * 未公開の文書を凍結すると、artifact との照合から静かに逃げられる。
   */
  for (const { tag, file, text } of FROZEN) {
    if (!/^docs\/release\/v[0-9.]+-notes\.md$/.test(file)) {
      res.mismatch.push(`${file}: 凍結できるのは公開済み release notes だけ`)
      continue
    }
    if (!tagExists(tag)) { res.mismatch.push(`${file}: 凍結の根拠にした tag ${tag} が実在しない`); continue }
    const body = overrideDoc && overrideDoc.file === file ? overrideDoc.body : read(file)
    if (!body.includes(text)) { res.absent.push(`${file}（${tag} 時点で凍結）: "${text}"`); continue }
    res.frozen++
  }
  return res
}

/** tag が実在するか。**凍結の前提**なので、無ければ凍結そのものを不合格にする */
function tagExists(tag) {
  try {
    execFileSync('git', ['rev-parse', '--verify', `refs/tags/${tag}`], { cwd: ROOT, stdio: 'pipe' })
    return true
  } catch { return false }
}

function runMmSweep(extraDocs = []) {
  const { vals, files: artifactFiles } = collectNumbers()
  const diffs = collectDifferences()
  const docs = [...TARGETS.map((t) => t.md), 'UNKNOWNS.md', 'ASSUMPTIONS.md', 'README.md', 'SOURCES.md']
    .filter((p) => existsSync(resolve(ROOT, p)))
  const seen = new Set()
  const scanned = []
  for (const p of docs) { if (!seen.has(p)) { seen.add(p); scanned.push({ path: p, body: read(p) }) } }
  for (const d of extraDocs) scanned.push(d)

  let total = 0, backed = 0
  const unbacked = []
  for (const { path: p, body } of scanned) {
    for (const h of extractMm(body)) {
      total++
      if (near(vals, h.value) || near(diffs, h.value)) backed++
      else unbacked.push({ file: p, line: h.line, value: h.value, text: h.text.slice(0, 90) })
    }
  }
  return { artifactFiles, artifactValues: vals.length, diffValues: diffs.length, docs: scanned.length, total, backed, unbacked }
}

function runHtmlSync() {
  const drift = []
  let checked = 0
  for (const t of TARGETS) {
    if (!existsSync(resolve(ROOT, t.html))) { drift.push(`${t.html}: 生成物が無い`); continue }
    const { html } = renderToString(t.md, t.title)
    checked++
    if (html !== read(t.html)) drift.push(`${t.html}: ${t.md} から生成し直すと変わる`)
  }
  return { checked, drift }
}

// ---------------------------------------------------------------- 自己検査（対照）
//
// **検出器が鳴ることを、同じ実行の中で示す。**これが無いと「0 件」が
// 「見つからなかった」なのか「検査が動かなかった」なのか区別できない。

function selfTest() {
  const results = []

  // ① 存在しない mm 値を混ぜたら「裏が取れなかった」に入るか
  const bogus = { path: '<self-test>', body: 'ここに 987.65 mm という artifact に無い値を書く\n' }
  const swept = runMmSweep([bogus])
  const caught = swept.unbacked.some((u) => u.file === '<self-test>' && u.value === 987.65)
  results.push(['① artifact に無い mm 値を検出する', caught])

  // ② 逆に、artifact にある値は裏が取れる（何でも未照合に落とす検出器ではない）
  const rj = JSON.parse(read('artifacts/real_jack_comparison.json'))
  const known = rj.testerPredictions.assumed.L.shoulderGapMm
  const good = { path: '<self-test-positive>', body: `既知の値 ${known} mm を書く\n` }
  const swept2 = runMmSweep([good])
  const notFlagged = !swept2.unbacked.some((u) => u.file === '<self-test-positive>')
  results.push(['② artifact にある mm 値は裏が取れる', notFlagged])

  // ③ **窓が広すぎないこと。**もっともらしい大きさで artifact に無い値は捕まえる
  const { vals } = collectNumbers()
  let absent = null
  for (let v = 1; v < 14 && absent === null; v += 0.01) {
    const r = +v.toFixed(2)
    if (!near(vals, r)) absent = r
  }
  const swept3 = absent === null ? null : runMmSweep([{ path: '<self-test-window>', body: `${absent} mm\n` }])
  results.push([
    `③ artifact に無い現実的な値（${absent ?? '見つからず'} mm）も捕まえる＝窓が広すぎない`,
    absent !== null && swept3.unbacked.some((u) => u.file === '<self-test-window>'),
  ])

  // ③ 宣言の本文を書き換えたら「本文に無い」で鳴るか
  const file = 'docs/REAL_JACK_COMPARISON.md'
  const mutated = { file, body: read(file).replace('Tip 接点が 1.45 mm 奥へ動いたため', 'Tip 接点が 9.99 mm 奥へ動いたため') }
  const decl = runDeclarations(mutated)
  results.push(['④ 宣言した文が変わったら鳴る', decl.absent.some((s) => s.includes(file))])

  return results
}

// ---------------------------------------------------------------- 出力

const sweep = runMmSweep()
const { rest, stale } = explain(sweep.unbacked)
const decl = runDeclarations()
const sync = runHtmlSync()
const self = selfTest()

