/**
 * 重い成果物が古くなっていないかを判定する。
 *   npm run check:stale
 *
 * 何のためか:
 *   `npm run search:topology` は約 10 分、`npm run sensitivity` は約 15 分かかるので、
 *   毎回は回せない。しかし回し忘れると、**成果物だけが古い値のまま残る**。
 *
 *   CONTRIBUTING.md §3 には「接点位置や区分を変えたときは必要」と書いていたが、
 *   2026-08-03 の通し確認で**その条件が足りない**ことが分かった。
 *   帰線パッド幅を変えたときも両方の再実行が要る（どちらも走査軸に持っている）のに、
 *   手順書からはそう読み取れなかった。人が条件を覚えるのではなく、機械が判定する。
 *
 * どう判定するか:
 *   **成果物自身が「どの値の上で作られたか」を記録している。**それを現在のモデルと突き合わせる。
 *   - topology_search_*.json … searchSpace.axesByJack[*].shipped
 *   - sensitivity.json       … inputs（schemaVersion 5 から）
 *   - sensitivity.<slug>.json … provenance.inputDigest（2026-08-03 追加）
 *   - topology-robustness.<slug>.json … provenance.inputDigest（2026-08-03 追加）
 *   キーの一覧を人が保守しないので、走査軸が増えても勝手に追随する。
 */

import { existsSync, readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { buildProvenance, listRobustnessInputs, listSensitivityInputs } from './provenance'

const ROOT = process.cwd()
const dims = JSON.parse(readFileSync(resolve(ROOT, 'src/data/dimensions.json'), 'utf8')).entries as Record<
  string,
  { value: number }
>
const now = (k: string) => dims[k]?.value

const stale: { artifact: string; reason: string; cmd: string }[] = []
const checked: string[] = []

// --- 1. 目標トポロジー探索 -------------------------------------------------
for (const f of readdirSync(resolve(ROOT, 'artifacts')).filter((x) => x.startsWith('topology_search_'))) {
  const a = JSON.parse(readFileSync(resolve(ROOT, 'artifacts', f), 'utf8'))
  const axes = Object.values(a.searchSpace?.axesByJack ?? {}).flat() as { key: string; shipped: number }[]
  if (!axes.length) {
    stale.push({ artifact: f, reason: '走査軸の記録が無い（古い schemaVersion）', cmd: 'npm run search:topology' })
    continue
  }
  const diff = axes.filter((x) => now(x.key) !== undefined && now(x.key) !== x.shipped)
  checked.push(`${f}: 軸 ${axes.length} 件`)
  for (const d of diff)
    stale.push({
      artifact: f,
      reason: `${d.key} が ${d.shipped} → ${now(d.key)} に変わっている`,
      cmd: 'npm run search:topology -- --target DIFFERENCE_SIGNAL',
    })
}

// --- 2. 感度解析 -----------------------------------------------------------
const sp = resolve(ROOT, 'artifacts/sensitivity.json')
if (!existsSync(sp)) {
  stale.push({ artifact: 'sensitivity.json', reason: '存在しない', cmd: 'npm run sensitivity' })
} else {
  const a = JSON.parse(readFileSync(sp, 'utf8'))
  if (!a.inputs) {
    stale.push({
      artifact: 'sensitivity.json',
      reason: '入力値の記録が無い（schemaVersion 5 より前）',
      cmd: 'npm run sensitivity',
    })
  } else {
    checked.push(`sensitivity.json: 入力 ${Object.keys(a.inputs).length} 件`)
    for (const [k, v] of Object.entries(a.inputs))
      if (now(k) !== undefined && now(k) !== v)
        stale.push({ artifact: 'sensitivity.json', reason: `${k} が ${v} → ${now(k)} に変わっている`, cmd: 'npm run sensitivity' })
  }
}

// --- 2b. 感度 event artifact が入力より古くなっていないか -------------------
//
// **provenance を足しただけでは何も守れない。**現在の入力と突き合わせて初めて意味が出る。
// profile 側で同じ穴が実際に開いていた（記録は目の前にあったのに使っていなかった）ので、
// 感度 artifact にも同じ日に同じ検査を付ける（非阻害フォローアップ P1-1）。
for (const f of readdirSync(resolve(ROOT, 'artifacts')).filter((x) => /^sensitivity\.trs_jack_/.test(x))) {
  const a = JSON.parse(readFileSync(resolve(ROOT, 'artifacts', f), 'utf8'))
  const got = a.provenance?.inputDigest
  if (!got) {
    stale.push({ artifact: f, reason: 'provenance.inputDigest が無い', cmd: 'npm run sensitivity:events:all' })
    continue
  }
  // 記録された設定をそのまま使う。走査軸や刻みを変えた場合は
  // scripts/sensitivityEvents.ts 自身が入力なので、ファイルの指紋の側で捕まる
  const wanted = buildProvenance({
    root: ROOT,
    inputs: listSensitivityInputs(ROOT),
    settings: a.provenance.inputSettings,
    command: 'check:stale',
    artifactDate: '1970-01-01',
    release: false,
    allowRevisionOverride: false,
  }).inputDigest
  checked.push(`${f}: inputDigest ${String(got).slice(0, 12)}`)
  if (got !== wanted)
    stale.push({
      artifact: f,
      reason: `入力が変わっている (記録 ${String(got).slice(0, 12)} → 現在 ${wanted.slice(0, 12)})`,
      cmd: `npm run sensitivity:events -- --variant "${a.variantId}"`,
    })
}

// --- 2c. 目標トポロジーの頑健性 artifact ------------------------------------
// 約 12 分かかる重い成果物。古いまま残ると「この仮定でも目標は残る」が嘘になる。
for (const f of readdirSync(resolve(ROOT, 'artifacts')).filter((x) => /^topology-robustness\./.test(x))) {
  const a = JSON.parse(readFileSync(resolve(ROOT, 'artifacts', f), 'utf8'))
  const got = a.provenance?.inputDigest
  if (!got) {
    stale.push({ artifact: f, reason: 'provenance.inputDigest が無い', cmd: 'npm run search:robustness' })
    continue
  }
  const wanted = buildProvenance({
    root: ROOT,
    inputs: listRobustnessInputs(ROOT),
    settings: a.provenance.inputSettings,
    command: 'check:stale',
    artifactDate: '1970-01-01',
    release: false,
    allowRevisionOverride: false,
  }).inputDigest
  checked.push(`${f}: inputDigest ${String(got).slice(0, 12)}`)
  if (got !== wanted)
    stale.push({
      artifact: f,
      reason: `入力が変わっている (記録 ${String(got).slice(0, 12)} → 現在 ${wanted.slice(0, 12)})`,
      cmd: 'npm run search:robustness',
    })
}

// --- 3. profile が入力より古くなっていないか -------------------------------
//
// **2026-08-03 の完了条件の通し確認で見つかった穴。**
// profile は provenance.inputDigest に「何から作ったか」を記録しているのに、
// **それを現在の入力と突き合わせる検査がどこにも無かった。**
//
// 実際に古くなっていた。ajv を dev 依存へ足したとき package-lock.json が変わり、
// これは digest の対象なので profile を作り直す必要があったが、誰も気付かなかった。
// 記録は目の前にあったのに使っていなかった。
//
// 重い成果物と違い profile は数秒で作り直せるが、**古いまま公開されるのは同じ害**である。
// **variant ごとに計算する。** 感度 artifact は variant 別なので、
// 単一の digest と比べると必ず食い違う (P1-2)
const wantedFor = (variantId: string) =>
  buildProvenance({
    root: ROOT,
    variantSlug: variantId.toLowerCase().replace(/[^a-z0-9]+/g, '_'),
    command: 'check:stale',
    artifactDate: '1970-01-01', // digest に日付は入らない。何を入れても同じ
    release: false,
    allowRevisionOverride: false,
  }).inputDigest

for (const f of readdirSync(resolve(ROOT, 'artifacts')).filter((x) => x.startsWith('half_plug_topology_profile'))) {
  const a = JSON.parse(readFileSync(resolve(ROOT, 'artifacts', f), 'utf8'))
  const got = a.provenance?.inputDigest
  if (!got) {
    stale.push({ artifact: f, reason: 'provenance.inputDigest が無い', cmd: 'npm run export:half-plug:all' })
    continue
  }
  const wanted = wantedFor(String(a.variantId))
  checked.push(`${f}: inputDigest ${String(got).slice(0, 12)}`)
  if (got !== wanted)
    stale.push({
      artifact: f,
      reason: `入力が変わっている (記録 ${String(got).slice(0, 12)} → 現在 ${wanted.slice(0, 12)})`,
      cmd: 'npm run export:half-plug:all',
    })
}

// --- 出力 -----------------------------------------------------------------
for (const c of checked) console.log(`  照合: ${c}`)
if (!stale.length) {
  console.log('\n重い成果物は現在のモデルと整合しています。再実行は不要です。')
  process.exit(0)
}
console.log('\n**再実行が必要です。**')
const byCmd: Record<string, typeof stale> = {}
for (const s of stale) (byCmd[s.cmd] ??= []).push(s)
for (const [cmd, list] of Object.entries(byCmd)) {
  console.log(`\n  ${cmd}`)
  for (const s of list) console.log(`    ${s.artifact}: ${s.reason}`)
}
process.exit(1)

/**
 * テストが「通った」のか「そもそも走っていない」のかを分ける。
 *   npm run check:vacuity
 *
 * ## 何のためか
 *
 * このリポジトリでは 2026-08-02〜03 に **7 回**、同じ形の欠陥を作った。
 * 「識別子で引く → 見つからない → それでもテストが通る」である (一覧は test/_must.ts)。
 *
 * 構文を機械で洗うのは筋が悪い。候補は 142 件あったが、そのうち
 * **本当に偽の合格になるのは 7 件**だった (誤検出 95 %)。`.find(...)!` は
 * 引けなければ TypeError で落ちるし、空の `for..of` はモデルが壊れた印であって、
 * それは他の数十件が先に捕まえる。
 *
 * 代わりに**結果の側**を見る。空振りは形がばらばらでも、必ず次のどちらかで現れる。
 *
 *   1. テストが skip される (describe.skipIf / it.skip)
 *   2. テストの件数が減る (ファイルが読めない / 動的生成が 0 件になる / 消された)
 *
 * どちらも `artifacts/test_counts.json` と突き合わせれば分かる。
 * **構文ではなく件数を見るので、新しい形の空振りにも効く。**
 *
 * ## 下限として使う
 *
 * byFile の値は「これ以上減ってはいけない」線として使う。
 * 減らす変更が正しいこともある (テストを統合した等) が、そのときは
 * npm run test:count で artifact を更新し、**なぜ減ったかをコミットに書く**。
 * 黙って減ることだけを止める。
 */

import { execFileSync } from 'node:child_process'
import { mkdirSync, readFileSync, rmSync } from 'node:fs'
import { resolve } from 'node:path'

const ROOT = process.cwd()
const TMP = resolve(ROOT, 'node_modules/.cache/check-vacuity.json')
const RECORDED = resolve(ROOT, 'artifacts/test_counts.json')

mkdirSync(resolve(ROOT, 'node_modules/.cache'), { recursive: true })
// テストが落ちても続ける。ここで見たいのは合否ではなく「走ったか」
try {
  execFileSync('npx', ['vitest', 'run', '--reporter=json', `--outputFile=${TMP}`], {
    cwd: ROOT,
    stdio: ['ignore', 'ignore', 'inherit'],
  })
} catch {
  /* レポートが書けていれば続行する */
}

const r = JSON.parse(readFileSync(TMP, 'utf8'))
rmSync(TMP, { force: true })
const recorded = JSON.parse(readFileSync(RECORDED, 'utf8'))

const problems = []

// --- 1. 飛ばされたテスト -----------------------------------------------------
const skippedNames = []
const byFile = {}
for (const f of r.testResults) {
  const name = f.name.split('/').slice(-1)[0]
  byFile[name] = f.assertionResults.length
  for (const a of f.assertionResults)
    if (a.status === 'skipped' || a.status === 'pending') skippedNames.push(`${name}: ${a.fullName}`)
}
if (skippedNames.length)
  problems.push({
    what: `飛ばされたテストが ${skippedNames.length} 件`,
    why:
      'skip は「通った」ではなく「見ていない」。artifacts/ は 14 件とも git 管理下なので、'
      + '成果物の有無で分岐する必要は無い。',
    detail: skippedNames,
  })

// --- 2. 件数が減っていないか -------------------------------------------------
const dropped = []
for (const [name, floor] of Object.entries(recorded.byFile ?? {})) {
  const now = byFile[name]
  if (now === undefined) dropped.push(`${name}: ${floor} 件 → **ファイルごと走っていない**`)
  else if (now < floor) dropped.push(`${name}: ${floor} → ${now} 件 (${floor - now} 件減)`)
}
if (dropped.length)
  problems.push({
    what: `テスト件数が減っているファイルが ${dropped.length} 件`,
    why:
      '動的生成の入力が消えると、件数だけが静かに減る。'
      + '意図して減らしたなら npm run test:count で更新し、理由をコミットに書く。',
    detail: dropped,
  })

// --- 出力 -------------------------------------------------------------------
const total = Object.values(byFile).reduce((a, b) => a + b, 0)
console.log(`  実行: ${total} 件 / ${Object.keys(byFile).length} ファイル (記録: ${recorded.total} 件)`)
if (!problems.length) {
  console.log('\n空振りしているテストはありません。全件が実際に走っています。')
  process.exit(0)
}
console.log('\n**空振りの疑いがあります。**')
for (const p of problems) {
  console.log(`\n  ${p.what}`)
  console.log(`    ${p.why}`)
  for (const d of p.detail.slice(0, 25)) console.log(`      ${d}`)
  if (p.detail.length > 25) console.log(`      ... 他 ${p.detail.length - 25} 件`)
}
process.exit(1)

/**
 * 実在部品の図面値と、本モデルの仮定値を突き合わせる。
 *   npm run compare:real-jack
 *
 * 何のためか:
 *   4極ジャックの接点位置は一次資料が無く、4 件とも仮定だった (UNKNOWNS §5-2)。
 *   2026-08-02 のデータシート探索で、**接点位置を寸法記入した断面図**を 1 件だけ
 *   見つけた (pro-SIGNAL PS000001)。この図面値を入れると本モデルの結論がどう動くかを
 *   測り、結果を artifact として固定する。
 *
 * 結論を先に書いておく:
 *   **図面値では、看板だった「3極プラグ×4極ジャックで左右差分が残る区間」が消える。**
 *   都合の悪い結果なので、消さずに artifact とテストで固定する。
 *
 * この 1 件で「4極ジャック一般」を語らない:
 *   PS000001 は 1 部品 (SMT・IPX5/7 防水) にすぎない。代表性は主張しない。
 *   また、この部品の接点位置**以外**の諸元 (パッド幅・ばね・端子) は図面に無いので、
 *   本モデルはこの部品を再現していない。差し替えでも variant 追加でもなく、
 *   **比較対象**として扱う。理由は docs/REAL_JACK_COMPARISON.md。
 */

import { mkdirSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { buildModelWithOverrides, getModel } from '../src/data'
import { DEFAULT_FAULTS } from '../src/model/contact'
import { classifyFromEvaluation } from '../src/model/topology'
import type { TrsModel } from '../src/model/engine'

const ROOT = resolve(process.cwd())
const STEP = 0.01
const VARIANT = 'TRS|JACK-TRRS' as const

/** ARTIFACT_DATE で固定できる。既存 artifact と同じ規約 */
const generatedAt = () => process.env.ARTIFACT_DATE ?? new Date().toISOString().slice(0, 10)

/**
 * PS000001 の断面図 SEC:A-A から読んだ接点の軸位置。
 * 基準は図中の "* Reference plane" で、完全挿入時にプラグ肩が来る面である
 * (図中の絶縁帯 3 本の位置を目視で読み取って確かめた。docs/REAL_JACK_COMPARISON.md §2)。
 */
const DRAWING: Record<string, number> = {
  'trrs.jack.contact.sleeve.axialCenter': 1.28,
  'trrs.jack.contact.ring2.axialCenter': 4.4,
  'trrs.jack.contact.ring1.axialCenter': 7.55,
  'trrs.jack.contact.tip.axialCenter': 12.75,
}

/**
 * 「帰線が浮き、L と R が別々の導体に届いている」区間。
 *
 * **判定は書かない (統合オーダー P0-4)。** 2026-08-03 まで、ここに同じ条件式の
 * 3 つ目の写しがあった。分類器 (src/model/topology.ts) が唯一の正本。
 */
function differenceWindows(m: TrsModel): { fromMm: number; toMm: number; widthMm: number }[] {
  const out: { fromMm: number; toMm: number; widthMm: number }[] = []
  let cur: { fromMm: number; toMm: number } | null = null
  for (let d = 0; d <= m.fullDepthMm + 1e-9; d += STEP) {
    const dd = +d.toFixed(4)
    const cls = classifyFromEvaluation(m.jack.terminals, m.plug.netFunctions, m.evaluate(dd, DEFAULT_FAULTS))
    if (cls.topologyClass === 'ground-open-differential') {
      if (!cur) cur = { fromMm: dd, toMm: dd }
      else cur.toMm = dd
    } else if (cur) {
      out.push({ ...cur, widthMm: +(cur.toMm - cur.fromMm + STEP).toFixed(4) })
      cur = null
    }
  }
  if (cur) out.push({ ...cur, widthMm: +(cur.toMm - cur.fromMm + STEP).toFixed(4) })
  return out
}

const fullInsertionOk = (m: TrsModel) =>
  m.evaluate(m.fullDepthMm, DEFAULT_FAULTS).acoustic.code === 'NORMAL'

const build = (ov: Record<string, number>) => buildModelWithOverrides(VARIANT, ov)

// --- 1. 仮定値と図面値の比較 -------------------------------------------
const assumed = getModel(VARIANT)
const drawing = build(DRAWING)

const assumedContacts = Object.fromEntries(
  Object.keys(DRAWING).map((k) => [k, assumed.dims.entry(k).value]),
)

// --- 2. 図面が縮尺どおりかの照合材料 -----------------------------------
// 完全挿入したとき、プラグの絶縁帯の中心が肩から何 mm の位置に来るか。
// 図面からの目視読み取り (2.76 / 5.79 / 8.80) と突き合わせる。
// 図面に描かれているのは **4極プラグ** なので、4極プラグの絶縁帯を使う。
// ここで 3極プラグ (TRS|JACK-TRRS の plug 側) を使うと絶縁帯が 2 本しか出ず、照合にならない。
const trrsPlug = getModel('TRRS-CTIA|JACK-TRRS')
const insulatorCentersFromShoulder = trrsPlug.plug.segments
  .filter((s) => s.kind === 'insulator')
  .map((s) => +(trrsPlug.fullDepthMm - (s.startMm + s.endMm) / 2).toFixed(3))
  .sort((a, b) => a - b)

// --- 3. どこで切り替わるか (Tip 接点の軸位置だけを振る) ------------------
const others = { ...DRAWING }
delete others['trrs.jack.contact.tip.axialCenter']

const tipScan: { tipAxialMm: number; fullInsertionOk: boolean; widthMm: number }[] = []
for (let tip = 10.0; tip <= 13.5 + 1e-9; tip += 0.05) {
  const t = +tip.toFixed(2)
  const m = build({ ...others, 'trrs.jack.contact.tip.axialCenter': t })
  const w = differenceWindows(m)
  tipScan.push({
    tipAxialMm: t,
    fullInsertionOk: fullInsertionOk(m),
    widthMm: w.length ? Math.max(...w.map((x) => x.widthMm)) : 0,
  })
}
const lastAlive = [...tipScan].reverse().find((r) => r.widthMm > 0)
const firstDead = tipScan.find((r) => r.tipAxialMm > (lastAlive?.tipAxialMm ?? -1) && r.widthMm === 0)

// --- 4. 他の軸で取り戻せるか -------------------------------------------
const recovery: { padWidthMm: number; complianceMm: number; widthMm: number }[] = []
for (const pad of [0.3, 0.4, 0.5, 0.7, 0.9])
  for (const c of [0.02, 0.05, 0.1, 0.15]) {
    const m = build({
      ...DRAWING,
      'trrs.jack.contact.narrowPadWidth': pad,
      'model.contact.complianceMm': c,
    })
    recovery.push({
      padWidthMm: pad,
      complianceMm: c,
      widthMm: differenceWindows(m).reduce((a, x) => Math.max(a, x.widthMm), 0),
    })
  }

/**
 * Lumberg 1503 28 (4極・JEITA RC-5325A) の **端子** 軸位置。接点位置ではない。
 * 基板レイアウト図の 2.75 / 5.50 / 9.30 に、ノーズ突出 2.00 を足して挿入口面基準にした値。
 * 端子 1 は回路記号の箱 = Sleeve バレルなので、ばねは端子 2 / 3 / 4 の 3 本。
 *
 * **これを接点位置として使ってよい保証は無い。** 端子は「ばねが基板へ降りる位置」であって
 * 接点そのものではなく、実在の 4極品には端子の並びが接点の並びと逆のものもある
 * (Cliff FC68125)。ここでは「もし接点が端子の真上にあるなら」という条件付きの計算をする。
 */
const LUMBERG_TERMINALS: Record<string, number> = {
  'trrs.jack.contact.ring2.axialCenter': 4.74,
  'trrs.jack.contact.ring1.axialCenter': 7.5,
  'trrs.jack.contact.tip.axialCenter': 11.3,
}

/** 完全挿入時に各接点が触れる導体。端子位置が接点位置として成立しうるかの検査 */
function landingAtFullInsertion(ov: Record<string, number>) {
  const m = build(ov)
  const ev = m.evaluate(m.fullDepthMm, DEFAULT_FAULTS)
  const tt = ev.circuit.terminalToPlugNet
  return Object.fromEntries(
    m.jack.terminals.map((t) => [t.signalRole ?? t.id, (tt[t.id] ?? []).join('+') || null]),
  )
}

// --- 5. テスターで測れる形の予測 (VERIFICATION_PLAN §2-2 の突き合わせ用) --------
// 4極プラグを使う。各端子が「最初に導通する深さ」と、そのときの肩〜ジャック前面のすき間。
function testerPredictions(ov: Record<string, number>) {
  const m = ov === null ? getModel('TRRS-CTIA|JACK-TRRS') : buildModelWithOverrides('TRRS-CTIA|JACK-TRRS', ov)
  const out: Record<string, { firstContactDepthMm: number | null; shoulderGapMm: number | null }> = {}
  for (const t of m.jack.terminals) {
    let first: number | null = null
    for (let d = 0; d <= m.fullDepthMm + 1e-9; d += STEP) {
      const dd = +d.toFixed(4)
      const nets = m.evaluate(dd, DEFAULT_FAULTS).circuit.terminalToPlugNet[t.id] ?? []
      if (nets.length > 0) {
        first = dd
        break
      }
    }
    out[t.signalRole ?? t.id] = {
      firstContactDepthMm: first,
      shoulderGapMm: first === null ? null : +(m.fullDepthMm - first).toFixed(3),
    }
  }
  return out
}

const out = {
  schemaVersion: 1,
  generatedAt: generatedAt(),
  variantId: VARIANT,
  stepMm: STEP,

  question:
    '4極ジャックの接点位置に一次資料が無いという未確認事項 (UNKNOWNS §5-2) を、実在部品の図面で埋められるか',

  referencePart: {
    partNumber: 'PS000001',
    brand: 'pro-SIGNAL (Premier Farnell 自社ブランド)',
    manufacturer: null,
    manufacturerNote: '実際の製造者は図面に記載が無い。商社の自社ブランド資料である',
    title: '3.5mm 4 Pole Audio Jack, SMT, IPX5/7',
    docDate: '2017-03-31 (V1.0)',
    url: 'https://www.farnell.com/datasheets/2261829.pdf',
    accessed: '2026-08-02',
    whatMakesItRare:
      'SEC:A-A が 4極プラグを挿した状態の断面図で、"* Reference plane" から各接点へ引出線を引き、4 接点すべての軸位置が寸法記入されている。探索した 170 型番のうち、接点位置そのものが寸法記入されていたのはこの 1 件だけ',
    hasTolerances: false,
    representativeness:
      'この 1 部品にすぎない。4極ジャック一般を代表するものではない。またこの部品の接点位置以外の諸元 (パッド幅・ばね定数・端子配置) は図面に無く、本モデルはこの部品を再現していない',
  },

  contactPositions: {
    unit: 'mm',
    datum: '完全挿入時にプラグ肩が来る面 (図面の Reference plane と一致することを §2 の照合で確かめた)',
    assumed: assumedContacts,
    drawing: DRAWING,
    deltaMm: Object.fromEntries(
      Object.keys(DRAWING).map((k) => [k, +(DRAWING[k] - assumedContacts[k]).toFixed(3)]),
    ),
  },

  scaleCheck: {
    method:
      '断面図を 800dpi で描画し、Reference plane を 0・12.75 の寸法線終端を基準に px/mm を求めて、絶縁帯 3 本の中心位置を目視で読み取った。自動計測ではないので精度は約 0.1mm',
    measuredFromDrawingMm: [2.76, 5.79, 8.8],
    predictedByModelMm: insulatorCentersFromShoulder,
    note:
      '本モデルのプラグ導体境界は独立 2 社の図面から得た FACT。ここが一致するということは、'
      + '断面図が縮尺どおりに描かれており、かつプラグが完全挿入の状態で描かれていることを意味する',
