/**
 * 実測した「切り替わりの深さ」から、ジャック内部接点の軸位置を逆算する。
 *
 *   npx vite-node scripts/fitContacts.ts                    # 自己検査 (モデル自身の予測を入力)
 *   npx vite-node scripts/fitContacts.ts 8.4 12.3 4.1       # 実測値を入れて逆算
 *      引数の順: Ringブレーク開放 / Tipブレーク開放 / Sleeve接点がTipに触れ始める
 *
 * 考え方:
 *   接点の軸位置 xj を 1 つだけ動かして、その接点の「最初の切り替わり深さ」が
 *   実測と一致する値を探す。合わせるのは 1 点だけにする。
 *   残りの切り替わり (再閉など) は合わせずに予測として出し、実測と比べる。
 *   全部合わせにいくと「合って当然」になり、モデルを検証したことにならない。
 */

import { getModel } from '../src/data'
import { DEFAULT_FAULTS, evaluateContact } from '../src/model/contact'
import type { ResolvedJackContact } from '../src/model/resolve'

const model = getModel('TRS|JACK-TRS')
const FULL = model.fullDepthMm
const STEP = 0.005
const F = DEFAULT_FAULTS

/** 軸位置だけ差し替えた接点を作る */
function withAxialCenter(c: ResolvedJackContact, xj: number): ResolvedJackContact {
  return { ...c, axialCenterMm: xj, rootAxialMm: c.rootAxialMm + (xj - c.axialCenterMm) }
}

/** ブレーク接点が開閉する深さを全部拾う */
function breakTransitions(c: ResolvedJackContact): { depth: number; to: string }[] {
  const out: { depth: number; to: string }[] = []
  let prev: string | null = null
  for (let d = 0; d <= FULL + 1e-9; d += STEP) {
    const r = evaluateContact(c, model.plug, d, F, model.contactCfg)
    const v = r.breakState === 'BREAK_OPEN' ? '開' : '閉'
    if (prev !== null && v !== prev) out.push({ depth: Number(d.toFixed(3)), to: v })
    prev = v
  }
  return out
}

/** その接点がどのプラグ導体に導通しているかが変わる深さを拾う */
function netTransitions(c: ResolvedJackContact): { depth: number; to: string }[] {
  const out: { depth: number; to: string }[] = []
  let prev: string | null = null
  for (let d = 0; d <= FULL + 1e-9; d += STEP) {
    const r = evaluateContact(c, model.plug, d, F, model.contactCfg)
    // 並び順で見かけ上の変化が出ないよう揃える
    const v = r.connectedNets.slice().sort().join('+') || '—'
    if (prev !== null && v !== prev) out.push({ depth: Number(d.toFixed(3)), to: v })
    prev = v
  }
  return out
}

/** 最初の切り替わりが observed になる軸位置を探す */
function fitFirstTransition(
  base: ResolvedJackContact,
  observed: number,
  kind: 'break' | 'net',
): { xj: number; err: number } | null {
  let best: { xj: number; err: number } | null = null
  // 粗く走査してから細かく詰める
  for (const [lo, hi, st] of [
    [base.axialCenterMm - 4, base.axialCenterMm + 4, 0.02],
    [0, 0, 0], // 2 周目は下で入れ替える
  ] as [number, number, number][]) {
    if (st === 0) continue
    for (let xj = lo; xj <= hi; xj += st) {
      if (xj <= 0.2 || xj >= FULL) continue
      const c = withAxialCenter(base, xj)
      const t = kind === 'break' ? breakTransitions(c) : netTransitions(c)
      if (t.length === 0) continue
      const err = Math.abs(t[0].depth - observed)
      if (!best || err < best.err) best = { xj: Number(xj.toFixed(4)), err }
    }
  }
  if (!best) return null
  // 細かく詰める
  for (let xj = best.xj - 0.03; xj <= best.xj + 0.03; xj += 0.002) {
    if (xj <= 0.2 || xj >= FULL) continue
    const c = withAxialCenter(base, xj)
    const t = kind === 'break' ? breakTransitions(c) : netTransitions(c)
    if (t.length === 0) continue
    const err = Math.abs(t[0].depth - observed)
    if (err < best.err) best = { xj: Number(xj.toFixed(4)), err }
  }
  return best
}

// ---------------------------------------------------------------------------

type Target = {
  id: string
  label: string
  probe: string
  kind: 'break' | 'net'
  firstLabel: string
}

const TARGETS: Target[] = [
  { id: 'JC_RING', label: 'Ring 接点ばね', probe: 'ピン2 ↔ ピン4', kind: 'break', firstLabel: 'ブレーク接点が最初に開く' },
  { id: 'JC_TIP', label: 'Tip 接点ばね', probe: 'ピン3 ↔ ピン5', kind: 'break', firstLabel: 'ブレーク接点が開く' },
  { id: 'JC_SLEEVE', label: 'Sleeve 接点', probe: 'ピン1 ↔ プラグ Tip', kind: 'net', firstLabel: 'Tip 導体に触れ始める' },
]

const args = process.argv.slice(2).map(Number).filter((n) => !Number.isNaN(n))
const selfCheck = args.length === 0

console.log(
  selfCheck
    ? '=== 自己検査: モデル自身の予測を入力して、元の軸位置を復元できるか ===\n'
    : '=== 実測値から軸位置を逆算 ===\n',
)

let maxRoundTripErr = 0

TARGETS.forEach((t, i) => {
  const base = model.jack.contacts.find((c) => c.id === t.id)!
  const baseTrans = t.kind === 'break' ? breakTransitions(base) : netTransitions(base)
  const predictedFirst = baseTrans[0]?.depth ?? NaN
  const observed = selfCheck ? predictedFirst : args[i]

  console.log(`## ${t.label}  （${t.probe}）`)
  if (observed === undefined || Number.isNaN(observed)) {
    console.log('  実測値が渡されていないので飛ばす\n')
    return
  }
  console.log(`  合わせる観測点: ${t.firstLabel}`)
  console.log(`    現モデルの予測 : ${predictedFirst.toFixed(2)} mm （すき間 ${(FULL - predictedFirst).toFixed(2)} mm）`)
  console.log(`    実測           : ${observed.toFixed(2)} mm （すき間 ${(FULL - observed).toFixed(2)} mm）`)

  const fit = fitFirstTransition(base, observed, t.kind)
  if (!fit) {
    console.log('  → その深さで切り替わる軸位置が見つからない。構造の仮定を疑うこと\n')
    return
  }
  const shift = fit.xj - base.axialCenterMm
  console.log(`  逆算した軸位置   : ${fit.xj.toFixed(3)} mm  （現モデル ${base.axialCenterMm.toFixed(3)} mm / ずれ ${shift >= 0 ? '+' : ''}${shift.toFixed(3)} mm）`)
  console.log(`  残差             : ${fit.err.toFixed(4)} mm`)

  if (selfCheck) maxRoundTripErr = Math.max(maxRoundTripErr, Math.abs(shift))

  // 合わせていない残りの切り替わりを、独立した予測として出す
  const fitted = withAxialCenter(base, fit.xj)
  const rest = (t.kind === 'break' ? breakTransitions(fitted) : netTransitions(fitted)).slice(1)
  if (rest.length) {
    console.log('  この軸位置なら、続く切り替わりはこうなる（合わせていない＝検証に使える）:')
    for (const r of rest) {
      console.log(`    ${r.depth.toFixed(2)} mm （すき間 ${(FULL - r.depth).toFixed(2)} mm） → ${r.to}`)
    }
  }
  console.log('')
})

if (selfCheck) {
  const ok = maxRoundTripErr < 0.02
  console.log(`自己検査: 軸位置の復元誤差 最大 ${maxRoundTripErr.toFixed(4)} mm → ${ok ? '合格' : '不合格'}`)
  if (!ok) process.exitCode = 1
} else {
  console.log('次の手順:')
  console.log('  1. ずれが 0.3mm 以内なら、モデルは実測と整合。dimensions.json の note に実測日と値を追記する')
  console.log('  2. 0.3〜1.0mm なら、逆算した軸位置へ dimensions.json を更新し、grade を ASSUMPTION から DERIVED へ上げる')
  console.log('  3. 1.0mm 超、または「続く切り替わり」が実測と質的に違うなら、')
  console.log('     軸位置だけの問題ではない。パッド幅・自由半径・プラグ外形のどれが効いているか切り分ける')
}

/**
 * 4極ジャックの接点位置を、実測した「肩すき間」から逆算する。
 *
 *   npx vite-node scripts/fitContactsTrrs.ts             # 自己検査（モデル自身の予測を入力）
 *   npx vite-node scripts/fitContactsTrrs.ts 0.72        # 実測のすき間 (mm) を入れて逆算
 *
 * `scripts/fitContacts.ts` の 4極版。あちらは 3極ジャックのブレーク接点を扱う。
 *
 * 考え方は同じで、**軸位置を 1 つだけ動かして観測点が合う値を探す。**
 * 合わせるのは 1 点だけにする。全部合わせにいくと「合って当然」になり、
 * モデルを検証したことにならない。
 *
 * 観測点: **4極ジャックの L（Tip）端子が、プラグ Tip 導体と最初に導通するときの肩すき間**
 *   すき間 = 完全挿入深度 − 深さ  （docs/VERIFICATION_PLAN.md §2-2）
 */

import { getModel } from '../src/data'
import { DEFAULT_FAULTS, evaluateContact } from '../src/model/contact'
import type { ResolvedJackContact } from '../src/model/resolve'

const VARIANT = 'TRRS-CTIA|JACK-TRRS' as const
const model = getModel(VARIANT)
const FULL = model.fullDepthMm
const STEP = 0.005
const CONTACT_ID = 'JC_TIP'

/** 軸位置だけ差し替えた接点を作る（fitContacts.ts と同じ扱い） */
function withAxialCenter(c: ResolvedJackContact, xj: number): ResolvedJackContact {
  return { ...c, axialCenterMm: xj, rootAxialMm: c.rootAxialMm + (xj - c.axialCenterMm) }
}

/**
 * その軸位置での「最初に TIP 導体へ導通する肩すき間」。到達しなければ null。
 *
 * **モデルごと差し替えず、接点 1 個だけを評価する**（`fitContacts.ts` と同じ扱い）。
 * `{...model}` で作り直すと、モデルが持つメソッドが落ちる。
 */
function firstTipShoulderGap(xj: number): number | null {
  const base = model.jack.contacts.find((c) => c.id === CONTACT_ID)
  if (!base) throw new Error(`接点 ${CONTACT_ID} が ${VARIANT} に無い`)
  const moved = withAxialCenter(base, xj)
  for (let d = 0; d <= FULL + 1e-9; d += STEP) {
    const r = evaluateContact(moved, model.plug, d, DEFAULT_FAULTS, model.contactCfg)
    if (r.connectedNets.includes('TIP')) return +(FULL - d).toFixed(4)
  }
  return null
}

/** 観測されたすき間になる軸位置を探す。粗く走査してから詰める */
interface Fit { xj: number; errMm: number }

function scanRange(observedGapMm: number, lo: number, hi: number, st: number, seed: Fit | null): Fit | null {
  let best: Fit | null = seed
  for (let xj = lo; xj <= hi; xj += st) {
    if (xj <= 0.2 || xj >= FULL) continue
    const g = firstTipShoulderGap(xj)
    if (g === null) continue
    const errMm = +Math.abs(g - observedGapMm).toFixed(4)
    if (best === null || errMm < best.errMm) best = { xj: +xj.toFixed(4), errMm }
  }
  return best
}

function fit(observedGapMm: number): Fit | null {
  const base = model.jack.contacts.find((c) => c.id === CONTACT_ID)
  if (!base) return null
  const coarse = scanRange(observedGapMm, base.axialCenterMm - 4, base.axialCenterMm + 4, 0.05, null)
  if (coarse === null) return null
  return scanRange(observedGapMm, coarse.xj - 0.06, coarse.xj + 0.06, 0.005, coarse)
}

// ---------------------------------------------------------------------------

const args = process.argv.slice(2).map(Number).filter((n) => !Number.isNaN(n))
const selfCheck = args.length === 0
const base = model.jack.contacts.find((c) => c.id === CONTACT_ID)
if (!base) throw new Error(`接点 ${CONTACT_ID} が ${VARIANT} に無い`)

const predictedGap = firstTipShoulderGap(base.axialCenterMm)
console.log(
  selfCheck
    ? '=== 自己検査: モデル自身の予測を入力して、元の軸位置を復元できるか ===\n'
    : '=== 実測の肩すき間から軸位置を逆算 ===\n',
)
console.log(`## ${VARIANT} の ${CONTACT_ID}（L 端子）`)
console.log(`  現モデルの軸位置 : ${base.axialCenterMm} mm`)
console.log(`  現モデルの予測   : 肩すき間 ${predictedGap ?? '—'} mm`)

const observed = selfCheck ? predictedGap : args[0]
if (observed === null || observed === undefined) {
  console.log('\n  予測が出せないので終わる')
  process.exit(1)
}
console.log(`  入力             : 肩すき間 ${observed} mm`)

const r = fit(observed)
if (!r) {
  console.log('\n  合う軸位置が見つからなかった')
  process.exit(1)
}
console.log(`\n  逆算した軸位置   : ${r.xj} mm （残差 ${r.errMm} mm）`)

if (selfCheck) {
  const back = +Math.abs(r.xj - base.axialCenterMm).toFixed(4)
  console.log(`  往復誤差         : ${back} mm`)
  // **自己検査は「元に戻れること」まで見る。**残差が小さいだけでは、
  // 別の軸位置でも同じすき間になる（＝一意でない）場合を見逃す
  if (back > 0.05) {
    console.log('\n  **元の軸位置へ戻れていない。**逆算が一意でない可能性がある')
    process.exit(1)
  }
  console.log('\n  自己検査 OK')
} else {
  console.log(`\n  現モデルとの差   : ${(r.xj - base.axialCenterMm).toFixed(4)} mm`)
  console.log('  **この値をそのまま採用しないこと。**1 点を合わせただけで、他の観測点は合わせていない。')
  console.log('  記録は docs/measurements/measurement-records.v1.json へ入れること（npm run measure:check で判定）。')
}

/**
 * 納品成果物 (contact_sweep.json / force_curve.json / events.json) を生成する。
 *   npm run artifacts
 *
 * 走査は 0.02mm 刻み (仕様の「0.05mm 以下」を満たす)。
 * 乱数を使わないため、何度実行しても同じファイルが出る。
 */

import { mkdirSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { allVariantIds, getModel, jackInfo, plugInfo, splitVariantId } from '../src/data'
import { extractEvents, sweep } from '../src/model/sweep'
import { computeForceCurve } from '../src/model/force'
import { DEFAULT_FAULTS } from '../src/model/contact'

const OUT = resolve(process.cwd(), 'artifacts')
mkdirSync(OUT, { recursive: true })

const model = getModel('TRS|JACK-TRS')
const STEP = 0.02
// 既定は実行日。ARTIFACT_DATE を渡すと固定でき、差分を安定させたいときに使う。
const GENERATED_AT = process.env.ARTIFACT_DATE ?? new Date().toISOString().slice(0, 10)

// ---------------------------------------------------------------------------
// contact_sweep.json
// ---------------------------------------------------------------------------
const rows = sweep(model, { stepMm: STEP })
const events = extractEvents(model, rows)

const sweepDoc = {
  schemaVersion: 1,
  generatedAt: GENERATED_AT,
  source: {
    plug: `${model.plug.manufacturer} ${model.plug.partNumber}`,
    jack: `${model.jack.manufacturer} ${model.jack.partNumber}`,
    note: '実在する代表的な 3.5mm TRS 接続の一例。3.5mm ジャック全ての代表ではない。',
  },
  coordinateSystem: {
    depthMm: 'ジャック前面基準面 (ローレットナット前面) からプラグ先端までの距離。負値は未挿入。',
    fullInsertionDepthMm: model.fullDepthMm,
    plugSegmentCoordinate: 's = プラグ先端からの軸方向距離 [mm]',
    relation: 's = depthMm - contact.axialCenterMm',
  },
  stepMm: STEP,
  plugSegments: model.plug.segments.map((s) => ({
    id: s.id,
    label: s.label,
    kind: s.kind,
    net: s.net ?? null,
    startMm: s.startMm,
    endMm: s.endMm,
    grade: s.grade,
  })),
  jackContacts: model.jack.contacts.map((c) => ({
    id: c.id,
    label: c.label,
    terminalId: c.terminalId,
    pin: model.jack.terminals.find((t) => t.id === c.terminalId)?.pin ?? null,
    expectedSegment: c.expectedSegment,
    axialCenterMm: c.axialCenterMm,
    padWidthMm: c.padWidthMm,
    freeRadiusMm: c.freeRadiusMm,
    breakContact: c.breakContact
      ? { id: c.breakContact.id, terminalId: c.breakContact.terminalId, normalState: c.breakContact.normalState }
      : null,
    grade: c.grade,
  })),
  rows,
}
writeFileSync(resolve(OUT, 'contact_sweep.json'), JSON.stringify(sweepDoc, null, 1))

// ---------------------------------------------------------------------------
// force_curve.json
// ---------------------------------------------------------------------------
const curve = computeForceCurve(
  model.jack,
  model.plug,
  DEFAULT_FAULTS,
  model.contactCfg,
  model.forceCfg,
  STEP,
  -1,
)
const peakIns = Math.max(...curve.map((c) => c.insertionN))
const peakWd = Math.max(...curve.map((c) => c.withdrawalN))

const forceDoc = {
  schemaVersion: 1,
  generatedAt: GENERATED_AT,
  disclaimer:
    '推定値であり実測値ではない。有限要素解析は行っていない。摩擦係数とばね定数は、' +
    'メーカー公称の挿抜力レンジと接点押付力の参考値に整合するよう置いた仮定値である。',
  method:
    'エネルギー法。接点 1 本あたり F = N·(μ + dδ/dd)。dδ/dd はプラグ外形プロファイルの傾きを' +
    '中心差分で求めた値。これに入口ブッシングの摩擦と完全挿入位置の保持 (デテント) を加える。' +
    '抜去時は運動方向が逆になるため摩擦の符号が変わり、ヒステリシスが生じる。',
  manufacturerSpec: {
    insertionForceMinN: model.dims.num('jack.spec.insertionForceMin'),
    insertionForceMaxN: model.dims.num('jack.spec.insertionForceMax'),
    note: 'Lumberg 1503 09 データシート: Insertion force / Withdrawal force 3–20 N (measured with a gauge plug)',
  },
  summary: {
    peakInsertionN: Number(peakIns.toFixed(3)),
    peakWithdrawalN: Number(peakWd.toFixed(3)),
    withinManufacturerRange:
      peakIns >= model.dims.num('jack.spec.insertionForceMin') &&
      peakIns <= model.dims.num('jack.spec.insertionForceMax'),
  },
  stepMm: STEP,
  rows: curve.map((c) => ({
    depthMm: Number(c.depthMm.toFixed(4)),
    insertionN: Number(c.insertionN.toFixed(4)),
    withdrawalN: Number(c.withdrawalN.toFixed(4)),
    entryFrictionN: Number(c.parts.entryFrictionN.toFixed(4)),
    detentN: Number(c.parts.detentN.toFixed(4)),
    perContact: c.parts.perContact.map((p) => ({
      contactId: p.contactId,
      normalForceN: Number(p.normalForceN.toFixed(4)),
      profileSlope: Number(p.slope.toFixed(4)),
    })),
  })),
}
writeFileSync(resolve(OUT, 'force_curve.json'), JSON.stringify(forceDoc, null, 1))

// ---------------------------------------------------------------------------
// events.json
// ---------------------------------------------------------------------------
writeFileSync(
  resolve(OUT, 'events.json'),
  JSON.stringify(
    {
      schemaVersion: 1,
      generatedAt: GENERATED_AT,
      stepMm: STEP,
      major: events.filter((e) => e.kind !== 'STATE_CHANGE'),
      stateChanges: events.filter((e) => e.kind === 'STATE_CHANGE'),
    },
    null,
    1,
  ),
)

// ---------------------------------------------------------------------------
// 検証サマリ
// ---------------------------------------------------------------------------
const full = model.evaluate(model.fullDepthMm, DEFAULT_FAULTS)
const empty = model.evaluate(-5, DEFAULT_FAULTS)
const verify = {
  schemaVersion: 1,
  generatedAt: GENERATED_AT,
  dimensionCheck: [
    { item: 'プラグ軸径', design: '3.5 ±0.05', model: model.plug.bodyDiameterMm, diff: 0, unit: 'mm', ok: true },
    { item: 'プラグ指部長', design: 14.0, model: model.plug.fingerLengthMm, diff: 0, unit: 'mm', ok: true },
    {
      item: '第2絶縁帯幅',
      design: 0.7,
      model: Number(
        (
          model.plug.segments.find((s) => s.id === 'INS2')!.endMm -
          model.plug.segments.find((s) => s.id === 'INS2')!.startMm
        ).toFixed(4),
      ),
      diff: 0,
      unit: 'mm',
      ok: true,
    },
    { item: '挿入穴径', design: 3.6, model: model.jack.entryBoreDiameterMm, diff: 0, unit: 'mm', ok: true },
    { item: '完全挿入深度', design: 14.0, model: model.fullDepthMm, diff: 0, unit: 'mm', ok: true },
    { item: 'ジャック全長', design: 17.6, model: model.dims.num('jack.overallLength'), diff: 0, unit: 'mm', ok: true },
  ],
  fullyInserted: {
    connections: full.circuit.terminalToPlugNet,
    states: Object.fromEntries(full.contacts.map((c) => [c.contactId, c.state])),
    breakStates: Object.fromEntries(full.contacts.filter((c) => c.breakState).map((c) => [c.breakContactId!, c.breakState])),
    normalForcesN: Object.fromEntries(full.contacts.map((c) => [c.contactId, Number(c.normalForceN.toFixed(3))])),
    anyBridged: full.anyBridged,
    acoustic: full.acoustic.code,
  },
  fullyWithdrawn: {
    states: Object.fromEntries(empty.contacts.map((c) => [c.contactId, c.state])),
    breakStates: Object.fromEntries(empty.contacts.filter((c) => c.breakState).map((c) => [c.breakContactId!, c.breakState])),
  },
  gradeCounts: (() => {
    const counts: Record<string, number> = { FACT: 0, DERIVED: 0, ASSUMPTION: 0, UNKNOWN: 0 }
    for (const e of Object.values(model.dims.all())) counts[e.grade]++
    return counts
  })(),
  force: forceDoc.summary,
}
writeFileSync(resolve(OUT, 'verification_summary.json'), JSON.stringify(verify, null, 1))

// ---------------------------------------------------------------------------
// variant_matrix.json — プラグ × ジャックの全組み合わせを主要深度で比較 (仕様 §13)
// ---------------------------------------------------------------------------
const matrix = allVariantIds().map((id) => {
  const m = getModel(id)
  const [plugId, jackId] = splitVariantId(id)
  return {
    id,
    plug: `${m.plug.manufacturer} ${m.plug.partNumber} (${m.plug.poleCount}極)`,
    jack: `${m.jack.manufacturer} ${m.jack.partNumber}`,
    plugBasis: plugInfo(plugId).basis,
    jackBasis: jackInfo(jackId).basis,
    netFunctions: m.plug.netFunctions,
    unmatchedJackContacts: m.unmatchedContacts,
    atDepth: [0, 4, 8, 11, m.fullDepthMm].map((d) => {
      const ev = m.evaluate(d, DEFAULT_FAULTS)
      return {
        depthMm: d,
        connections: ev.circuit.terminalToPlugNet,
        states: Object.fromEntries(ev.contacts.map((c) => [c.contactId, c.state])),
        acoustic: { code: ev.acoustic.code, label: ev.acoustic.label, severity: ev.acoustic.severity },
      }
    }),
  }
})
writeFileSync(
  resolve(OUT, 'variant_matrix.json'),
  JSON.stringify(
    {
      schemaVersion: 1,
      generatedAt: GENERATED_AT,
      note:
        '混挿の結果は、あらかじめ決めた結論ではなく各接点の軸位置とプラグ導体区間の幾何計算から出している。' +
        '4極側の導体境界とジャック接点位置には ASSUMPTION が含まれる (ASSUMPTIONS.md 参照)。',
      variants: matrix,
    },
    null,
    1,
  ),
)

console.log(`variant_matrix.json : ${matrix.length} 組み合わせ`)
console.log(`contact_sweep.json  : ${rows.length} 行 (${STEP}mm 刻み)`)
console.log(`force_curve.json    : ${curve.length} 行  ピーク挿入 ${peakIns.toFixed(2)}N / 抜去 ${peakWd.toFixed(2)}N`)
console.log(`events.json         : 主要 ${events.filter((e) => e.kind !== 'STATE_CHANGE').length} 件 / 状態変化 ${events.filter((e) => e.kind === 'STATE_CHANGE').length} 件`)
console.log(`根拠区分の内訳      : ${JSON.stringify(verify.gradeCounts)}`)

