const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

function inline(s) {
  let t = esc(s)
  t = t.replace(/`([^`]+)`/g, (_, c) => `<code>${c}</code>`)
  t = t.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, a, b) => `<a href="${b}">${a}</a>`)
  t = t.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  // esc() で潰れた改行タグだけを戻す（表セル内の折り返しに使っている）
  t = t.replace(/&lt;br\s*\/?&gt;/g, '<br>')
  return t
}

export function renderToString(mdPath, title) {
  const md = readFileSync(resolve(mdPath), 'utf8')
  const lines = md.split('\n')
const out = []
let i = 0
const flushPara = (buf) => { if (buf.length) out.push(`<p>${inline(buf.join(' '))}</p>`) }
let para = []

while (i < lines.length) {
  const L = lines[i]

  if (/^```/.test(L)) {
    flushPara(para); para = []
    const body = []
    i++
    while (i < lines.length && !/^```/.test(lines[i])) { body.push(lines[i]); i++ }
    i++
    out.push(`<pre><code>${esc(body.join('\n'))}</code></pre>`)
    continue
  }

  if (/^---+$/.test(L.trim())) { flushPara(para); para = []; out.push('<hr>'); i++; continue }

  const h = L.match(/^(#{1,4})\s+(.*)$/)
  if (h) {
    flushPara(para); para = []
    const lv = h[1].length
    const id = 's' + out.filter((x) => /^<h2/.test(x)).length
    out.push(lv === 2 ? `<h2 id="${id}">${inline(h[2])}</h2>` : `<h${lv}>${inline(h[2])}</h${lv}>`)
    i++; continue
  }

  if (/^>\s?/.test(L)) {
    flushPara(para); para = []
    const body = []
    while (i < lines.length && /^>\s?/.test(lines[i])) { body.push(lines[i].replace(/^>\s?/, '')); i++ }
    out.push(`<div class="note">${body.filter(Boolean).map((b) => `<p>${inline(b)}</p>`).join('')}</div>`)
    continue
  }

  if (/^\|/.test(L) && /^\|[\s:|-]+\|$/.test(lines[i + 1] ?? '')) {
    flushPara(para); para = []
    const cells = (r) => r.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim())
    const head = cells(L)
    const align = cells(lines[i + 1]).map((a) => (a.startsWith(':') && a.endsWith(':') ? ' style="text-align:center"' : a.endsWith(':') ? ' class="num"' : ''))
    i += 2
    const rows = []
    while (i < lines.length && /^\|/.test(lines[i])) { rows.push(cells(lines[i])); i++ }
    out.push(
      '<div class="tw"><table><thead><tr>' +
        head.map((c, k) => `<th${align[k] ?? ''}>${inline(c)}</th>`).join('') +
        '</tr></thead><tbody>' +
        rows.map((r) => '<tr>' + r.map((c, k) => `<td${align[k] ?? ''}>${inline(c)}</td>`).join('') + '</tr>').join('') +
        '</tbody></table></div>',
    )
    continue
  }

  if (/^\s*-\s+\[[ x]\]\s/.test(L)) {
    flushPara(para); para = []
    const items = []
    while (i < lines.length && /^\s*-\s+\[[ x]\]\s/.test(lines[i])) {
      const done = /\[x\]/.test(lines[i])
      items.push(`<li><input type="checkbox" disabled${done ? ' checked' : ''}> ${inline(lines[i].replace(/^\s*-\s+\[[ x]\]\s/, ''))}</li>`)
      i++
    }
    out.push(`<ul class="chk">${items.join('')}</ul>`)
    continue
  }

  if (/^\s*[-*]\s+/.test(L)) {
    flushPara(para); para = []
    const items = []
    while (i < lines.length && (/^\s*[-*]\s+/.test(lines[i]) || (/^\s{2,}\S/.test(lines[i]) && items.length))) {
      if (/^\s*[-*]\s+/.test(lines[i])) items.push(inline(lines[i].replace(/^\s*[-*]\s+/, '')))
      else items[items.length - 1] += ' ' + inline(lines[i].trim())
      i++
    }
    out.push(`<ul>${items.map((x) => `<li>${x}</li>`).join('')}</ul>`)
    continue
  }

  if (/^\s*\d+\.\s+/.test(L)) {
    flushPara(para); para = []
    const items = []
    while (i < lines.length && (/^\s*\d+\.\s+/.test(lines[i]) || (/^\s{3,}\S/.test(lines[i]) && items.length))) {
      if (/^\s*\d+\.\s+/.test(lines[i])) items.push(inline(lines[i].replace(/^\s*\d+\.\s+/, '')))
      else items[items.length - 1] += ' ' + inline(lines[i].trim())
      i++
    }
    out.push(`<ol>${items.map((x) => `<li>${x}</li>`).join('')}</ol>`)
    continue
  }

  if (L.trim() === '') { flushPara(para); para = []; i++; continue }
  para.push(L.trim()); i++
}
flushPara(para)

  // --- 目次 -----------------------------------------------------------
  // 見出しの id は上の変換で既に振ってある (h2 のみ)。ここは拾うだけ。
  const toc = []
  for (const block of out) {
    const m = /^<h2 id="([^"]+)">([\s\S]*?)<\/h2>$/.exec(block)
    if (m) toc.push({ id: m[1], text: m[2].replace(/<[^>]+>/g, '') })
  }
  const tocHtml = toc.length
    ? `<nav class="toc">\n  <h2>目次</h2>\n  <ol>\n` +
      toc.map((t) => `    <li><a href="#${t.id}">${t.text}</a></li>`).join('\n') +
      `\n  </ol>\n</nav>\n`
    : ''
  const withIds = out

  const html = `<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${title}</title>
${STYLE}
<style>
  ul.chk{list-style:none;padding-left:2px}
  ul.chk li{margin-bottom:7px}
  ul.chk input{margin-right:9px;transform:translateY(1px)}
  h4{font-size:15px;margin:22px 0 8px;color:var(--ink-2)}
  table td{font-size:14px}
</style>
</head>
<body>
<div class="wrap">
${tocHtml}${withIds.join('\n')}
</div>
</body>
</html>
`
  return { html, blocks: out.length, tocItems: toc.length }
}

/** 生成して書き出す。**HTML は Markdown の派生物なので、手で編集しない。** */
function render(mdPath, htmlPath, title) {
  const { html, blocks, tocItems } = renderToString(mdPath, title)
  writeFileSync(resolve(htmlPath), html)
  console.log(`  ${htmlPath}  ${html.length} bytes / ブロック ${blocks} / 目次 ${tocItems} 項目`)
}

// **import されたときは書き出さない**（checkDocNumbers.mjs が同期検査で読み込むため）
if (process.argv[1] && process.argv[1].endsWith('mdToHtml.mjs')) {
  console.log('docs/*.html を Markdown から生成')
  for (const t of TARGETS) render(t.md, t.html, t.title)
}

/**
 * `verifiedPhysical` を、**記録から機械で決める。**
 *
 * 2026-08-06 まで `scripts/exportHalfPlugProfile.ts` のリテラル `false` だった。
 * schema の説明は「true にできるのは実測記録が伴う場合のみ」だけで、
 * **何を何点測れば足りるのかが定義されていなかった。**
 * つまり実態は「誰かがリテラルを書き換えたら true」で、**検証ではなかった。**
 *
 * 条文は `docs/VERIFIED_PHYSICAL_GATE.md`。ここはその実装である。
 *
 * **予測は呼び出し側が渡す。**この module はモデルを読まない。
 * 生成器が「いま計算したモデルの予測」を渡すので、
 * **モデルが動けば判定もやり直される**（古い予測と照合し続けることがない）。
 *
 * ---
 * **条文 v2（2026-08-06）で 3 つ直した。**外部監査の反例をこちらで再現してから直している。
 *
 * | | v1 で何が起きたか | v2 |
 * |---|---|---|
 * | 相反記録 | 一致する記録を 1 件見つけた時点で `break` していたので、**同じ台帳でも並び順で結果が変わり、矛盾する記録があっても `true`** | 全候補を評価し、順序に依存しない。一致と矛盾が併存したら `AMBIGUOUS`（＝ `false`） |
 * | 分解能 | `resolutionMm > 0` しか見ていないので、**許容 0.29 mm の判定を分解能 1.0 mm の測定器が通った** | 観測点ごとに `maxResolutionMm` を置き、超えたら**認定しない** |
 * | 主張の範囲 | `verifiedPhysical: true` が「その接点トポロジーを実物で確かめた」と読めた | `claimScope` を出力し、**幾何の観測点が合っただけ**であることを機械可読にする |
 */

export const GATE_VERSION = 2
export const GATE_DOCUMENT = 'docs/VERIFIED_PHYSICAL_GATE.md'
export const LEDGER_PATH = 'docs/measurements/measurement-records.v1.json'

/**
 * **この判定が何を主張しているか。**（条文 v2 第9条）
 *
 * `verifiedPhysical: true` が言うのは「**条文が名指しした幾何量が、モデルの予測と合った**」まで。
 * 接点トポロジー（どの端子がどの導体と繋がるか・GND が開放か・短絡が無いか）も、
 * 音響特性も、**この判定では確かめていない。**
 */
export const CLAIM_SCOPE = 'geometry-only'

/** 将来ここが増えたら、増えたぶんだけ別に測る。**`verifiedPhysical` は geometry しか担わない** */
export const CLAIM_SCOPES_NOT_COVERED = ['target-topology', 'acoustic', 'lot-variation']

/**
 * 分解能の要求は**許容の 1/3 以下**から出す（条文 v2 第5条）。
 * 目盛が許容と同じ粗さだと、量子化の誤差だけで許容帯を食い尽くしてしまい、
 * **「合った」が測定器の粗さの結果なのかモデルの正しさなのか分けられない。**
 */
export const RESOLUTION_DIVISOR = 3

/** 実際の測定器の刻みへ**切り下げる**（0.0967 のような要求値は道具の側に存在しない） */
const INSTRUMENT_STEPS = [0.001, 0.002, 0.005, 0.01, 0.02, 0.05, 0.1, 0.2, 0.5, 1]
function maxResolutionFor(toleranceMm) {
  const want = toleranceMm / RESOLUTION_DIVISOR
  const usable = INSTRUMENT_STEPS.filter((s) => s <= want + 1e-12)
  return usable.length ? usable[usable.length - 1] : INSTRUMENT_STEPS[0]
}

/**
 * 観測点の定義。
 *
 * `toleranceMm` は**その観測点で見分けたい差の 1/5** を基準に置いた。
 * 例えば `L` は本モデルと実在部品 PS000001 の予測が 1.45 mm 離れているので 0.29 mm。
 * **判定に効かない桁を要求しない**ためで、これ以上厳しくすると
 * 「測ってもらったのに弾く」ことになる。
 *
 * `maxResolutionMm` は許容から導く（→ `maxResolutionFor`）。**手で書かない。**
 */
export const OBSERVATIONS = {
  L_FIRST_CONTACT_SHOULDER_GAP_MM: {
    variantId: 'TRRS-CTIA|JACK-TRRS',
    label: '4極ジャックの L 端子が、プラグ Tip 導体と最初に導通するときの肩すき間',
    unit: 'mm',
    toleranceMm: 0.29,
    discriminatesMm: 1.45,
    why: '**このプロジェクトで最も重い未確認事項**（UNKNOWNS §5-2）を直接決める。'
      + '本モデルの予測 2.14 mm と実在部品 PS000001 由来の予測 0.69 mm が 1.45 mm 離れており、'
      + 'ノギスの分解能 0.01 mm の 145 倍なので、測り慣れていなくても結果が動かない',
    procedure: 'docs/VERIFICATION_PLAN.md §2-2',
  },
  RING_BREAK_OPEN_DEPTH_MM: {
    variantId: 'TRS|JACK-TRS',
    label: 'Ring 側ブレーク接点が最初に開く深さ（ピン2 ↔ ピン4）',
    unit: 'mm',
    toleranceMm: 0.3,
    discriminatesMm: 1.5,
    why: 'ジャックだけで測れて、Ring 接点ばねの軸位置がそのまま出る',
    procedure: 'docs/VERIFICATION_PLAN.md §1',
  },
  TIP_BREAK_OPEN_DEPTH_MM: {
    variantId: 'TRS|JACK-TRS',
    label: 'Tip 側ブレーク接点が開く深さ（ピン3 ↔ ピン5）',
    unit: 'mm',
    toleranceMm: 0.3,
    discriminatesMm: 1.5,
    why: '同上。Tip 接点ばねの軸位置に効く',
    procedure: 'docs/VERIFICATION_PLAN.md §1',
  },
}
for (const o of Object.values(OBSERVATIONS)) o.maxResolutionMm = maxResolutionFor(o.toleranceMm)

/**
 * profile ごとの必須観測点。
 *
 * **ここに載っていない profile は必ず `false` になる**（fail closed）。
 * 「必須が 0 件だから全部満たしている」で `true` になると、
 * **profile を足しただけで検証済みを名乗れてしまう。**
 */
export const REQUIRED_FOR_PROFILE = {
  'TRS|JACK-TRS': ['RING_BREAK_OPEN_DEPTH_MM', 'TIP_BREAK_OPEN_DEPTH_MM'],
  'TRS|JACK-TRRS': ['L_FIRST_CONTACT_SHOULDER_GAP_MM'],
}

const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s)
const mean = (a) => a.reduce((x, y) => x + y, 0) / a.length
const round4 = (x) => +x.toFixed(4)

/**
 * 記録 1 件が使えるかを見る。**予測との一致は見ない**（→ `evaluateGate`）。
 * 理由を全部返す。最初の 1 個で止めると、直しても次が出る。
 *
 * **「使えない」を 2 つに分ける（条文 v2 第3条）。**
 *
 * - `valid: false` … 記録として壊れている。**中身を読まない**
 * - `certifiable: false` … 記録は読めるが、**認定には足りない**（分解能が粗い・目盛に乗っていない）
 *
 * 分けるのは、**粗い測定でもモデルとの食い違いは検出できる**ため。
 * 分解能 1.0 mm の測定でも「1.45 mm ずれている」は言える。
 * それを「使えない記録」として捨てると、**モデルの誤りを見逃す。**
 */
export function checkRecord(rec) {
  const reasons = []
  const notCertifiable = []
  const obs = OBSERVATIONS[rec?.observation]
  if (!obs) reasons.push(`観測点 ${rec?.observation} は定義されていない`)
  const retracted = rec?.retracted === true
  if (obs && rec?.variantId !== obs.variantId) {
    reasons.push(`variantId が観測点の定義（${obs.variantId}）と違う`)
  }
  const v = rec?.valuesMm
  if (!Array.isArray(v) || v.length < 3) reasons.push('生値が 3 回に満たない')
  else if (!v.every((x) => typeof x === 'number' && Number.isFinite(x))) reasons.push('生値に数でないものがある')
  const res = rec?.instrument?.resolutionMm
  if (!(typeof res === 'number' && res > 0)) reasons.push('測定器の分解能が書かれていない')
  for (const [k, label] of [['measuredBy', '測った人'], ['measuredOn', '測定日']]) {
    if (!rec?.[k]) reasons.push(`${label}（${k}）が無い`)
  }
  if (rec?.measuredOn && !isDate(rec.measuredOn)) reasons.push('測定日が YYYY-MM-DD ではない')
  for (const [k, label] of [['jack', 'ジャック'], ['plug', 'プラグ']]) {
    if (!rec?.parts?.[k]) reasons.push(`${label}の型番（parts.${k}）が無い`)
  }

  let rangeMm = null
  let meanMm = null
  const valuesOk = Array.isArray(v) && v.length >= 3
    && v.every((x) => typeof x === 'number' && Number.isFinite(x))
  if (valuesOk) {
    rangeMm = round4(Math.max(...v) - Math.min(...v))
    meanMm = round4(mean(v))
    if (obs && rangeMm > obs.toleranceMm) {
      reasons.push(`3 回のばらつき ${rangeMm} mm が許容 ${obs.toleranceMm} mm を超えている`)
    }
  }

  // --- 認定に足りるか（条文 v2 第5条）。**壊れているとは別に見る** ---
  if (obs && typeof res === 'number' && res > 0) {
    if (res > obs.maxResolutionMm + 1e-12) {
      notCertifiable.push(
        `測定器の分解能 ${res} mm では、許容 ${obs.toleranceMm} mm の判定を認定できない`
        + `（この観測点は ${obs.maxResolutionMm} mm 以下が要る＝許容の 1/${RESOLUTION_DIVISOR} 以下）。`
        + '**食い違いの検出には使うが、`verifiedPhysical` は立てない**',
      )
    }
    if (valuesOk) {
      const off = v.filter((x) => Math.abs(x - Math.round(x / res) * res) > res * 1e-3)
      if (off.length) {
        notCertifiable.push(
          `生値 ${off.join(', ')} が分解能 ${res} mm の目盛に乗っていない`
          + '（その測定器では読めない値なので、分解能か生値のどちらかが違う）',
        )
      }
    }
  }

  return {
    valid: reasons.length === 0,
    certifiable: reasons.length === 0 && notCertifiable.length === 0,
    retracted,
    reasons,
    notCertifiableReasons: notCertifiable,
    rangeMm,
    meanMm,
    resolutionMm: typeof res === 'number' && res > 0 ? res : null,
  }
}

/**
 * profile 1 本ぶんの判定。
 *
 * @param ledger      記録台帳（`docs/measurements/measurement-records.v1.json`）
 * @param profileVariantId  判定したい profile の variant
 * @param predictions {観測点ID: 現行モデルの予測値}。**渡されていない観測点は満たせない**
 *
 * **全候補を評価する。**一致を 1 件見つけても止まらない（条文 v2 第10条）。
 * 途中で止めると、後ろに矛盾する記録があっても `true` になり、
 * **同じ台帳でも並び順で結果が変わる**（外部監査 2026-08-06 の反例。こちらで再現済み）。
 */
export function evaluateGate({ ledger, profileVariantId, predictions = {} }) {
  const required = REQUIRED_FOR_PROFILE[profileVariantId]
  const satisfied = []
  const missing = []
  const ambiguous = []
  const rejected = []
  const conflicting = []
  const retracted = []
  const notCertified = []

  const records = Array.isArray(ledger?.records) ? ledger.records : []

  /**
   * **recordId の重複は台帳ごと拒む。**
   * 同じ ID が 2 つあると、判定に使った記録を後から一意に指せない
   * （`physicalVerificationRef` が指す先が 2 つになる）。
   */
  const counts = new Map()
  for (const r of records) {
    const id = r?.recordId
    if (typeof id === 'string') counts.set(id, (counts.get(id) ?? 0) + 1)
  }
  const duplicateRecordIds = [...counts].filter(([, n]) => n > 1).map(([id]) => id).sort()

  const base = {
    gateVersion: GATE_VERSION,
    claimScope: CLAIM_SCOPE,
    notCoveredByThisClaim: CLAIM_SCOPES_NOT_COVERED,
  }

  if (!required) {
    return {
      ...base,
      verified: false,
      verdict: 'UNVERIFIED',
      required: [],
      satisfied,
      missing: [`profile ${profileVariantId} の必須観測点が条文に無い（定義が無いものは検証済みにしない）`],
      ambiguous,
      rejected,
      conflicting,
      retracted,
      notCertified,
      duplicateRecordIds,
      decidedBy: [],
    }
  }

  for (const id of required) {
    const obs = OBSERVATIONS[id]
    // **並び順に依存しないよう recordId で固定する。**入力の順序が結果に出ない
    const cands = records
      .filter((r) => r?.observation === id)
      .slice()
      .sort((a, b) => String(a?.recordId ?? '').localeCompare(String(b?.recordId ?? '')))
    const predicted = predictions[id]
    const accepted = []
    let conflictsHere = 0

    for (const r of cands) {
      const recordId = typeof r?.recordId === 'string' ? r.recordId : '(id なし)'
      const c = checkRecord(r)

      // 取り下げは「壊れている」ではない。**消さずに残し、数えない**
      if (c.retracted) {
        retracted.push({ recordId, observation: id, reason: r?.retractedReason ?? null })
        continue
      }
      if (!c.valid) {
        rejected.push({ recordId, observation: id, reasons: c.reasons })
        continue
      }
      if (typeof predicted !== 'number' || !Number.isFinite(predicted)) {
        rejected.push({ recordId, observation: id, reasons: ['現行モデルの予測が渡されていない'] })
        continue
      }

      const deltaMm = round4(Math.abs(c.meanMm - predicted))
      /**
       * **食い違いの判定には測定器自身の不確かさを足す。**
       * 目盛の量子化で最大 ±分解能/2 ずれるので、それを超えた差だけを「合わない」と言う。
       * ここを許容そのものにすると、粗い測定器で測っただけで
       * **モデルが間違っていることになってしまう。**
       */
      const conflictLimit = round4(obs.toleranceMm + (c.resolutionMm ?? 0) / 2)
      if (deltaMm > conflictLimit) {
        const reasons = [
          `実測 ${c.meanMm} mm と現行モデルの予測 ${predicted} mm の差 ${deltaMm} mm が`
          + `許容 ${obs.toleranceMm} mm（測定器の不確かさ込みで ${conflictLimit} mm）を超えている。`
          + '**モデルのほうを直すこと**',
        ]
        conflicting.push({ recordId, observation: id, measuredMm: c.meanMm, predictedMm: predicted, deltaMm, reasons })
        rejected.push({ recordId, observation: id, reasons })
        conflictsHere++
        continue
      }

      // 差は許容内。**認定できるかは分解能で別に決まる**
      if (!c.certifiable) {
        notCertified.push({ recordId, observation: id, reasons: c.notCertifiableReasons })
        rejected.push({ recordId, observation: id, reasons: c.notCertifiableReasons })
        continue
      }
      if (deltaMm > obs.toleranceMm) {
        // 不確かさ込みなら矛盾しないが、許容そのものは外している。認定しない
        notCertified.push({
          recordId,
          observation: id,
          reasons: [`差 ${deltaMm} mm が許容 ${obs.toleranceMm} mm を外している（測定器の不確かさ込みなら矛盾はしない）`],
        })
        continue
      }
      accepted.push({ observation: id, recordId, measuredMm: c.meanMm, predictedMm: predicted, deltaMm, rangeMm: c.rangeMm })
    }

    if (conflictsHere > 0 && accepted.length > 0) {
      // **一致と矛盾が併存している。**どちらが正しいかは記録からは決まらない
      ambiguous.push(id)
      continue
    }
    if (!accepted.length) { missing.push(id); continue }
    satisfied.push({ ...accepted[0], recordIds: accepted.map((a) => a.recordId) })
  }

  const verdict = duplicateRecordIds.length
    ? 'INVALID_LEDGER'
    : ambiguous.length
      ? 'AMBIGUOUS'
      : missing.length
        ? 'UNVERIFIED'
        : 'VERIFIED'

  return {
    ...base,
    verified: verdict === 'VERIFIED',
    verdict,
    required,
    satisfied,
    missing,
    ambiguous,
    rejected,
    conflicting,
    retracted,
    notCertified,
    duplicateRecordIds,
    decidedBy: satisfied.flatMap((s) => s.recordIds ?? [s.recordId]),
  }
}

/**
 * profile の event 列から、この観測点の**現行モデルの予測**を取り出す。
 * `eventIdentity` で引く。**label の文字列で引かない**（文言を直すと壊れる）。
 */
export function predictionsFromEvents(events, fullDepthMm) {
  const firstBreakOpen = (subjectId) => {
    const e = (events ?? []).find(
      (x) => x?.eventIdentity?.subjectType === 'break-contact'
        && x.eventIdentity.subjectId === subjectId
        && x.eventIdentity.toState === 'BREAK_OPEN',
    )
    return e ? e.depthMm : undefined
  }
  const out = {}
  const ring = firstBreakOpen('JC_RING')
  const tip = firstBreakOpen('JC_TIP')
  if (typeof ring === 'number') out.RING_BREAK_OPEN_DEPTH_MM = ring
  if (typeof tip === 'number') out.TIP_BREAK_OPEN_DEPTH_MM = tip
  /**
   * **`L_FIRST_CONTACT_SHOULDER_GAP_MM` はここでは出せない。**
   * この観測点は 4極プラグ（`TRRS-CTIA|JACK-TRRS`）の量で、
   * 配布している profile は 3極プラグ（`TRS|JACK-TRRS`）だから、
   * **同じ event 列には現れない。**生成器が別 variant を評価して渡す。
   * 渡されなければ、その観測点は満たせない（fail closed）。
   */
  void fullDepthMm
  return out
}

/**
 * `physicalVerificationRef` に書かれた**判定に使った予測**を読み出す（v0.6.3）。
 * 形式は `predicted=OBS:値,OBS:値`。読めなければ空を返す。
 */
export function recordedPredictions(ref) {
  const token = String(ref ?? '').split(' ').find((t) => t.startsWith('predicted='))
  if (!token) return {}
  const body = token.slice('predicted='.length)
  if (!body || body === '-') return {}
  const out = {}
  for (const pair of body.split(',')) {
    const i = pair.lastIndexOf(':')
    if (i < 0) continue
    const v = Number(pair.slice(i + 1))
    if (Number.isFinite(v)) out[pair.slice(0, i)] = v
  }
  return out
}

/**
 * **配布 profile だけから、判定に使う予測を組み直す（v0.6.3・外部監査 P0-4）。**
 *
 * ## v0.6.2 で何が悪かったか
 *
 * v0.6.2 は L の予測を `artifacts/real_jack_comparison.json` から取っていた。
 * ところがこのファイルは、
 *
 * - **生成器の入力として宣言されていない**（変えても `inputDigest` も `profileId` も動かない・実測）
 * - **release asset にも入っていない**（受け手の手元には無い）
 *
 * つまり「受け手が配布物だけで判定をやり直す」ことも、
 * 「変えたら ID が動く」ことも、どちらも成り立っていなかった。
 * **P0-3 を直すために入れた依存が、別の穴を開けていた。**
 *
 * ## v0.6.3 の形
 *
 * | 観測点 | どこから出すか |
 * |---|---|
 * | `RING_BREAK_OPEN_DEPTH_MM` / `TIP_BREAK_OPEN_DEPTH_MM` | **profile 自身の event 列から計算し直す**（独立） |
 * | `L_FIRST_CONTACT_SHOULDER_GAP_MM` | profile が `physicalVerificationRef` に**記録した値** |
 *
 * **記録した値は profile の中にある。**書き換えれば `profileId` も asset の sha256 も動くので、
 * 差し替えは検算で分かる。そのうえで、**event 列から計算し直せる観測点については
 * 記録値と一致することを要求する**——検算できるものについて記録が嘘をつけないようにするため。
 *
 * **限界を明記する。**`L` は配布 profile からは計算し直せない（別 variant の量）。
 * ここで言えるのは「記録された予測との整合」までで、
 * **その予測がモデルの出力である保証は、この関数の外**（生成器と `inputDigest`）にある。
 *
 * @returns `{ predictions, problems }` — `problems` が空でなければ検証は不合格
 */
export function predictionsForValidation(profile) {
  const problems = []
  const recomputed = predictionsFromEvents(profile?.events, profile?.fullInsertionDepthMm)
  const recorded = recordedPredictions(profile?.modelLimitations?.physicalVerificationRef)

  // **計算し直せるものは、記録が合っているかを見る。**合わなければ記録のほうを信じない
  for (const [id, v] of Object.entries(recomputed)) {
    if (!(id in recorded)) {
      problems.push(`予測 ${id} が physicalVerificationRef に記録されていない（profile を作り直すこと）`)
    } else if (Math.abs(recorded[id] - v) > 1e-6) {
      problems.push(`予測 ${id} の記録値 ${recorded[id]} が、profile の event 列から計算し直した ${v} と違う`)
    }
  }
  const required = REQUIRED_FOR_PROFILE[profile?.variantId] ?? []
  for (const id of required) {
    if (!(id in recorded) && !(id in recomputed)) {
      problems.push(`必須観測点 ${id} の予測が配布物から得られない（記録も無く、計算し直せもしない）`)
    }
  }
  return { predictions: { ...recorded, ...recomputed }, problems }
}

/**
 * 実 GPU 環境でのフレームレート実測。
 *
 *   npm run perf              # 実 GPU (headed Chrome) で測る
 *   PERF_HEADLESS=1 npm run perf   # 比較用にヘッドレスでも測る
 *
 * 前提: 別ターミナルで `npm run dev` が動いていること。
 *
 * ヘッドレス Chromium は既定でソフトウェアラスタ (SwiftShader) を使うため、
 * 絶対 fps は実機の値にならない。実 GPU を使うには headed で起動する必要がある。
 */

import { chromium } from 'playwright'
import os from 'node:os'
import { mkdirSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const URL = process.env.APP_URL ?? 'http://localhost:5173'
const HEADLESS = process.env.PERF_HEADLESS === '1'
/**
 * 既定 (vsync あり) は「実際に利用者が得るフレームレート」を測る。
 * ディスプレイのリフレッシュレートが上限になるので、上限に張り付いていれば余裕があるということ。
 * PERF_UNTHROTTLED=1 にすると vsync を外し、1 フレームの実コストと低負荷モードの効果を測れる。
 */
const UNTHROTTLED = process.env.PERF_UNTHROTTLED === '1'
const FRAMES = Number(process.env.PERF_FRAMES ?? 180)

mkdirSync(resolve(process.cwd(), 'artifacts'), { recursive: true })

const args = []
if (!HEADLESS) args.push('--use-angle=metal', '--ignore-gpu-blocklist')
if (UNTHROTTLED) args.push('--disable-gpu-vsync', '--disable-frame-rate-limit')

const browser = await chromium.launch({
  headless: HEADLESS,
  channel: HEADLESS ? undefined : 'chrome',
  args,
})

/** 1 条件ぶんの測定 */
async function measureAt(page, label) {
  return await page.evaluate(
    async ([frames, name]) => {
      // 最初の数フレームは捨てる (切替直後の再コンパイル等を除くため)
      const times = []
      await new Promise((done) => {
        let last = performance.now()
        let n = 0
        const tick = () => {
          const now = performance.now()
          if (n > 10) times.push(now - last)
          last = now
          if (++n < frames) requestAnimationFrame(tick)
          else done()
        }
        requestAnimationFrame(tick)
      })
      times.sort((a, b) => a - b)
      const at = (q) => times[Math.min(times.length - 1, Math.floor(times.length * q))]
      const s = window.__r3fState
      return {
        label: name,
        samples: times.length,
        medianMs: at(0.5),
        p95Ms: at(0.95),
        p99Ms: at(0.99),
        minMs: times[0],
        // 最大値を記録しないと「フレーム落ちが無かった」を確かめようがない。
        maxMs: times[times.length - 1],
        // 1 vsync (16.7ms) の 2 倍を超えた回数 = 明確なフレーム落ち
        droppedFrames: times.filter((t) => t > 33).length,
        fps: 1000 / at(0.5),
        pixels: s ? s.gl.domElement.width * s.gl.domElement.height : -1,
        triangles: s ? s.gl.info.render.triangles : -1,
        drawCalls: s ? s.gl.info.render.calls : -1,
      }
    },
    [FRAMES, label],
  )
}

/**
 * 1 フレームの実コストを測る。
 *
 * vsync があると rAF 間隔は必ず 16.7ms に張り付くので、そこからは「余裕があるか」しか分からない。
 * ここでは gl.render() の直後に glFinish() を入れて GPU の完了を待ち、
 * 描画そのものにかかる時間を取り出す。低負荷モードの効果はこの値で比べる。
 */
async function measureRenderCost(page, label, iterations = 25) {
  return await page.evaluate(
    async ([n, name]) => {
      const s = window.__r3fState
      const gl = s.gl.getContext()
      // ウォームアップ
      for (let i = 0; i < 10; i++) {
        s.gl.render(s.scene, s.camera)
        gl.finish()
      }
      // performance.now() は 0.1ms 単位に丸められるので、1 回ずつ測ると分解能に埋もれる。
      // BATCH 回まとめて描いてから finish し、合計時間を割って 1 回あたりを出す。
      const BATCH = 40
      const t = []
      for (let i = 0; i < n; i++) {
        const a = performance.now()
        for (let k = 0; k < BATCH; k++) s.gl.render(s.scene, s.camera)
        gl.finish() // GPU の完了を待つ
        t.push((performance.now() - a) / BATCH)
      }
      t.sort((x, y) => x - y)
      return {
        label: name,
        batch: BATCH,
        medianMs: t[Math.floor(t.length / 2)],
        minMs: t[0],
        p95Ms: t[Math.floor(t.length * 0.95)],
        pixels: s.gl.domElement.width * s.gl.domElement.height,
      }
    },
    [iterations, label],
  )
}

const clickButton = async (page, label) => {
  await page.locator('button').filter({ hasText: new RegExp(`^${label}$`) }).first().click()
  await page.waitForTimeout(500)
}

const runs = []

for (const size of [
  { name: 'デスクトップ 1440x900 @2x', width: 1440, height: 900, dsf: 2 },
  { name: 'デスクトップ 1920x1080 @2x', width: 1920, height: 1080, dsf: 2 },
]) {
  const page = await browser.newPage({
    viewport: { width: size.width, height: size.height },
    deviceScaleFactor: size.dsf,
  })
  await page.goto(URL, { waitUntil: 'domcontentloaded' })
  await page.waitForSelector('.viewport canvas')
  await page.waitForFunction(() => !!window.__r3fState, null, { timeout: 15000 })
  await page.waitForTimeout(1500)

  const gpu = await page.evaluate(() => {
    const c = document.createElement('canvas')
    const gl = c.getContext('webgl2') || c.getContext('webgl')
    const dbg = gl && gl.getExtension('WEBGL_debug_renderer_info')
    return {
      renderer: dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : 'unknown',
      vendor: dbg ? gl.getParameter(dbg.UNMASKED_VENDOR_WEBGL) : 'unknown',
      dpr: window.devicePixelRatio,
    }
  })

  // 完全挿入で静止
  await page.evaluate(() => {
    const sl = document.querySelector('input[aria-label="挿入深度"]')
    const set = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set
    set.call(sl, '14')
    sl.dispatchEvent(new Event('input', { bubbles: true }))
  })
  await page.waitForTimeout(400)
  const idle = await measureAt(page, '静止 (完全挿入)')
  const costNormal = await measureRenderCost(page, '通常品質の描画コスト')

  // 自動挿入アニメ中 = 毎フレーム全接点を再評価する最も重い状態
  await page.locator('button').filter({ hasText: '自動抜去' }).first().click()
  await page.waitForTimeout(300)
  await page.locator('button').filter({ hasText: '自動挿入' }).first().click()
  await page.waitForTimeout(200)
  const animating = await measureAt(page, '挿抜アニメ中')

  // 低負荷モード (dpr=1 / アンチエイリアス無し)
  await clickButton(page, '低負荷モード')
  const lowIdle = await measureAt(page, '低負荷モード (静止)')
  const costLow = await measureRenderCost(page, '低負荷モードの描画コスト')

  runs.push({ viewport: size, gpu, idle, animating, lowIdle, costNormal, costLow })
  await page.close()
}

await browser.close()

const suffix = (HEADLESS ? 'headless' : 'real_gpu') + (UNTHROTTLED ? '_unthrottled' : '')

// 測定環境は実行時に取得する。ここを固定文字列にすると、別のマシンで回した人の
// 成果物に「実際には測っていない環境」が書き込まれてしまう。
const host = [os.type(), os.release(), os.arch(), `${os.cpus()[0]?.model ?? 'unknown CPU'} x${os.cpus().length}`]
  .filter(Boolean)
  .join(' / ')

const doc = {
  schemaVersion: 1,
  generatedAt: new Date().toISOString().slice(0, 10),
  mode: (HEADLESS ? 'headless (比較用)' : 'headed Chrome (実 GPU)') + (UNTHROTTLED ? ' / vsync 解除' : ' / vsync あり'),
  host,
  gpu: runs[0]?.gpu?.renderer ?? 'unknown',
  loadAverage1min: os.loadavg()[0],
  note: HEADLESS
    ? 'ヘッドレス Chromium はソフトウェアラスタを使うため、絶対 fps は実機の値ではない。'
    : '実 GPU を使う headed Chrome での測定。ディスプレイのリフレッシュレートが上限になる (vsync)。',
  runs,
}
writeFileSync(resolve(process.cwd(), `artifacts/perf_${suffix}.json`), JSON.stringify(doc, null, 1))

console.log(`\n=== ${doc.mode} ===`)
for (const r of runs) {
  console.log(`\n--- ${r.viewport.name} (devicePixelRatio=${r.gpu.dpr}) ---`)
  console.log(`GPU : ${r.gpu.renderer}`)
  console.log(`形状: ${r.idle.triangles} 三角形 / ${r.idle.drawCalls} draw call`)
  for (const m of [r.idle, r.animating, r.lowIdle]) {
    console.log(
      `${m.label.padEnd(20)} 中央値 ${m.medianMs.toFixed(2).padStart(6)}ms  ` +
        `(${m.fps.toFixed(0).padStart(3)} fps)  p95 ${m.p95Ms.toFixed(2).padStart(6)}ms  ` +
        `最速 ${m.minMs.toFixed(2)}ms  ${(m.pixels / 1e6).toFixed(2)}Mpx`,
    )
  }
  console.log(`${r.costNormal.label.padEnd(20)} 中央値 ${r.costNormal.medianMs.toFixed(3).padStart(6)}ms  (${(r.costNormal.pixels/1e6).toFixed(2)}Mpx)`)
  console.log(`${r.costLow.label.padEnd(20)} 中央値 ${r.costLow.medianMs.toFixed(3).padStart(6)}ms  (${(r.costLow.pixels/1e6).toFixed(2)}Mpx)`)
  const gain = r.costNormal.medianMs / r.costLow.medianMs
  const pxRatio = r.costNormal.pixels / r.costLow.pixels
  console.log(`低負荷モードの効果: 描画コスト ${gain.toFixed(2)}倍速 (画素数は ${pxRatio.toFixed(2)}分の1)。16.7ms 予算に対する使用率 ${(r.costNormal.medianMs/16.7*100).toFixed(0)}% → ${(r.costLow.medianMs/16.7*100).toFixed(0)}%`)
}

/**
 * テスターで実際に測れる「端子間の導通」に変換した予測を出す。
 *   npx vite-node scripts/predictProbe.ts
 *
 * 接点の内部状態 (CLOSED / WRONG_SEGMENT ...) はテスターでは見えない。
 * 見えるのは「ジャックのこのピンと、プラグのこの電極が導通しているか」だけである。
 * 実物と突き合わせるには、モデルの出力をその形に落とす必要がある。
 */

import { getModel } from '../src/data'
import { DEFAULT_FAULTS } from '../src/model/contact'
import type { PlugNet } from '../src/model/types'

const model = getModel('TRS|JACK-TRS')
const STEP = 0.01
const FULL = model.fullDepthMm

/** 測定できるチャンネル: [表示名, 判定関数] */
type Channel = { name: string; probe: string; read: (d: number) => string }

const netsOf = (d: number, termId: string): PlugNet[] =>
  model.evaluate(d, DEFAULT_FAULTS).circuit.terminalToPlugNet[termId] ?? []

const breakOf = (d: number, contactId: string): string => {
  const c = model.evaluate(d, DEFAULT_FAULTS).contacts.find((x) => x.contactId === contactId)!
  return c.breakState === 'BREAK_OPEN' ? '開' : '閉'
}

