/**
 * artifact が「どの入力から作られたか」を記録する。
 *
 * ## なぜ revision だけでは足りないか
 *
 * 2026-08-03 の統合オーダー P0-1 の指摘。監査時の HEAD は `ba58b4c` だったのに、
 * コミット済み profile は `sourceRevision: 5adf454` を持っていた。
 * その間にモデルデータが変わっていたので、**`sourceRevision` が実際の生成入力を
 * 表していなかった。**
 *
 * かといって `sourceRevision === HEAD` を要求してはいけない。
 * **artifact を含めてコミットすると HEAD が変わるので、自己参照になる。**
 * 生成した瞬間に正しかった値が、コミットした瞬間に「古い」と判定されてしまう。
 *
 * ## そこで入力そのものを指紋にする
 *
 * `inputDigest` は**入力ファイルの中身だけ**から作る。artifact は入力ではないので、
 * artifact だけを作り直してコミットしても digest は変わらない。
 * 逆に、寸法を 1 文字でも直せば必ず変わる。
 *
 *   - `generatedFromCommit` … 生成時点の source commit。**一致の要求はしない**（参考値）
 *   - `workingTreeDirty`    … **入力ファイル**に未コミットの変更があるか
 *   - `inputDigest`         … 何から作ったかの一意な指紋。**こちらで固定する**
 *
 * Half-Plug Lab 側は `generatedFromCommit` ではなく `inputDigest` で固定してください。
 */

import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { resolve, join } from 'node:path'

/**
 * 生成器の版。**出力の形（項目・意味）を変えたら上げる。**
 * データが変わっただけでは上げない（それは inputDigest が表す）。
 *
 *   1 … 初版
 *   2 … eventId / eventIdentity / spreadStatus を追加、jackBasis.detail を追加 (2026-08-03)
 *   3 … provenance を追加 (2026-08-03)
 *   4 … 感度 artifact にも provenance を付け、profile の sensitivitySummary へ
 *       eventSpreadAvailable / globalSummaryAvailable を追加 (2026-08-03・非阻害オーダー P1-1/P1-3)
 */
export const GENERATOR_VERSION = 4

export interface InputFile {
  path: string
  sha256: string
  role: string
}

export interface Provenance {
  generatorVersion: number
  generatedFromCommit: string
  workingTreeDirty: boolean
  revisionOverride: boolean
  artifactKind: 'local' | 'release'
  inputDigestAlgorithm: 'sha256'
  inputDigest: string
  inputDigestScope: string
  /**
   * digest に混ぜた**ファイル以外の入力**。無い場合は項目ごと出さない。
   *
   * **値を記録しないと第三者が digest を再計算できない。**
   * 「先頭に setting 行を置く」と説明だけ書いても、その中身が分からなければ再現不能で、
   * 再計算できない digest は provenance の役に立たない。
   */
  inputSettings?: Record<string, string>
  inputFiles: InputFile[]
  command: string
  artifactDate: string
}

const sha256 = (buf: Buffer | string) => createHash('sha256').update(buf).digest('hex')

/** ディレクトリ配下を決定的な順で列挙する（readdir の順に依存しない） */
function walk(root: string, dir: string): string[] {
  const out: string[] = []
  for (const name of readdirSync(join(root, dir)).sort()) {
    const rel = join(dir, name)
    if (statSync(join(root, rel)).isDirectory()) out.push(...walk(root, rel))
    else out.push(rel)
  }
  return out
}

// ---------------------------------------------------------------------------
// 入力の範囲定義（v0.3.0 フォローアップ P1-2）
// ---------------------------------------------------------------------------

/**
 * **入力の範囲は 1 か所にしか書かない。**
 *
 * 2026-08-03 まで、生成側（このファイルの `add` 呼び出し）と検証側
 * （`verifyReleaseSourceInputs.mjs` の `INPUT_DIRS`）に別々の範囲が直書きされていた。
 * 検証側は `src/data` / `src/model` しか見ておらず、**manifest から `scripts/`・`schemas/`・
 * `package-lock.json` を落としても exit 0 で素通りした**（28 件中 8 件しか検出できない）。
 *
 * 片方だけを直しても、もう片方は黙ったままになる。だから両方がこのファイルを読む。
 */
export const INPUT_SCOPE_FILE = 'source-input-scope.v1.json'

/** 版と契約変更の対応表の正本。**これも入力である**（内容が変われば digest が動く） */
export const CONTRACT_MIGRATION_FILE = 'contract-migration.v1.json'

export interface InputScopeGenerator {
  schema: string
  generator: string
  usesGeneratedInputs: boolean
  note?: string
}

export interface InputScope {
  schemaVersion: number
  schemaId: string
  recursiveDirectories: string[]
  requiredExactFiles: string[]
  allowedGeneratedInputs: string[]
  excludedOutputs: string[]
  generators: Record<string, InputScopeGenerator>
  commonInputs: string[]
  notCovered: { what: string; why: string; consequence: string }[]
}

/**
 * 範囲定義を読む。**無ければ落とす。**
 *
 * 既定値へ黙って戻してはいけない。戻した瞬間、それは「範囲が狭いまま動いている」状態で、
 * まさに今回塞いだ穴そのものになる。
 */
export function loadInputScope(root: string): InputScope {
  const p = resolve(root, INPUT_SCOPE_FILE)
  let raw: string
  try {
    raw = readFileSync(p, 'utf8')
  } catch {
    throw new Error(
      `入力の範囲定義 ${INPUT_SCOPE_FILE} が読めない (${p})。\n`
        + '  既定値へ戻すことはしない。範囲が狭いまま黙って動くのが、この定義で塞いだ穴だから。',
    )
  }
  const scope = JSON.parse(raw) as InputScope
  if (scope.schemaId !== 'trs-jack-3d-source-input-scope.v1')
    throw new Error(`${INPUT_SCOPE_FILE} の schemaId が想定と違う: ${scope.schemaId}`)
  return scope
}

/**
 * パスから role を決める。**範囲定義から機械的に導く**ので、
 * ファイルを足したときに role を書き忘れることがない。
 */
export function roleOfInput(scope: InputScope, path: string): string {
  if (path === INPUT_SCOPE_FILE) return 'input-scope'
  if (path === CONTRACT_MIGRATION_FILE) return 'contract-migration'
  if (path === 'package-lock.json') return 'lockfile'
  if (scope.allowedGeneratedInputs.includes(path)) return 'sensitivity-input'
  if (path.startsWith('src/data/')) return 'model-data'
  if (path.startsWith('src/model/')) return 'model-code'
  if (path.startsWith('schemas/')) return 'schema'
  if (path.startsWith('scripts/')) return 'generator'
  return 'other'
}

/**
 * ある生成器が読む入力の一覧を、範囲定義から組み立てる。
 *
 * 共通入力（`commonInputs` + `recursiveDirectories` 配下）に、
 * その生成器固有の schema と generator を足したもの。
 * **`usesGeneratedInputs: false` の生成器には、感度 artifact を絶対に足さない**
 * （自分自身が出力になり、生成するたびに digest が変わる）。
 */
function listScopedInputs(root: string, generatorKey: string, variantSlug?: string): InputFile[] {
  const scope = loadInputScope(root)
  const g = scope.generators[generatorKey]
  if (!g) throw new Error(`${INPUT_SCOPE_FILE} に生成器 "${generatorKey}" の定義が無い`)

  const files: InputFile[] = []
  const seen = new Set<string>()
  const required = new Set(scope.requiredExactFiles)
  /**
   * @param path 入力のパス
   *
   * **`requiredExactFiles` のものが読めなければ落とす。**
   * 黙って飛ばすと、その入力**抜きの** digest ができあがる。
   * 値は変わるのに理由がどこにも残らないので、あとから追えない。
   * 範囲外（`recursiveDirectories` 配下や生成物）は、無くても digest に影響させない。
   */
  const add = (path: string) => {
    if (seen.has(path)) return
    try {
      files.push({ path, sha256: sha256(readFileSync(resolve(root, path))), role: roleOfInput(scope, path) })
      seen.add(path)
    } catch (e) {
      if (required.has(path))
        throw new Error(
          `必須の入力 ${path} が読めない (${resolve(root, path)}): ${(e as Error).message}\n`
            + '  黙って飛ばすと、この入力を含まない inputDigest ができる。\n'
            + `  範囲定義から外すなら ${INPUT_SCOPE_FILE} の requiredExactFiles を直すこと。`,
        )
      // 範囲外のものは記録しない。存在しない入力は digest に影響させない
    }
  }

  for (const f of scope.commonInputs) add(f)
  add(g.schema)
  add(g.generator)
  for (const dir of scope.recursiveDirectories) {
    try {
      for (const f of walk(root, dir)) add(f)
    } catch {
      // 範囲定義にあるがこの木には無いディレクトリ。digest には影響させない
    }
  }
  if (g.usesGeneratedInputs && variantSlug) {
    add(`artifacts/sensitivity.${variantSlug}.json`)
    // 3極 profile は総合解析も使う (プラトー間隔・Tip 橋絡しきい値・挿抜力)
    if (variantSlug === 'trs_jack_trs') add('artifacts/sensitivity.json')
  }
  return files.sort((a, b) => a.path.localeCompare(b.path))
}

/**
 * digest の対象。**ここに artifact の出力先を入れてはいけない**（自己参照になる）。
 *
 * `artifacts/sensitivity.json` だけは例外で、**入力として読んでいる**ので入れる
 * （events[].spreadMm の元データ）。感度解析を回し直せば digest が変わるのが正しい。
 */
/**
 * profile の入力。
 *
 * **感度 artifact は variant のものだけを入力にする（統合フォローアップ P1-2）。**
 * 2026-08-03 まで、全 variant が単一の `artifacts/sensitivity.json` を入力にしていた。
 * そのため **3極の感度を測り直しただけで 4極 profile の ID まで変わって**いた。
 * 中身が変わっていないのに ID が変わるのは、受け手に無駄な引き直しをさせる。
 *
 * variantSlug を渡さない場合は、どの感度 artifact も入力にしない
 * （check:stale のように variant を跨いで digest を比べる用途で使う）。
 */
export function listInputs(root: string, variantSlug?: string): InputFile[] {
  return listScopedInputs(root, 'profile', variantSlug)
}

/**
 * **感度 artifact の入力**（非阻害フォローアップ P1-1）。
 *
 * profile 用の `listInputs` とは対象が違う。感度 artifact は
 * `scripts/sensitivityEvents.ts` がモデルを振って作るので、schema も exporter も入力ではない。
 *
 * **ここに `artifacts/sensitivity.*.json` を入れてはいけない**（自分自身が入力になる）。
 * profile 側は感度 artifact を入力として読むので入れて正しいが、向きが逆である。
 */
export function listSensitivityInputs(root: string): InputFile[] {
  return listScopedInputs(root, 'sensitivity')
}

/**
 * 目標トポロジーの頑健性 artifact の入力（非阻害フォローアップ P1-4）。
 * 感度 artifact と同じ形。schema と生成器だけが違う。
 */
export function listRobustnessInputs(root: string): InputFile[] {
  return listScopedInputs(root, 'robustness')
}

const git = (root: string, args: string[]): string | null => {
  try {
    return execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim()
  } catch {
    return null
  }
}

/**
 * **入力ファイルだけ**を見て未コミットの変更を判定する。
 *
 * 木全体を見てはいけない。artifact を作り直した直後は必ず artifact が dirty になるので、
 * 「入力は clean なのに release を拒否される」という使えない挙動になる。
 */
export function inputsAreDirty(root: string, files: InputFile[]): boolean {
  const out = git(root, ['status', '--porcelain', '--', ...files.map((f) => f.path)])
  return out === null ? false : out.length > 0
}

/**
 * release artifact を作ってよいかの判定。**規則だけを切り出してある。**
 *
 * `buildProvenance` の中に埋めたままだと、テストするのに
 * 「入力が汚れている git リポジトリ」を用意しないといけない。
 * 作業ツリーの状態でテストの成否が変わるので、規則をここへ出す。
 */
export function assertReleaseAllowed(release: boolean, dirty: boolean, detail = ''): void {
  if (!release || !dirty) return
  throw new Error(
    '入力ファイルに未コミットの変更がある。release artifact は clean な入力からしか作れない。\n'
      + '  変更をコミットしてから、もう一度 --release を付けて実行する。\n'
      + `  ${detail}`,
  )
}

export interface ProvenanceOptions {
  root: string
  /** 感度 artifact を variant 単位で入力に含めるためのスラグ */
  variantSlug?: string
  /** 既定 (profile 用 `listInputs`) ではなくこの一覧を入力とする。感度 artifact 用 */
  inputs?: InputFile[]
  /**
   * **ファイルに現れない variant 固有の設定**を digest に混ぜる。
   *
   * 感度 artifact は 3極も4極も同じスクリプト・同じモデルデータから作られるので、
   * ファイルの中身だけを指紋にすると **2 つの variant の digest が同一になる**。
   * それでは「どちらの解析か」を digest で固定できない
   * （非阻害オーダー P1-1 の「variant別input digest」要件）。
   */
  settings?: Record<string, string>
  command: string
  artifactDate: string
  release: boolean
  /** SOURCE_REVISION による上書きを許すか。通常モードでは許さない */
  allowRevisionOverride: boolean
  envRevision?: string
}

export function buildProvenance(o: ProvenanceOptions): Provenance {
  const inputFiles = o.inputs ?? listInputs(o.root, o.variantSlug)
  const head = git(o.root, ['rev-parse', 'HEAD']) ?? 'UNKNOWN'
  const dirty = inputsAreDirty(o.root, inputFiles)

  // --- revision の上書き ---------------------------------------------------
  // 素通しにすると、古い値を渡したまま「その改訂から作った」と名乗れてしまう。
  // 一致しているなら無害なので通す。食い違っていて許可も無いなら止める。
  let commit = head
  let override = false
  if (o.envRevision) {
    if (o.envRevision === head) {
      // 実際の HEAD と同じ。上書きとして扱う必要が無い
    } else if (o.allowRevisionOverride) {
      commit = o.envRevision
      override = true
    } else {
      throw new Error(
        `SOURCE_REVISION=${o.envRevision} が実際の HEAD (${head}) と食い違っている。\n`
          + '  古い改訂を名乗った artifact ができるので、通常モードでは受け付けない。\n'
          + '  意図してやる場合だけ --unsafe-revision-override を付ける。',
      )
    }
  }

  // --- release モードは clean な入力からしか作らせない -----------------------
  assertReleaseAllowed(o.release, dirty, git(o.root, ['status', '--porcelain', '--', ...inputFiles.map((f) => f.path)]) ?? '')

  // settings 行は先頭に置き、キーの昇順で並べる（並び順で digest が変わらないようにする）
  const settingLines = Object.entries(o.settings ?? {})
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([k, v]) => `setting  ${k}=${v}`)
  const manifest = [...settingLines, ...inputFiles.map((f) => `${f.sha256}  ${f.path}`)].join('\n')
  return {
    generatorVersion: GENERATOR_VERSION,
    generatedFromCommit: commit,
    workingTreeDirty: dirty,
    revisionOverride: override,
    artifactKind: o.release ? 'release' : 'local',
    inputDigestAlgorithm: 'sha256',
    inputDigest: sha256(manifest),
    inputDigestScope:
      (settingLines.length
        ? `先頭に "setting  <key>=<value>" を key 昇順で ${settingLines.length} 行置き、続けて `
        : '')
      + 'inputFiles を path の昇順に並べ、"<sha256>  <path>" を改行で連結した文字列の sha256。'
      + (settingLines.length
        ? 'setting 行は**ファイルに現れない variant 固有の設定**で、これが無いと variant 間で digest が同一になる。'
        : 'variant は含まない (profileId 側が持つ)。')
      + '**生成される artifact 自身は含まない。**',
    ...(settingLines.length ? { inputSettings: o.settings } : {}),
    inputFiles,
    command: o.command,
    artifactDate: o.artifactDate,
  }
}

/** scripts/robustnessWindows.mjs の型。実体は .mjs 側にある（正本は 1 つ） */

export interface RobustnessWindow {
  startMm: number
  lastSampleMm: number
  endExclusiveMm: number
  widthMm: number
}

/** 窓 1 つ分の不変条件。**エラー文字列の配列**を返す（空なら合格） */
export declare function checkWindow(w: RobustnessWindow, stepMm: number, where: string): string[]

/** artifact 全体の窓（nominalConfiguration と counterExamples の両方）を見る */
export declare function checkWindowInvariants(a: unknown): string[]

/**
 * `topology-robustness` の窓の不変条件。**schema では書けない規則をここに置く。**
 *
 * ## なぜ切り出したか（v0.3.0 フォローアップ P1-4）
 *
 * schema は「その項目があるか」「型が合うか」しか言えない。
 * **`lastSampleMm` と `endExclusiveMm` の大小関係は draft-07 では書けない**
 * （項目どうしを比べる書き方が無い）。
 *
 * すると受け手は「schema を通ったから窓は正しい」と読んでしまう。
 * だから *どこで捕まえるのか* を、fixture で実演できる形にする——
 * 旧語彙 (`toMm`) は schema が、端点の大小は意味検査がそれぞれ捕まえる。
 *
 * `validateProfiles.mjs`（本番の検証）と `test/robustnessWindowFixtures.test.ts`
 * （fixture の実演）が**同じこの関数**を呼ぶ。別々に書くと、fixture が通っても
 * 本番が通るとは限らなくなる。
 */

/**
 * 窓 1 つ分の不変条件。**エラー文字列の配列**を返す（空なら合格）。
 *
 * @param {{startMm:number,lastSampleMm:number,endExclusiveMm:number,widthMm:number}} w
 * @param {number} stepMm 走査の刻み
 * @param {string} where エラー文につける場所の名前
 */
export function checkWindow(w, stepMm, where) {
  const errs = []
  const num = (k) => typeof w?.[k] === 'number' && Number.isFinite(w[k])
  for (const k of ['startMm', 'lastSampleMm', 'endExclusiveMm', 'widthMm'])
    if (!num(k)) errs.push(`${where}: ${k} が数値でない (${JSON.stringify(w?.[k])})`)
  if (errs.length) return errs

  // **旧 v1 の語彙が残っていないこと。**`toMm` は「最後に当たった標本の位置」で、
  // 区間の終端ではなかった。同じ「終わり」という語で 2 つの違う量を指していた
  for (const legacy of ['fromMm', 'toMm'])
    if (legacy in w) errs.push(`${where}: 旧 v1 の項目 ${legacy} が残っている`)

  if (w.lastSampleMm < w.startMm)
    errs.push(`${where}: lastSampleMm ${w.lastSampleMm} が startMm ${w.startMm} より小さい`)

  /**
   * **最後の標本は区間の終端より必ず手前にある。**
   * `lastSampleMm === endExclusiveMm` は「終端でも観測した」という意味になり、
   * EXCLUSIVE の約束と矛盾する。**schema では書けない条件はここが唯一の砦。**
   */
  if (w.lastSampleMm >= w.endExclusiveMm)
    errs.push(
      `${where}: lastSampleMm ${w.lastSampleMm} が endExclusiveMm ${w.endExclusiveMm} 以上。`
        + 'endExclusiveMm は区間の外側なので、標本がそこに乗ることはない (EXCLUSIVE)',
    )

  const wantEnd = +(w.lastSampleMm + stepMm).toFixed(4)
  if (Math.abs(w.endExclusiveMm - wantEnd) > 1e-6)
    errs.push(`${where}: endExclusiveMm ${w.endExclusiveMm} が lastSampleMm + stepMm (${wantEnd}) と合わない`)

  const wantWidth = +(w.endExclusiveMm - w.startMm).toFixed(4)
  if (Math.abs(w.widthMm - wantWidth) > 1e-6)
    errs.push(`${where}: widthMm ${w.widthMm} が endExclusiveMm − startMm (${wantWidth}) と合わない`)

  return errs
}

/**
 * artifact 全体の窓を見る。`nominalConfiguration` と `counterExamples` の両方。
 *
 * @param {object} a topology-robustness artifact
 * @returns {string[]} エラー文字列（空なら合格）
 */
export function checkWindowInvariants(a) {
  const errs = []
  if (a.windowEndConvention !== 'EXCLUSIVE') errs.push(`windowEndConvention が ${a.windowEndConvention}`)
  const all = [
    ...(a.nominalConfiguration?.windows ?? []).map((w) => ['nominalConfiguration', w]),
    ...(a.counterExamples ?? []).flatMap((c) => (c.windows ?? []).map((w) => [c.label ?? c.kind, w])),
  ]
  for (const [where, w] of all) errs.push(...checkWindow(w, a.stepMm, where))
  return errs
}

/** scripts/schemaLanguageDiff.mjs の型。実体は .mjs 側にある（正本は 1 つ） */

/** 差分 1 件。pointer は **schema への JSON Pointer** */
export interface SchemaDiffFact {
  kind: 'WIDEN' | 'NARROW' | 'UNDEC'
  /** 人が読む位置。`$.a.b[].c` 形式 */
  path: string
  /** schema への JSON Pointer。`/properties/a/items/properties/c` */
  pointer: string
  detail: string
}

export interface SchemaDiff {
  /** BUMP = 版を上げる / HOLD_RECORD = 据え置き可だが記録する / HOLD = 据え置き可 */
  verdict: 'BUMP' | 'HOLD_RECORD' | 'HOLD'
  facts: SchemaDiffFact[]
}

/**
 * **判定器が正しく扱えると宣言した keyword（allowlist）。**
 * 宣言外の keyword が schema に現れたらテストが落ちる。
 */
export declare const HANDLED_KEYWORDS: Set<string>

export declare const WIDEN: 'WIDEN'
export declare const NARROW: 'NARROW'
export declare const UNDEC: 'UNDEC'

export declare function diffSchemaObjects(oldSchema: unknown, newSchema: unknown): SchemaDiff
export declare function diffSchemaFiles(oldPath: string, newPath: string): SchemaDiff

/** JSON Pointer を解決する（`$ref` を辿る）。**存在しなければ undefined** */
export declare function resolvePointer(root: unknown, pointer: string): unknown

/**
 * schema の「言語」が広がったか狭まったかを機械で決める。
 *   node scripts/schemaLanguageDiff.mjs <旧schema> <新schema>
 *
 * ## 何のためか
 *
 * 版を上げるかどうかを **artifact の中身に依存させないため**である。
 *
 * 最初に書いた条文は「旧 schema を pin した consumer が**今の artifact**を拒むか」だった。
 * これを実測すると判定できるように見えるが、**同じ schema 変更でも artifact 次第で反転する**。
 *
 *   v0.3.0 schema × 現物 (role に input-scope を使う)          → 拒む   → 「上げる」
 *   v0.3.0 schema × role を input-scope から戻した同じ artifact → 受ける → 「据え置き可」
 *                                                    (書き換えたのは 1 項目だけ)
 *
 * つまり enum に値を足しても、その版の artifact がまだ使っていなければ据え置きが許され、
 * **使い始めた版で突然止まる**。破壊的変更の記録が「いつ壊したか」ではなく
 * 「いつ使い始めたか」にずれる。
 *
 * だから判定は **新旧 2 つの schema だけ**で行う。条文は docs/SCHEMA_VERSIONING_POLICY.md。
 *
 * ## 判定
 *
 *   BUMP         新 ⊄ 旧 (広がった / 決められない) → 版を上げる
 *   HOLD_RECORD  新 ⊊ 旧 (狭まった)               → 据え置き可。ただし記録する
 *   HOLD         新 = 旧                          → 据え置き可
 *
 * ## 出力の 2 つのパス
 *
 *   path     $.provenance.inputFiles[].role     人が読む位置 (instance 寄り)
 *   pointer  /properties/provenance/.../enum    **schema への JSON Pointer**
 *
 * pointer は contractMigration の記録と schema 実物を突き合わせるために要る
 * (test/contractMigration.test.ts の検査①)。
 *
 * ## 限界
 *
 * JSON Schema の言語包含は一般には決定不能なので、**これは保守的な近似**である。
 * 決められない変更 (pattern の書き換え・oneOf の変更・未対応キーワード) は
 * すべて BUMP 側へ倒す。「上げなくてよいのに上げる」誤りは残る。
 *
 * **v0.5.0 までは「逆 (上げるべきなのに据え置く) は起きない」と書いていたが、それは嘘だった。**
 * `oneOf` の枝を index 同士で比較しており、枝を狭めたのに全体は広がる場合を
 * HOLD_RECORD と誤判定していた (外部監査で ajv 付きの反例が出た。下の oneOf の節)。
 * v0.5.1 で `oneOf` は変更があれば無条件 UNDEC へ倒すようにした。
 *
 * **同じ形の穴が他にも残っている可能性は消えていない。**
 * 「危険側の誤りは起きない」と再び書かないこと。言えるのは
 * 「**いま反例が見つかっている経路は塞いだ**」までである。
 *
 * $ref は辿るが、循環参照は打ち切って UNDEC にする (黙って通さない)。
 */

import { readFileSync } from 'node:fs'

export const WIDEN = 'WIDEN'
export const NARROW = 'NARROW'
export const UNDEC = 'UNDEC'

const NEUTRAL_KEYS = ['description', 'title', '$comment', '$schema', '$id', 'examples', 'default']
const LOWER_BOUNDS = ['minimum', 'exclusiveMinimum', 'minLength', 'minItems', 'minProperties']
const UPPER_BOUNDS = ['maximum', 'exclusiveMaximum', 'maxLength', 'maxItems', 'maxProperties']
/**
 * **判定器が正しく扱えると宣言した keyword。allowlist である。**
 *
 * v0.5.1 までは「知らない keyword が**変わったら**倒す」形だった。
 * これでは、**変わっていない keyword が他の keyword の意味を変える**場合を取りこぼす。
 * 実際に外部監査が 3 件出した（patternProperties が居ると項目削除は狭まらない、など）。
 *
 * v0.5.2 からは **宣言外の keyword が「在る」だけで倒す**（かつその節が変わっていれば）。
 * 宣言集合は現行 schema が実際に使う keyword を機械で数えて決めた
 * (test/schemaVersioningPolicy.test.ts の ①-d が、宣言外が現れたら落とす)。
 *
 * **ここへ足すときは、判定器が本当にその keyword を扱えるようにしてから足すこと。**
 * 足すだけでは、倒れていたものが倒れなくなるだけである。
 */
export const HANDLED_KEYWORDS = new Set([
  ...NEUTRAL_KEYS,
  ...LOWER_BOUNDS,
  ...UPPER_BOUNDS,
  'type', 'enum', 'const', 'required', 'properties', 'items', 'additionalProperties',
  'pattern', 'uniqueItems', 'oneOf', 'anyOf', 'allOf', 'definitions', '$defs', '$ref',
])

const REF_LIMIT = 50

/** JSON Pointer のトークンを escape する (RFC 6901) */
const tok = (k) => String(k).replace(/~/g, '~0').replace(/\//g, '~1')

class Diff {
  constructor() {
    this.facts = []
  }

  add(kind, path, pointer, detail) {
    this.facts.push({ kind, path, pointer, detail })
  }

  get verdict() {
    const kinds = new Set(this.facts.map((f) => f.kind))
    if (kinds.has(WIDEN) || kinds.has(UNDEC)) return 'BUMP'
    if (kinds.has(NARROW)) return 'HOLD_RECORD'
    return 'HOLD'
  }
}

/** $ref を辿る。辿れない・深すぎるときは目印を返し、呼び出し側で UNDEC にする */
function deref(node, root) {
  let n = 0
  while (node && typeof node === 'object' && !Array.isArray(node) && '$ref' in node && Object.keys(node).length === 1) {
    const ref = node.$ref
    if (typeof ref !== 'string' || !ref.startsWith('#/')) return { __unresolvable__: String(ref) }
    let cur = root
    for (const part of ref.slice(2).split('/')) {
      cur = cur && typeof cur === 'object' ? cur[part] : undefined
      if (cur === undefined) return { __unresolvable__: ref }
    }
    node = cur
    if (++n > REF_LIMIT) return { __unresolvable__: `${ref} (循環している可能性)` }
  }
  return node
}

const typesOf = (node) => {
  const t = node.type
  if (t === undefined) return null
  return new Set(Array.isArray(t) ? t : [t])
}

const isSuperset = (a, b) => [...b].every((x) => a.has(x))
const sorted = (s) => [...s].sort()

/**
 * 集合の包含で widen / narrow を決める。
 * widenIfSuperset=false は「集合が増えると狭まる」もの (required がこれ)。
 */
function cmpSets(d, path, ptr, kw, oldSet, newSet, widenIfSuperset = true) {
  const p = `${ptr}/${kw}`
  if (oldSet.size === newSet.size && isSuperset(oldSet, newSet)) return
  const grew = isSuperset(newSet, oldSet)
  const shrank = isSuperset(oldSet, newSet)
  const added = () => sorted(new Set([...newSet].filter((x) => !oldSet.has(x))))
  const removed = () => sorted(new Set([...oldSet].filter((x) => !newSet.has(x))))
  if (grew) {
    d.add(widenIfSuperset ? WIDEN : NARROW, path, p, `${kw}: 値が増えた ${JSON.stringify(added())}`)
  } else if (shrank) {
    d.add(widenIfSuperset ? NARROW : WIDEN, path, p, `${kw}: 値が減った ${JSON.stringify(removed())}`)
  } else {
    d.add(UNDEC, path, p, `${kw}: 入れ替わった -${JSON.stringify(removed())} +${JSON.stringify(added())}`)
  }
}

function compare(o, n, oroot, nroot, path, ptr, d, seen) {
  o = deref(o, oroot)
  n = deref(n, nroot)
  const obj = (x) => x && typeof x === 'object' && !Array.isArray(x)
  if (!obj(o) || !obj(n)) {
    if (JSON.stringify(o) !== JSON.stringify(n)) {
      d.add(UNDEC, path, ptr, `schema でない値が変わった: ${JSON.stringify(o)} -> ${JSON.stringify(n)}`)
    }
    return
  }
  if ('__unresolvable__' in o || '__unresolvable__' in n) {
    d.add(UNDEC, path, ptr, `$ref を解決できない (${o.__unresolvable__ ?? n.__unresolvable__})`)
    return
  }
  if (seen.has(ptr)) return
  seen.add(ptr)

  // --- type ---
  const ot = typesOf(o)
  const nt = typesOf(n)
  if (JSON.stringify(ot && sorted(ot)) !== JSON.stringify(nt && sorted(nt))) {
    if (ot === null) d.add(NARROW, path, `${ptr}/type`, `type: 制約が付いた ${JSON.stringify(sorted(nt))}`)
    else if (nt === null) d.add(WIDEN, path, `${ptr}/type`, 'type: 制約が外れた')
    else cmpSets(d, path, ptr, 'type', ot, nt)
  }

  // --- enum / const ---
  if ('enum' in o || 'enum' in n) {
    if (!('enum' in o)) d.add(NARROW, path, `${ptr}/enum`, `enum: 制約が付いた ${JSON.stringify(n.enum)}`)
    else if (!('enum' in n)) d.add(WIDEN, path, `${ptr}/enum`, 'enum: 制約が外れた')
    else cmpSets(d, path, ptr, 'enum', new Set(o.enum.map((v) => JSON.stringify(v))), new Set(n.enum.map((v) => JSON.stringify(v))))
  }
  if ('const' in o || 'const' in n) {
    const p = `${ptr}/const`
    if (!('const' in o)) d.add(NARROW, path, p, `const: 固定された ${JSON.stringify(n.const)}`)
    else if (!('const' in n)) d.add(WIDEN, path, p, 'const: 固定が外れた')
    else if (JSON.stringify(o.const) !== JSON.stringify(n.const)) {
      d.add(UNDEC, path, p, `const: 値が変わった ${JSON.stringify(o.const)} -> ${JSON.stringify(n.const)}`)
    }
  }

  // --- required: 増えると狭まる ---
  cmpSets(d, path, ptr, 'required', new Set(o.required ?? []), new Set(n.required ?? []), false)

  // --- additionalProperties ---
  const oap = o.additionalProperties ?? true
  const nap = n.additionalProperties ?? true
  const apPtr = `${ptr}/additionalProperties`
  if (typeof oap === 'boolean' && typeof nap === 'boolean') {
    if (oap !== nap) d.add(nap ? WIDEN : NARROW, path, apPtr, `additionalProperties: ${oap} -> ${nap}`)
  } else if (typeof oap === 'boolean' || typeof nap === 'boolean') {
    d.add(UNDEC, path, apPtr, 'additionalProperties: bool と schema が入れ替わった')
  } else {
    compare(oap, nap, oroot, nroot, `${path}.additionalProperties`, apPtr, d, seen)
  }

  // --- properties ---
  const op = o.properties ?? {}
  const np = n.properties ?? {}
  for (const k of Object.keys(np).filter((x) => !(x in op)).sort()) {
    const p = `${ptr}/properties/${tok(k)}`
    if (oap === false) d.add(WIDEN, `${path}.${k}`, p, '項目の追加: 旧は additionalProperties:false なのでこの key は禁止だった')
    else if (oap === true) d.add(NARROW, `${path}.${k}`, p, '項目の追加: 旧は無制約だったが新は型が付いた')
    /**
     * **旧の additionalProperties が schema のときは「無制約」ではない。**
     * その key は additionalProperties の schema の制約下にあった。
     * 明示 property へ移すと、新しい型が旧の制約より広いことも狭いこともある。
     * v0.5.1 までは NARROW と決め打ちしていて、**広がる場合を据え置き可と誤判定した。**
     */
    else d.add(UNDEC, `${path}.${k}`, p, '項目の追加: 旧は additionalProperties の schema の制約下にあった (広狭を機械判定しない)')
  }
  for (const k of Object.keys(op).filter((x) => !(x in np)).sort()) {
    const p = `${ptr}/properties/${tok(k)}`
    if (nap === false) d.add(NARROW, `${path}.${k}`, p, '項目の削除: 新は additionalProperties:false なのでこの key は禁止になる')
    else if (nap === true) d.add(WIDEN, `${path}.${k}`, p, '項目の削除: 新では無制約になる')
    else d.add(UNDEC, `${path}.${k}`, p, '項目の削除: 新では additionalProperties の schema の制約下に入る (広狭を機械判定しない)')
  }
  for (const k of Object.keys(op).filter((x) => x in np).sort()) {
    compare(op[k], np[k], oroot, nroot, `${path}.${k}`, `${ptr}/properties/${tok(k)}`, d, seen)
  }

  /**
   * --- $ref に sibling がある節の参照先 ---
   *
   * `deref()` は `$ref` が唯一の key のときしか辿らない。
   * そのため **sibling がある節（profile v3 の evidenceGrade がこれ）は、
   * 節自体が同じまま参照先だけ変わっても何も見えなかった。**
   *
   * 節が変わっていれば下の allowlist ゲートが倒す。ここで見るのは
   * **節は同じで参照先だけ変わった**場合である。
   * `definitions` を丸ごと走査する形にすると、`deref` 経由で見えている変更と
   * 二重に出るので採らない（記録側が同じ差分を 2 か所へ書く羽目になる）。
   */
  for (const [node, isOld] of [[o, true], [n, false]]) {
    if (!('$ref' in node) || Object.keys(node).length === 1) continue
    const other = isOld ? n : o
    if (!('$ref' in other) || other.$ref !== node.$ref) continue // 参照先が違うならゲートが倒す
    if (!isOld) continue // 1 回だけ比べる
    const a = deref({ $ref: node.$ref }, oroot)
    const b = deref({ $ref: other.$ref }, nroot)
    compare(a, b, oroot, nroot, `${path}(ref)`, `${ptr}/$ref`, d, seen)
  }

  // --- items ---
  if ('items' in o || 'items' in n) {
    const p = `${ptr}/items`
    if (!('items' in o)) d.add(NARROW, path, p, 'items: 要素に制約が付いた')
    else if (!('items' in n)) d.add(WIDEN, path, p, 'items: 要素の制約が外れた')
    else compare(o.items, n.items, oroot, nroot, `${path}[]`, p, d, seen)
  }

  // --- 数値境界 ---
  for (const kw of LOWER_BOUNDS) {
    const ov = o[kw]
    const nv = n[kw]
    if (ov === nv) continue
    const p = `${ptr}/${kw}`
    if (ov === undefined) d.add(NARROW, path, p, `${kw}: 下限が付いた (${nv})`)
    else if (nv === undefined) d.add(WIDEN, path, p, `${kw}: 下限が外れた (${ov})`)
    else d.add(nv > ov ? NARROW : WIDEN, path, p, `${kw}: ${ov} -> ${nv}`)
  }
  for (const kw of UPPER_BOUNDS) {
    const ov = o[kw]
    const nv = n[kw]
    if (ov === nv) continue
    const p = `${ptr}/${kw}`
    if (ov === undefined) d.add(NARROW, path, p, `${kw}: 上限が付いた (${nv})`)
    else if (nv === undefined) d.add(WIDEN, path, p, `${kw}: 上限が外れた (${ov})`)
    else d.add(nv > ov ? WIDEN : NARROW, path, p, `${kw}: ${ov} -> ${nv}`)
  }

  // --- pattern / uniqueItems ---
  if (o.pattern !== n.pattern) {
    const p = `${ptr}/pattern`
    if (o.pattern === undefined) d.add(NARROW, path, p, `pattern: 制約が付いた ${JSON.stringify(n.pattern)}`)
    else if (n.pattern === undefined) d.add(WIDEN, path, p, `pattern: 制約が外れた ${JSON.stringify(o.pattern)}`)
    else d.add(UNDEC, path, p, `pattern: 書き換わった (包含は機械判定しない) ${JSON.stringify(o.pattern)} -> ${JSON.stringify(n.pattern)}`)
  }
  const ou = o.uniqueItems ?? false
  const nu = n.uniqueItems ?? false
  if (ou !== nu) d.add(nu ? NARROW : WIDEN, path, `${ptr}/uniqueItems`, `uniqueItems: ${ou} -> ${nu}`)

  /**
   * --- oneOf ---
   *
   * **枝を狭めても全体が狭まるとは限らない。**`oneOf` は「ちょうど 1 枝が一致」なので、
   * 枝の言語について単調ではない。実測した反例:
   *
   *   旧  oneOf: [{integer}, {number, minimum: 0}]
   *   新  oneOf: [{integer}, {number, minimum: 1}]
   *
   *   値 0    旧 invalid (2 枝が一致するので oneOf は落ちる) → 新 valid  **広がった**
   *   値 0.5  旧 valid                                    → 新 invalid 狭まった
   *
   * 枝を index 同士で再帰比較していた v0.5.0 までの実装は、これを
   * 「minimum が上がった = NARROW」とだけ見て **HOLD_RECORD** を返していた。
   * **危険な向き (上げるべきなのに据え置く) の誤りである。**
   *
   * 一般の包含判定を作る必要は無い。**変更があれば無条件で BUMP 側へ倒す。**
   */
  if (JSON.stringify(o.oneOf) !== JSON.stringify(n.oneOf)) {
    d.add(
      UNDEC,
      path,
      `${ptr}/oneOf`,
      'oneOf: 変わった (「ちょうど 1 枝」は枝の言語について単調でないので、枝ごとの比較では決められない)',
    )
  }

  /**
   * --- anyOf / allOf ---
   *
   * こちらは和と積なので**枝ごとに単調である**。
   * 各枝が狭まれば ∪ も ∩ も狭まり、各枝が広がれば逆も同じ。
   * 枝が混在すれば WIDEN と NARROW が両方立ち、verdict は BUMP になる (安全側)。
   * so 枝ごとの再帰比較で健全。
   */
  for (const kw of ['anyOf', 'allOf']) {
    const ol = o[kw]
    const nl = n[kw]
    if (JSON.stringify(ol) === JSON.stringify(nl)) continue
    if (!ol || !nl || ol.length !== nl.length) {
      d.add(UNDEC, path, `${ptr}/${kw}`, `${kw}: 枝の数が変わった (包含は機械判定しない)`)
    } else {
      ol.forEach((a, i) => compare(a, nl[i], oroot, nroot, `${path}.${kw}[${i}]`, `${ptr}/${kw}/${i}`, d, seen))
    }
  }

  /**
   * --- allowlist ゲート（v0.5.2）---
   *
   * **宣言外の keyword が「在る」だけで倒す。**変わったかどうかではない。
   * 変わっていない keyword が、他の keyword の意味を変えることがあるためである
   * （patternProperties が居ると、明示 property を消しても禁止にならない）。
   *
   * ただし**その節が新旧でまったく同じなら倒さない。**言語も同じだからで、
   * ここを倒すと同一 schema 同士の比較まで BUMP になり、条文が使えなくなる。
   */
  const reasons = []
  for (const k of [...new Set([...Object.keys(o), ...Object.keys(n)])].sort()) {
    if (!HANDLED_KEYWORDS.has(k)) reasons.push(`未対応キーワード ${k}`)
  }
  // **$ref に sibling があると deref が辿らない。**辿らないまま他の keyword だけ比べても意味がない
  for (const [label, node] of [['旧', o], ['新', n]]) {
    if ('$ref' in node && Object.keys(node).length > 1) reasons.push(`${label}の $ref に sibling がある`)
  }
  if (reasons.length > 0 && JSON.stringify(o) !== JSON.stringify(n)) {
    d.add(UNDEC, path, ptr, `扱えない構文があり、この節が変わっている (${[...new Set(reasons)].join(' / ')}) — 判定できないので BUMP 側へ倒す`)
  }
}

/** 2 つの schema オブジェクトを比べる */
export function diffSchemaObjects(oldSchema, newSchema) {
  const d = new Diff()
  compare(oldSchema, newSchema, oldSchema, newSchema, '$', '', d, new Set())
  return { verdict: d.verdict, facts: d.facts }
}

/** 2 つの schema ファイルを比べる */
export function diffSchemaFiles(oldPath, newPath) {
  return diffSchemaObjects(JSON.parse(readFileSync(oldPath, 'utf8')), JSON.parse(readFileSync(newPath, 'utf8')))
}

/**
 * JSON Pointer を解決する。**存在しなければ undefined**（呼び出し側で落とすこと）。
 *
 * 途中で `$ref` に当たったら辿る。**diff が出す pointer は展開後の位置**なので、
 * 辿らないと `/properties/provenance/properties/...` のような位置が
 * 「実在しない」と誤判定される（provenance は #/definitions/provenance への $ref）。
 */
export function resolvePointer(root, pointer) {
  if (pointer === '') return root
  if (!pointer.startsWith('/')) return undefined
  let cur = root
  for (const raw of pointer.slice(1).split('/')) {
    const part = raw.replace(/~1/g, '/').replace(/~0/g, '~')
    cur = deref(cur, root)
    if (cur === null || typeof cur !== 'object' || '__unresolvable__' in cur) return undefined
    cur = Array.isArray(cur) ? cur[Number(part)] : cur[part]
    if (cur === undefined) return undefined
  }
  return deref(cur, root)
}

const invokedDirectly = process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop())
if (invokedDirectly && process.argv.length >= 4) {
  const r = diffSchemaFiles(process.argv[2], process.argv[3])
  console.log(r.verdict)
  for (const f of r.facts) console.log(`  ${f.kind.padEnd(6)} ${f.path}\n         ${f.pointer}\n         ${f.detail}`)
  process.exit(r.verdict === 'BUMP' ? 1 : 0)
}

