const breakEffect = [0.01, 0.03, 0.05, 0.1, 0.2, 0.35, 0.4].map((v) => {
  const m = buildModelWithOverrides(V3, { 'jack.break.ring.openDeflection': v })
  const d = firstBreakOpen(m, 'JC_RING')
