for (const x of breakEffect) console.log(`    ${x.openDeflection} → ${x.depth === null ? '開かない' : x.depth}`)

// ---------------------------------------------------------------------------
// 7) 4極: パッド幅のしきい値 (二分法 + 深さ clamp)
// ---------------------------------------------------------------------------

const m4 = getModel(V4)
const GAPS4 = plateauGaps(m4)
const GAP3 = plateauGaps(base)
console.log(`\n  プラトー間隔: 3極 ${GAP3.join(', ')} / 4極 ${GAPS4.join(', ')}`)

function padThreshold(axialKey: string, padKey: string, contactId: string, insC: number, axial: number) {
  const ideal = insC + axial
  const depth = Math.min(ideal, m4.fullDepthMm)
  return {
    axial,
    threshold: +bisect(0.01, 6.0, (w) => {
      try {
        return bridgingAt(buildModelWithOverrides(V4, { [axialKey]: axial, [padKey]: w }), contactId, depth) !== null
      } catch {
        return false
      }
    }).toFixed(6),
    evaluatedDepthMm: +depth.toFixed(3),
    idealDepthReachable: ideal <= m4.fullDepthMm,
  }
}

/**
 * 走査する水準に、必ず既定値そのものを含める。
 * 2026-08-02 に 4極ジャックの既定値が動いたとき、直書きリストが古いままだと
 * 「いま採っている値」を一度も評価しないまま結論を出してしまう
 * (同種の取りこぼしを searchTopology で実際に出した)。
 */
const withShipped = (levels: number[], key: string) =>
  [...new Set([...levels, base.dims.entry(key).value])].sort((a, b) => a - b)

const padThresholds = {
  JC_RING2: withShipped([3.45, 4.0, 4.35, 5.25, 5.85, 6.0, 6.5], 'trrs.jack.contact.ring2.axialCenter').map((a) =>
    padThreshold('trrs.jack.contact.ring2.axialCenter', 'trrs.jack.contact.narrowPadWidth', 'JC_RING2', (7.8 + 8.5) / 2, a),
  ),
  JC_SLEEVE: withShipped([0.45, 1.25, 2.05, 2.85, 3.5], 'trrs.jack.contact.sleeve.axialCenter').map((a) =>
    padThreshold('trrs.jack.contact.sleeve.axialCenter', 'jack.contact.sleeve.padWidth', 'JC_SLEEVE', (10.8 + 11.5) / 2, a),
  ),
}
for (const [cid, rows] of Object.entries(padThresholds)) {
  console.log(`  ${cid}:`)
  for (const r of rows)
    console.log(
      `    位置 ${r.axial} → ${r.threshold}${r.idealDepthReachable ? '' : '  ← 理想深さが完全挿入を超える (clamp)'}`,
    )
}

// ---------------------------------------------------------------------------
// 10) 公差の「箱」の隅で Tip 橋絡のしきい値を測る
//
// §6-1 で bodyRadius だけを振ったが、段差はもう一方の端 insulatorRadius にも依る。
// そちらは DERIVED で、注記自身が図面実測 φ3.20〜3.22 という幅を認めている。
// 2 つを同時に振って、いちばん薄くなる隅を出す。
// ---------------------------------------------------------------------------

// 振り幅は台帳 (dimensions.json の tolerance) から取る。ここに数値を直書きすると、
// 台帳を直したときに解析だけ古い幅のまま残る。
const levels = (key: string, n: number) => {
  const e = base.dims.entry(key)
  // 非対称な幅は sweepRange、左右対称の公差は tolerance。両方あれば sweepRange を採る
  let lo: number
  let hi: number
  if (e.sweepRange) {
    if (e.sweepRange.length !== 2) throw new Error(`${key} の sweepRange は [min, max] の 2 要素で書く`)
    ;[lo, hi] = e.sweepRange
  } else if (e.tolerance !== undefined) {
    lo = e.value - e.tolerance
    hi = e.value + e.tolerance
  } else {
    throw new Error(`${key} に sweepRange も tolerance も無い。振り幅を決められない`)
  }
  return Array.from({ length: n }, (_, i) => +(lo + ((hi - lo) * i) / (n - 1)).toFixed(6))
}
const BODY_R = levels('plug.bodyRadius', 5) // 図面公差 φ3.5±0.05 → 半径 ±0.025
const INS_R = levels('plug.insulatorRadius', 3) // 図面実測 φ3.20〜3.22 → 半径 1.60〜1.61
console.log(`  振り幅は台帳から: bodyRadius ${BODY_R.join('/')} , insulatorRadius ${INS_R.join('/')}`)
const toleranceBox = BODY_R.flatMap((b) =>
  INS_R.map((i) => ({
    bodyDiameter: +(2 * b).toFixed(3),
    insulatorDiameter: +(2 * i).toFixed(3),
    stepHeight: +(b - i).toFixed(6),
    tipThreshold: +bisect(0, 2 * STEP_HEIGHT, (c) =>
      anyTipBridge(
        buildModelWithOverrides(V3, {
          'plug.bodyRadius': b,
          'plug.insulatorRadius': i,
          'model.contact.complianceMm': c,
        }),
      ),
    ).toFixed(6),
  })),
)
const worstCorner = toleranceBox.reduce((a, b) => (b.tipThreshold < a.tipThreshold ? b : a))

/**
 * 「実物のプラグを測ったとき、段差がどこまで薄ければ結論が崩れるか」。
 *
 * VERIFICATION_PLAN §1-1 がこの値を判定線として使うので、artifact に出して
 * 文書と機械照合できるようにしておく。段差を薄くしていって (絶縁帯半径を上げて)、
 * その compliance で実際に Tip 橋絡が始まる点を二分法で探す。
 */
function stepBreakEven(compliance: number): { stepRadius: number; diameterDiff: number } {
  const bridges = (ir: number) =>
    anyTipBridge(
      buildModelWithOverrides(V3, { 'plug.insulatorRadius': ir, 'model.contact.complianceMm': compliance }),
    )
  const body = base.plug.bodyRadiusMm
  if (bridges(1.6) || !bridges(body - 1e-4)) throw new Error(`端点が想定外 (compliance=${compliance})`)
  const ir = bisect(1.6, body, bridges)
  return { stepRadius: +(body - ir).toFixed(6), diameterDiff: +(2 * (body - ir)).toFixed(4) }
}
const breakEven = {
  note: '段差がこれより薄いと、その compliance で第1絶縁帯の Tip 橋絡が実際に起きる',
  atAdopted005: stepBreakEven(0.05),
  atRangeTop010: stepBreakEven(0.1),
}
console.log(
  `  段差の破綻点: compliance 0.05 → 直径差 ${breakEven.atAdopted005.diameterDiff} mm / ` +
    `0.10 → ${breakEven.atRangeTop010.diameterDiff} mm (公称の直径差は 0.30)`,
)
console.log('\n  公差の箱の隅で Tip 橋絡のしきい値:')
console.log(
  `    最悪 φ${worstCorner.bodyDiameter} × 絶縁 φ${worstCorner.insulatorDiameter} → ${worstCorner.tipThreshold}` +
    ` (採用 0.05 の ${(worstCorner.tipThreshold / 0.05).toFixed(2)} 倍 / 採用範囲上端 0.10 の ${(worstCorner.tipThreshold / 0.1).toFixed(2)} 倍)`,
)

// ---------------------------------------------------------------------------
// 11) 力のモデル (force.* 9 件)
//
// 初版は「対象外。calibrationScale 1 個で 3.6〜7.3 N に動く」とだけ書いていた。
// 校正係数は純粋な倍率なので、それを振っても「倍率を振れば倍率の分動く」以上の
// ことが言えない。校正係数を固定したまま、物理的な意味のある 8 件を振る。
// ---------------------------------------------------------------------------

function peakForce(ov: Record<string, number>, stepMm = 0.02) {
  const mm = buildModelWithOverrides(V3, ov)
  const curve = computeForceCurve(mm.jack, mm.plug, F, mm.contactCfg, mm.forceCfg, stepMm, -2)
  let insertion = 0
  let withdrawal = 0
  let atMm = 0
  for (const p of curve) {
    if (p.insertionN > insertion) {
      insertion = p.insertionN
      atMm = p.depthMm
    }
    if (p.withdrawalN > withdrawal) withdrawal = p.withdrawalN
  }
  return { insertion, withdrawal, atMm }
}

/** 各パラメータの「物理的に成立しうる」幅。根拠は ASSUMPTIONS D / UNKNOWNS §3-7 */
const FORCE_RANGES: Record<string, [number, number]> = {
  'force.frictionInsert': [0.2, 0.6],
  'force.frictionWithdraw': [0.2, 0.6],
  'force.entryFrictionPerMm': [0.0, 0.2],
  'force.entryFrictionMax': [0.5, 2.5],
  'force.detentPeak': [0.0, 3.0],
  'force.detentSigma': [0.2, 1.5],
  'force.differentiationStep': [0.001, 0.02],
  'force.maxRampSlope': [0.285, 0.775], // ドーム半径 1.0〜0.2mm に対応
}

const forceBaseline = peakForce({})
const forceOat = Object.entries(FORCE_RANGES).map(([key, [lo, hi]]) => ({
  key,
  lo,
  hi,
  peakAtLo: +peakForce({ [key]: lo }).insertion.toFixed(3),
  peakAtHi: +peakForce({ [key]: hi }).insertion.toFixed(3),
}))

const forceKeys = Object.keys(FORCE_RANGES)
let fLo = Infinity
let fHi = -Infinity
let belowSpec = 0
let aboveSpec = 0
let detentDominated = 0
for (let mask = 0; mask < 1 << forceKeys.length; mask++) {
  const ov: Record<string, number> = {}
  forceKeys.forEach((k, i) => {
    ov[k] = FORCE_RANGES[k][(mask >> i) & 1]
  })
  const p = peakForce(ov)
  if (p.insertion < fLo) fLo = p.insertion
  if (p.insertion > fHi) fHi = p.insertion
  if (p.insertion < 3) belowSpec++
  if (p.insertion > 20) aboveSpec++
  if (Math.abs(p.atMm - base.fullDepthMm) < 0.5) detentDominated++
}
const calibrationLinear = [1.0, 1.45, 2.0].map((s) => ({
  scale: s,
  peakN: +peakForce({ 'force.calibrationScale': s }).insertion.toFixed(3),
}))
console.log('\n  力のモデル (校正係数を固定して物理 8 件を同時に振る):')
console.log(`    既定 ${forceBaseline.insertion.toFixed(2)} N (深さ ${forceBaseline.atMm.toFixed(2)} mm)`)
console.log(`    256 通り → ${fLo.toFixed(2)} 〜 ${fHi.toFixed(2)} N`)
console.log(`    3 N 未満 ${belowSpec} / 20 N 超 ${aboveSpec} / ピークがデテント支配 ${detentDominated}`)
console.log(`    校正係数は純粋な倍率: ${calibrationLinear.map((x) => `${x.scale}→${x.peakN}`).join(' / ')}`)

// ---------------------------------------------------------------------------

/**
 * **この成果物が、どの寸法値の上で作られたかを記録する。**
 * 記録しておくと、あとから `npm run check:stale` が「モデルの値が動いたのに
 * 感度解析を回し直していない」を機械で判定できる。
 * 2026-08-03 の手順の通し確認で、パッド幅を変えたときに再実行が要ることが
 * 手順書から読み取れなかったため追加した (CONTRIBUTING.md §3)。
 * キーは、このスクリプトが実際に参照する寸法キーを列挙している。
 */
const SWEPT_KEYS = [
  'jack.contact.sleeve.axialCenter',
  'jack.contact.sleeve.padWidth',
  'jack.contact.ring.axialCenter',
  'jack.contact.tip.axialCenter',
  'jack.break.ring.openDeflection',
  'model.contact.complianceMm',
  'plug.bodyRadius',
  'plug.insulatorRadius',
  'trrs.jack.contact.ring2.axialCenter',
  'trrs.jack.contact.narrowPadWidth',
  'trrs.jack.contact.sleeve.axialCenter',
]

const out = {
  schemaVersion: 5,
  generatedBy: 'npm run sensitivity',
  inputs: Object.fromEntries(SWEPT_KEYS.map((k) => [k, base.dims.entry(k).value])),
  note:
    'しきい値は走査ではなく二分法で求めている (走査刻みが答えを変えるため)。乱数は使っていないので何度実行しても同じ結果になる。' +
    '初版 (schemaVersion 1) には手法上の欠陥が 4 つあり作り直した。scripts/sensitivity.ts の冒頭を参照。',
  stepHeightMm: +STEP_HEIGHT.toFixed(6),
  baseline: {
    firstBridgeMm: +baselineFirst.toFixed(4),
    bridgeEndMm: +baselineEnd.toFixed(4),
    widthMm: +(baselineEnd - baselineFirst).toFixed(4),
    byScanStep: byScan,
  },
  tipBridge: {
    complianceThreshold: +tipThreshold.toFixed(6),
    byMinOverlap: tipByMinOverlap,
    insideStepHeight: { tried: insideTried, tipBridgeCount: insideTip, violations: insideViolations },
    factToleranceExcursion: tolExcursion,
    toleranceBox: {
      note: 'bodyRadius (FACT 公差 φ3.5±0.05) と insulatorRadius (DERIVED 図面実測 φ3.20〜3.22) を同時に振る',
      grid: toleranceBox,
      worstCorner,
      marginVsAdopted: +(worstCorner.tipThreshold / 0.05).toFixed(3),
      marginVsAdoptedRangeTop: +(worstCorner.tipThreshold / 0.1).toFixed(3),
      breakEven,
    },
  },
  eventSpread: {
    note:
      '主要イベントごとの深さの幅。帰線接点の軸位置とパッド幅を同時に振った全構成にわたる最小・最大。' +
      'README の深さ表の全行に幅を付けるために測った。n は、その構成数のうちそのイベントが現れた回数。',
    byKind: Object.fromEntries(
      [...eventSpread.entries()].map(([k, v]) => [
        k,
        { minMm: +v.min.toFixed(4), maxMm: +v.max.toFixed(4), configs: v.n, movesMm: +(v.max - v.min).toFixed(4) },
      ]),
    ),
  },
  bridgeDepthRange: {
    joint: { configs: sjConfigs, minMm: +Math.min(...sjFirst).toFixed(4), maxMm: +Math.max(...sjFirst).toFixed(4) },
    oneAtATime: { minMm: +Math.min(...oatFirst).toFixed(4), maxMm: +Math.max(...oatFirst).toFixed(4) },
  },
  previouslyUnswept: { minOverlap: minOverlapEffect, ringBreakOpenDeflection: breakEffect },
  plateauGaps: { threePole: GAP3, fourPole: GAPS4 },
  padThresholds,
  forceModel: {
    note:
      'calibrationScale は純粋な倍率で独立した根拠を持たないため、同時振りからは外して固定した。' +
      '振ったのは物理的な意味のある 8 件。',
    baseline: {
      peakInsertionN: +forceBaseline.insertion.toFixed(3),
      peakWithdrawalN: +forceBaseline.withdrawal.toFixed(3),
      peakAtMm: +forceBaseline.atMm.toFixed(3),
    },
    ranges: FORCE_RANGES,
    oneAtATime: forceOat,
    joint: {
      configs: 1 << forceKeys.length,
      minN: +fLo.toFixed(3),
      maxN: +fHi.toFixed(3),
      belowSpec3N: belowSpec,
      aboveSpec20N: aboveSpec,
      detentDominated,
    },
    calibrationScaleIsPureMultiplier: calibrationLinear,
  },
}

const OUT = resolve(process.cwd(), 'artifacts')
mkdirSync(OUT, { recursive: true })
writeFileSync(resolve(OUT, 'sensitivity.json'), JSON.stringify(out, null, 1) + '\n')
console.log('\n  artifacts/sensitivity.json を書き出した')

/**
 * **variant ごとの**主要イベント深さの幅を測る。
 *   npm run sensitivity:events -- --variant "TRS|JACK-TRRS"
 *
 * ## なぜ分けたか（統合フォローアップ 2026-08-03 P0-1 / P0-2）
 *
 * `scripts/sensitivity.ts` は解析基準を `TRS|JACK-TRS` に固定している。
 * ところが exporter は variant を問わず単一の `artifacts/sensitivity.json` を読み、
 * その `eventSpread.byKind` を**どの profile へも配っていた。**
 *
 * 結果、TRS×TRRS profile の `FIRST_BREAK_OPEN` は
 * 名目 8.48mm なのに幅 8.06〜8.06mm（3極の値）が付いていた。
 * **名目値が自分の幅の外にある**という、あり得ない状態である。
 * Half-Plug Lab 側の fixture import で見つかった。
 *
 * `sensitivity.ts` の他の解析（プラトー間隔・Tip 橋絡しきい値・挿抜力）は
 * 3極の幾何に強く結びついており、variant 化すると差分が大きい。
 * **profile へ漏れていたのは `eventSpread` だけ**なので、そこだけを切り出した。
 *
 * ## 何を測るか
 *
 * 帰線接点の軸位置とパッド幅を**同時に**振り、成立する全構成にわたって
 * 主要イベントの深さの最小・最大を集める。**モデル内部の感度**であって、
 * 実物のばらつきでも製造公差でもない。
 */

import { mkdirSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { buildProvenance, listSensitivityInputs } from './provenance'
import { migrationFor } from './contractMigration.mjs'
import { buildModelWithOverrides, getModel, type VariantId } from '../src/data'
import { DEFAULT_FAULTS } from '../src/model/contact'
import { extractEvents, sweep } from '../src/model/sweep'
import type { TrsModel } from '../src/model/engine'

const ROOT = resolve(process.cwd())
const argv = process.argv.slice(2)
const argOf = (name: string, dflt: string): string => {
  const i = argv.indexOf(`--${name}`)
  const v = i >= 0 ? argv[i + 1] : undefined
  return v ?? dflt
}
// **`Parameters<typeof getModel>[0]` を使わない。** getModel は既定値を持つので
// その型は `VariantId | undefined` になり、buildModelWithOverrides へ渡すと型エラーになる
const VARIANT = argOf('variant', 'TRS|JACK-TRS') as VariantId
const slug = String(VARIANT).toLowerCase().replace(/[^a-z0-9]+/g, '_')
const RELEASE = argv.includes('--release')

/**
 * variant ごとの走査軸。**キーを取り違えると override が効かず、
 * 同じ構成を数百回繰り返すだけの空振りになる**（2026-08-02 に探索側で実際に起きた）。
 * 下の assertAxesBite で、動かすとモデルが変わることを実測して確かめる。
 */
const AXES_BY_JACK: Record<string, { axial: string; pad: string }> = {
  'JACK-TRS': { axial: 'jack.contact.sleeve.axialCenter', pad: 'jack.contact.sleeve.padWidth' },
  'JACK-TRRS': { axial: 'trrs.jack.contact.sleeve.axialCenter', pad: 'trrs.jack.contact.narrowPadWidth' },
}
const jackId = String(VARIANT).split('|')[1]
const AX = AXES_BY_JACK[jackId]
if (!AX) throw new Error(`${VARIANT}: 走査軸の定義が無い`)

/**
 * 走査の設定。**digest に混ぜるので、直書きせずここに集める**（非阻害オーダー P1-1）。
 * 同じ値が「実際に振る範囲」「既定値が範囲内かの判定」「出力の sweep 欄」で使われる。
 * 散らしておくと、片方だけ直したときに記録と実際が食い違う。
 */
const AXIAL_RANGE_MM: readonly [number, number] = [0.45, 4.55]
const PAD_RANGE_MM: readonly [number, number] = [0.01, 5.0]
const DIVISIONS = 30
const STEP_MM = 0.02

const base = getModel(VARIANT)

/** その軸を動かすとモデルが本当に変わるか。変わらなければ空振り */
for (const key of [AX.axial, AX.pad]) {
  const before = JSON.stringify(base.jack.contacts.map((c) => [c.axialCenterMm, c.padWidthMm]))
  const shipped = base.dims.entry(key).value
  const after = JSON.stringify(
    buildModelWithOverrides(VARIANT, { [key]: shipped + 0.5 }).jack.contacts.map((c) => [c.axialCenterMm, c.padWidthMm]),
  )
  if (before === after) throw new Error(`${VARIANT}: 軸 ${key} を動かしてもモデルが変わらない。走査が空振りになる`)
}

const fullOk = (m: TrsModel) => m.evaluate(m.fullDepthMm, DEFAULT_FAULTS).acoustic.code === 'NORMAL'

// ---------------------------------------------------------------------------
// 同時振り
// ---------------------------------------------------------------------------

const spread = new Map<string, { min: number; max: number; n: number }>()
let configs = 0
let buildFailed = 0
let notFullOk = 0

const N = DIVISIONS
for (let i = 0; i <= N; i++) {
  const a = +(AXIAL_RANGE_MM[0] + (AXIAL_RANGE_MM[1] - AXIAL_RANGE_MM[0]) * (i / N)).toFixed(4)
  for (let j = 0; j <= N; j++) {
    const w = +(PAD_RANGE_MM[0] + (PAD_RANGE_MM[1] - PAD_RANGE_MM[0]) * (j / N)).toFixed(4)
    let m: TrsModel
    try {
      m = buildModelWithOverrides(VARIANT, { [AX.axial]: a, [AX.pad]: w })
    } catch {
      buildFailed++
      continue
    }
    if (!fullOk(m)) {
      notFullOk++
      continue
    }
    configs++
    for (const ev of extractEvents(m, sweep(m, { stepMm: STEP_MM }))) {
      const cur = spread.get(ev.kind) ?? { min: Infinity, max: -Infinity, n: 0 }
      cur.min = Math.min(cur.min, ev.depthMm)
      cur.max = Math.max(cur.max, ev.depthMm)
      cur.n++
      spread.set(ev.kind, cur)
    }
  }
}

if (configs === 0)
  throw new Error(`${VARIANT}: 完全挿入が成立する構成が 1 つも無かった。幅を 0 件と報告する前に軸を見直すこと`)

// **既定値の構成が走査に含まれているか。** 含まれていないと、
// 名目値が幅の外に出る (統合フォローアップ P0-3 で見つかったのと同じ形)
const shippedA = base.dims.entry(AX.axial).value
const shippedW = base.dims.entry(AX.pad).value
const inRange = (v: number, lo: number, hi: number) => v >= lo - 1e-9 && v <= hi + 1e-9
const shippedInside = inRange(shippedA, ...AXIAL_RANGE_MM) && inRange(shippedW, ...PAD_RANGE_MM)

/**
 * **感度 artifact 自身の provenance**（非阻害オーダー P1-1）。
 *
 * v0.1.1 まで、この artifact は `generatedFromCommit` を 1 行持つだけだった。
 * その commit は release commit より前を指す（artifact をコミットすると HEAD が進むので当然）。
 * profile 側は `inputFiles[].sha256` でこの artifact の bytes を固定しているので
 * 取り込みは安全だったが、**この artifact だけを見て「何から作られたか」を再計算できなかった。**
 *
 * profile と同じ方式にする。commit の一致は要求せず、**入力の中身で固定する。**
 * `settings` を混ぜるのは、3極と4極が同じファイル群から作られるため
 * ファイルの指紋だけでは 2 つの variant が同じ digest になってしまうから。
 */
const provenance = buildProvenance({
  root: ROOT,
  inputs: listSensitivityInputs(ROOT),
  settings: {
    variantId: String(VARIANT),
    sweptParameters: `${AX.axial},${AX.pad}`,
    axialRangeMm: AXIAL_RANGE_MM.join('..'),
    padRangeMm: PAD_RANGE_MM.join('..'),
    divisions: String(DIVISIONS),
    stepMm: String(STEP_MM),
  },
  // 呼び出し方で変わらない正規化した形を記録する (byte-identical を壊さないため)
  command: `npm run sensitivity:events -- --variant "${VARIANT}"${RELEASE ? ' --release' : ''}`,
  artifactDate: process.env.ARTIFACT_DATE ?? new Date().toISOString().slice(0, 10),
  release: RELEASE,
  allowRevisionOverride: argv.includes('--unsafe-revision-override'),
  envRevision: process.env.SOURCE_REVISION,
})

const out = {
  schemaVersion: 2 as const,
  contractMigration: migrationFor('event-sensitivity.v2'),
  generatedBy: 'npm run sensitivity:events',
  // **この 3 つが今回の修正の核心。** どの variant の解析かを機械可読にする
  variantId: String(VARIANT),
  analysisScope: 'EVENT_DEPTH_SPREAD_ONLY',
  sweptParameters: [AX.axial, AX.pad],
  generatedFromCommit: provenance.generatedFromCommit,
  provenance,
  generatedAt: process.env.ARTIFACT_DATE ?? new Date().toISOString().slice(0, 10),
  basis: 'MODEL_PARAMETER_SWEEP',
  note:
    'モデル内部の感度であって、実物のばらつきでも製造公差でもない。'
    + '帰線接点の軸位置とパッド幅を同時に振り、完全挿入が成立する構成にわたって'
    + '主要イベントの深さの最小・最大を集めたもの。',
  sweep: {
    axialRangeMm: AXIAL_RANGE_MM,
    padRangeMm: PAD_RANGE_MM,
    divisions: DIVISIONS,
    stepMm: STEP_MM,
    configurationsTried: (N + 1) * (N + 1),
    configurationsUsable: configs,
    buildFailed,
    fullInsertionNotOk: notFullOk,
    shippedValues: { [AX.axial]: shippedA, [AX.pad]: shippedW },
    shippedInsideSweptRange: shippedInside,
  },
  byKind: Object.fromEntries(
    [...spread.entries()]
      .sort()
      .map(([k, v]) => [
        k,
        { minMm: +v.min.toFixed(4), maxMm: +v.max.toFixed(4), configs: v.n, movesMm: +(v.max - v.min).toFixed(4) },
      ]),
  ),
}

mkdirSync(resolve(ROOT, 'artifacts'), { recursive: true })
writeFileSync(resolve(ROOT, `artifacts/sensitivity.${slug}.json`), JSON.stringify(out, null, 1) + '\n')

console.log(`\n  ${VARIANT}`)
console.log(`  走査 ${out.sweep.configurationsTried} 構成 / 成立 ${configs} (組めず ${buildFailed} / 完全挿入不成立 ${notFullOk})`)
console.log(`  軸: ${AX.axial} × ${AX.pad}`)
console.log(`  既定値が走査範囲の中: ${shippedInside}`)
for (const [k, v] of Object.entries(out.byKind)) console.log(`    ${k.padEnd(26)} ${v.minMm} 〜 ${v.maxMm}`)
console.log(`  artifacts/sensitivity.${slug}.json を書き出した`)

/**
 * release asset を 1 か所へ集め、`SHA256SUMS` を作る。
 *   npm run release:stage -- --version v0.3.0
 *   npm run release:stage -- --version v0.3.0 --allow-local   (下見用)
 *
 * ## 何を防ぐか（非阻害フォローアップ P2-7）
 *
 * v0.1.1 では asset をその場で選んで並べ、**`event-sensitivity` schema を入れ忘れた。**
 * 一覧を `scripts/releaseAssets.mjs` に固め、ここはそれを機械的に写すだけにする。
 *
 * ## `local` な artifact は既定で拒む
 *
 * `artifactKind: 'local'` は「手元で作った」で、作業ツリーが汚れていても作れる。
 * それを release として配ると、受け手は再現できない。
 * 本番は clean checkout から `--release` 付きで作り直したものだけを使う。
 */

import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { basename, resolve } from 'node:path'
import { RELEASE_ASSETS, REMOVED_SINCE_V011 } from './releaseAssets.mjs'

const ROOT = process.cwd()
const argv = process.argv.slice(2)
const argOf = (n, d) => {
  const i = argv.indexOf(`--${n}`)
  return i >= 0 && argv[i + 1] ? argv[i + 1] : d
}
/**
 * 既定の版数は **package.json から引く**（v0.4.0 で直書きをやめた）。
 *
 * 直書きにしていたので、採番のたびにここを手で直す必要があり、
 * **v0.4.0 へ上げたときに実際に忘れた**（テストが落ちて気づいた）。
 * 忘れうるものは持たせない。
 */
const VERSION = argOf('version', `v${JSON.parse(readFileSync(resolve(ROOT, 'package.json'), 'utf8')).version}`)
const ALLOW_LOCAL = argv.includes('--allow-local')
const OUT = resolve(ROOT, argOf('out', `dist/release/${VERSION}`))

const sha256 = (p) => createHash('sha256').update(readFileSync(p)).digest('hex')
const read = (p) => JSON.parse(readFileSync(p, 'utf8'))
const git = (a) => {
  try {
    return execFileSync('git', a, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim()
  } catch {
    return 'UNKNOWN'
  }
}

// --- 揃っているか -----------------------------------------------------------
const missing = RELEASE_ASSETS.filter((a) => !existsSync(resolve(ROOT, a.path)))
if (missing.length) {
  console.log('**次の asset が存在しない。**')
  for (const m of missing) console.log(`  ${m.path}`)
  process.exit(1)
}

// **同名になる asset があると、片方が黙って上書きされる**
const names = RELEASE_ASSETS.map((a) => basename(a.path))
const dup = names.filter((n, i) => names.indexOf(n) !== i)
if (dup.length) {
  console.log(`**配布名が重複している: ${[...new Set(dup)].join(', ')}**`)
  process.exit(1)
}

/**
 * --- テストが通っていない artifact を配らせない（v0.4.1・P0-1/P0-2）-----------
 *
 * **v0.4.0 で実際にやってしまった。**テストが 2 件落ちている時点で `test:count` を回し、
 * 直したあと取り直さなかった。件数は変わらなかったので `total` の突き合わせは通り、
 * `allPassed: false` のまま公開した。
 *
 * **生成は止めない。**止めると「件数の照合が落ちている間は件数を更新できない」という
 * 循環に戻る（`scripts/testCount.mjs` の冒頭に経緯がある）。
 * 循環が起きるのは*生成*側で、*配布*側で止めればどちらの問題も起きない。
 * だからここで拒む。
 *
 * `--allow-not-ready` は形だけ確かめたいときの逃げ道で、**配ってはいけない。**
 */
const ALLOW_NOT_READY = argv.includes('--allow-not-ready')
const TEST_COUNTS = 'artifacts/test_counts.json'
if (existsSync(resolve(ROOT, TEST_COUNTS))) {
  const tc = read(resolve(ROOT, TEST_COUNTS))
  const reasons = []
  if (tc.allPassed !== true) reasons.push(`allPassed が ${JSON.stringify(tc.allPassed)}`)
  if (tc.failed !== undefined && tc.failed !== 0) reasons.push(`failed が ${tc.failed}`)
  if (tc.exitCode !== undefined && tc.exitCode !== 0) reasons.push(`exitCode が ${tc.exitCode}`)
  if (reasons.length) {
    console.log(`**${TEST_COUNTS} がテストの成功を示していない: ${reasons.join(' / ')}**`)
    console.log('  この artifact を配ると、受け手は「テストが落ちたまま出した」と読む。')
    console.log('  テストを直してから npm run test:count を**取り直す**こと。')
    console.log('  (件数が同じでも取り直しは要る。v0.4.0 はここを飛ばして allPassed: false を公開した)')
    console.log('  形だけ確かめたい場合は --allow-not-ready を付ける（**配ってはいけない**）。')
    if (!ALLOW_NOT_READY) process.exit(1)
    console.log('  --allow-not-ready が付いているので続行する。')
  }
} else {
  console.log(`**${TEST_COUNTS} が無い。**npm run test:count を回すこと。`)
  if (!ALLOW_NOT_READY) process.exit(1)
}

/**
 * release evidence 側の判定とも突き合わせる。
 * **evidence が「配布可」と言っていないものを配らない。**
 */
const VALIDATION = 'artifacts/validation-results.json'
if (existsSync(resolve(ROOT, VALIDATION))) {
  const vr = read(resolve(ROOT, VALIDATION))
  if (vr.releaseReadinessStatus !== undefined && vr.releaseReadinessStatus !== 'READY') {
    console.log(`**${VALIDATION} の releaseReadinessStatus が ${vr.releaseReadinessStatus} である。**`)
    for (const r of vr.releaseReadinessReasons ?? []) console.log(`  ${r}`)
    console.log('  npm run release:evidence を回し直すこと。')
    if (!ALLOW_NOT_READY) process.exit(1)
    console.log('  --allow-not-ready が付いているので続行する。')
  }
}

// --- local な artifact を拒む ------------------------------------------------
const localOnes = RELEASE_ASSETS.filter((a) => {
  if (!a.path.startsWith('artifacts/')) return false
  try {
    return read(resolve(ROOT, a.path)).provenance?.artifactKind === 'local'
  } catch {
    return false
  }
})
if (localOnes.length && !ALLOW_LOCAL) {
  console.log(`**artifactKind: 'local' の artifact が ${localOnes.length} 件ある。**`)
  for (const a of localOnes) console.log(`  ${a.path}`)
  console.log('\n  clean checkout から --release 付きで作り直すこと。')
  console.log('  形だけ確かめたい場合は --allow-local を付ける（配布してはいけない）。')
  process.exit(1)
}

/**
 * --- 索引の tag 情報は**ここで埋める** ------------------------------------------
 *
 * **artifact は、自分を含む commit の hash を持てない。**
 * 索引をコミットしてから tag を打つので、生成時点では tag も commit も存在しない。
 * リポジトリに置く索引は `null` のままが正しい（分からないものを埋めない）。
 *
 * 配布物では受け手が「どの tag のものか」を引けたほうがよいので、
 * **staged copy にだけ** `--commit` の値を書き込む。リポジトリ側は触らない。
 */
const INDEX_REL = 'artifacts/trs-jack-3d-release-index.v1.json'
const COMMIT = argOf('commit', null)
let stagedIndex = null
if (existsSync(resolve(ROOT, INDEX_REL))) {
  const idx = read(resolve(ROOT, INDEX_REL))
  const tag = idx.releaseTag ?? VERSION
  const commit = idx.releaseCommit ?? COMMIT
  if (!commit) {
    console.log('**tag が指す commit が分からない。**')
    console.log('  索引の releaseCommit は null のままで正しい（自分を含む commit の hash は持てない）。')
    console.log(`  配布時に渡すこと: npm run release:stage -- --version ${VERSION} --commit $(git rev-parse HEAD)`)
    process.exit(1)
  }
  if (tag !== VERSION) {
    console.log(`**release index の tag (${tag}) が --version (${VERSION}) と違う。**`)
    process.exit(1)
  }
  stagedIndex = { ...idx, releaseTag: tag, releaseCommit: commit }
}

// --- 集める -----------------------------------------------------------------
mkdirSync(OUT, { recursive: true })
const rows = []
for (const a of RELEASE_ASSETS) {
  const src = resolve(ROOT, a.path)
  const dst = resolve(OUT, basename(a.path))
  if (a.path === INDEX_REL && stagedIndex) {
    // **配布する索引にだけ tag を書き込む。**リポジトリ側は null のまま
    writeFileSync(dst, JSON.stringify(stagedIndex, null, 1) + '\n')
  } else {
    copyFileSync(src, dst)
  }
  rows.push({ name: basename(a.path), sha256: sha256(dst), role: a.role })
}

// --- SHA256SUMS --------------------------------------------------------------
const profiles = RELEASE_ASSETS.filter((a) => a.path.includes('half_plug_topology_profile'))
  .map((a) => read(resolve(ROOT, a.path)))

const header = [
  `# trs-jack-3d ${VERSION} — release asset の sha256`,
  '#',
  '# **固定には inputDigest を使ってください。**',
  '# ファイル単位の sha256 は「この配布物が改変されていないか」を見るためのものです。',
  '#',
  /**
   * **版は artifact から引く。**直書きしていたら v0.4.1 まで「schemaVersion 2」のまま残り、
   * v0.5.0 で 3 になっても気づけなかった（README が v0.1.1〜v0.4.0 で古い版を案内し続けたのと同じ型）。
   */
  `# **この版の profile は schemaVersion ${profiles[0]?.schemaVersion ?? '不明'} です。`
    + `v${(profiles[0]?.schemaVersion ?? 1) - 1} とは非互換です。**`,
  '# 対応表は profile の contractMigration.history と、同梱の contract-migration.v1.json にあります。',
  '# 旧版を期待する実装は schemaVersion を見て停止してください（沈黙より停止のほうが安全です）。',
  '#',
  ...profiles.map((p) => `# ${p.variantId.padEnd(14)} inputDigest = ${p.provenance.inputDigest}\n#                profileId   = ${p.profileId}`),
  '#',
  `# generatedFromCommit = ${profiles[0]?.provenance?.generatedFromCommit ?? git(['rev-parse', 'HEAD'])}`,
  `# artifactKind        = ${profiles[0]?.provenance?.artifactKind ?? '不明'}`,
  '#',
  '# v0.1.1 から外したもの（消えた理由）:',
  ...REMOVED_SINCE_V011.map((r) => `#   ${r.name ?? r.path} — ${r.reason}`),
  '#',
  '# 検算: shasum -a 256 -c SHA256SUMS',
  '',
].join('\n')

writeFileSync(
  resolve(OUT, 'SHA256SUMS'),
  header + rows.map((r) => `${r.sha256}  ${r.name}`).sort().join('\n') + '\n',
)

console.log(`\n  ${VERSION} の asset を ${rows.length} 件そろえた`)
for (const [role, n] of Object.entries(rows.reduce((m, r) => ({ ...m, [r.role]: (m[r.role] ?? 0) + 1 }), {})))
  console.log(`    ${role.padEnd(12)} ${n} 件`)
console.log(`  ${OUT}`)
if (ALLOW_LOCAL && localOnes.length) console.log('\n  **--allow-local で作った。配布してはいけない。**')

/**
 * テスト件数を artifact に書き出す。
 *   npm run test:count
 *
 * 何のためか:
 *   2026-08-03 までの 8 コミットすべてで、テスト件数を README / UNKNOWNS /
 *   docs/TEST_RESULTS.md の 3 か所へ手で書き写していた (24 回の手作業)。
 *   数えるのは機械にできる。docs.test.ts がこの artifact と文書を突き合わせる。
 *
 * 静的に `it(` を数えないのはなぜか:
 *   docs.test.ts は CLAIMS 表から it() を動的に生成しているため、
 *   ソースを読んで数えても実際の件数と合わない。実行結果から取る必要がある。
 */

import { execFileSync } from 'node:child_process'
import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { migrationFor } from './contractMigration.mjs'

const ROOT = process.cwd()
const TMP = resolve(ROOT, 'node_modules/.cache/test-count.json')
const OUT = resolve(ROOT, 'artifacts/test_counts.json')

/** 引けなければ `UNKNOWN`。**推測で埋めない** */
const gitHead = () => {
  try {
    return execFileSync('git', ['rev-parse', 'HEAD'], { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim()
  } catch {
    return 'UNKNOWN'
  }
}
const runnerVersion = () => {
  try {
    return JSON.parse(readFileSync(resolve(ROOT, 'node_modules/vitest/package.json'), 'utf8')).version
  } catch {
    return 'UNKNOWN'
  }
}

mkdirSync(resolve(ROOT, 'node_modules/.cache'), { recursive: true })
/**
 * **失敗しても続ける。生成は止めない。**
 *
 * vitest はテストが落ちると非ゼロで終了するが、JSON レポートは書く。
 * ここで例外にすると「件数の照合が落ちている間は件数を更新できない」という循環になる
 * (実際に一度そうなった)。件数を数えるのが目的なので、成否は記録するだけにする。
 *
 * ## 止めるのは配布側（v0.4.1・P0-1/P0-2）
 *
 * v0.4.0 では、**2 件落ちている時点でこれを回し、直したあと取り直さなかった。**
 * 件数は変わらなかったので `total` を突き合わせる検査は通り、
 * `allPassed: false` のまま公開された。
 *
 * 生成を止める設計にすると上の循環に戻るので、**生成は許して配布を止める。**
 * `npm run release:stage` が `allPassed !== true` を拒否し、
 * `validation-results.json` の `releaseReadinessStatus` にも出す。
 */
let exitCode = 0
try {
  execFileSync('npx', ['vitest', 'run', '--reporter=json', `--outputFile=${TMP}`], {
    cwd: ROOT,
    stdio: ['ignore', 'ignore', 'inherit'],
  })
} catch (e) {
  exitCode = typeof e.status === 'number' ? e.status : 1
  // レポートが書けていれば続行する。書けていなければ次の readFileSync で落ちる
}

const r = JSON.parse(readFileSync(TMP, 'utf8'))
rmSync(TMP, { force: true })

const byFile = {}
let skipped = 0
for (const f of r.testResults) {
  byFile[f.name.split('/').slice(-1)[0]] = f.assertionResults.length
  // **飛ばされたテストを数える。** 0 でないと npm run check:vacuity が落ちる。
  // 「通った」と「そもそも走っていない」を同じ緑にしないため (→ CONTRIBUTING §7)
  skipped += f.assertionResults.filter((a) => a.status === 'skipped' || a.status === 'pending').length
}
const total = Object.values(byFile).reduce((a, b) => a + b, 0)

// ARTIFACT_DATE で固定できる。既存 artifact と同じ規約
const generatedAt = process.env.ARTIFACT_DATE ?? new Date().toISOString().slice(0, 10)

mkdirSync(resolve(ROOT, 'artifacts'), { recursive: true })
writeFileSync(
  OUT,
  JSON.stringify(
    {
      schemaVersion: 2,
      contractMigration: migrationFor('test-counts.v2'),
      generatedAt,
      note:
        'npm run test:count で生成。README と UNKNOWNS には件数を書かない (読者に意味が無く、'
        + '手作業が増えるだけだった)。docs/TEST_RESULTS.md の件数だけをこの artifact と突き合わせる。'
        + 'byFile は npm run check:vacuity の下限としても使う。件数が減る変更は理由を書く。',
      total,
      byFile: Object.fromEntries(Object.entries(byFile).sort()),
      skipped,
      /**
       * **同じ実行から取る（v0.4.1・P0-1）。**
       * `allPassed` だけだと「なぜ false なのか」が残らず、
       * 直したあと取り直したかどうかも分からない。
       */
      failed: r.numFailedTests ?? 0,
      failedSuites: r.numFailedTestSuites ?? 0,
      exitCode,
      allPassed: r.numFailedTests === 0 && exitCode === 0,
      testCommand: 'npx vitest run --reporter=json',
      runner: 'vitest',
      runnerVersion: runnerVersion(),
      nodeVersion: process.version,
      generatedFromCommit: gitHead(),
    },
    null,
    1,
  ) + '\n',
)
console.log(`artifacts/test_counts.json: 合計 ${total} 件 / ${Object.keys(byFile).length} ファイル`)
for (const [k, v] of Object.entries(byFile).sort()) console.log(`  ${k.padEnd(30)} ${v}`)
if (r.numFailedTests || exitCode) {
  console.log(`\n  **失敗 ${r.numFailedTests} 件 / exit ${exitCode}。件数は記録したが、この artifact では配布できない。**`)
  console.log('  npm run release:stage が allPassed !== true を拒否する。直してから取り直すこと。')
}

/**
 * タッチ操作の検証。
 *
 *   npm run touch
 *
 * 前提: 別ターミナルで `npm run dev` が動いていること。
 *
 * 実行環境について:
 *   物理的な iPhone / iPad は自動操作できないため、ここでは
 *   「iPhone 相当のビューポート + hasTouch を有効にした Chromium」に対し、
 *   CDP の Input.dispatchTouchEvent で本物のタッチ入力を注入している。
 *   これにより OS が生成するのと同じ pointerdown/pointermove/pointerup が発火し、
 *   アプリのドラッグ処理と OrbitControls のピンチ処理を実際に通せる。
 *
 *   ただしこれは Chromium であって Safari ではない。実機 Safari での確認は別途必要。
 */

import { chromium, devices } from 'playwright'
import { mkdirSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const URL = process.env.APP_URL ?? 'http://localhost:5173'
const OUT = resolve(process.cwd(), 'docs/screenshots')
mkdirSync(OUT, { recursive: true })

const results = []
const log = (name, ok, detail = '') => {
  results.push({ name, ok, detail })
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  — ' + detail : ''}`)
}

const browser = await chromium.launch()

for (const deviceName of ['iPhone 15 Pro', 'iPad Pro 11']) {
  const device = devices[deviceName] ?? devices['iPhone 15 Pro']
  const ctx = await browser.newContext({ ...device, hasTouch: true, isMobile: true })
  const page = await ctx.newPage()
  const cdp = await ctx.newCDPSession(page)

  const errors = []
  page.on('pageerror', (e) => errors.push(e.message))

  await page.goto(URL, { waitUntil: 'domcontentloaded' })
  await page.waitForSelector('.viewport canvas')
  await page.waitForFunction(() => !!window.__r3fState, null, { timeout: 20000 })
  await page.waitForTimeout(1500)

  console.log(`\n=== ${deviceName} (${device.viewport.width}x${device.viewport.height}) ===`)

  // --- レイアウト ---
  const cols = await page.evaluate(
    () => getComputedStyle(document.querySelector('.app')).gridTemplateColumns.split(' ').length,
  )
  log(`${deviceName}: 1 カラムレイアウトになる`, cols === 1, `columns=${cols}`)

  const canvasBox = await page.locator('.viewport canvas').boundingBox()
  log(
    `${deviceName}: 3D ビューが画面内に描かれている`,
    canvasBox.width > 100 && canvasBox.height > 100,
    `${Math.round(canvasBox.width)}x${Math.round(canvasBox.height)}`,
  )

  // --- 深度を設定し、プラグ指部の画面座標を求める ---
  const setDepth = async (mm) => {
    await page.evaluate((v) => {
      const sl = document.querySelector('input[aria-label="挿入深度"]')
      const set = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set
      set.call(sl, String(v))
      sl.dispatchEvent(new Event('input', { bubbles: true }))
    }, mm)
    await page.waitForTimeout(300)
  }
  const depthNow = () =>
    page.evaluate(() => parseFloat(document.querySelector('.hud').innerText.split(' ')[0]))

  await setDepth(8)

  /** プラグ指部の中ほどの世界座標を画面座標へ投影する */
  const plugScreen = await page.evaluate(() => {
    const s = window.__r3fState
    const el = s.gl.domElement
    const r = el.getBoundingClientRect()
    // プラグ先端は x=depth。少し手前 (指部の中ほど) を掴む
    const v = new (Object.getPrototypeOf(s.camera.position).constructor)(8 - 4, 0, 0)
    v.project(s.camera)
    return {
      x: r.left + ((v.x + 1) / 2) * r.width,
      y: r.top + ((1 - v.y) / 2) * r.height,
      rect: { left: r.left, top: r.top, width: r.width, height: r.height },
    }
  })

  // --- 1 本指ドラッグ (プラグの抜き差し) ---
  const before = await depthNow()
  const touch = async (type, points) =>
    cdp.send('Input.dispatchTouchEvent', { type, touchPoints: points })

  const startX = plugScreen.x
  const startY = plugScreen.y
  await touch('touchStart', [{ x: startX, y: startY, id: 1 }])
  for (let i = 1; i <= 12; i++) {
    await touch('touchMove', [{ x: startX + i * 6, y: startY, id: 1 }])
    await page.waitForTimeout(16)
  }
  await touch('touchEnd', [])
  await page.waitForTimeout(300)
  const after = await depthNow()

  log(
    `${deviceName}: 1 本指でプラグをドラッグして深度が変わる`,
    Math.abs(after - before) > 0.05,
    `${before.toFixed(2)}mm → ${after.toFixed(2)}mm`,
  )

  // --- 2 本指ピンチ (拡大縮小) ---
  // OrbitControls の注視点からの距離で測る (原点からの距離ではズーム量が正しく出ない)
  const camDist = () =>
    page.evaluate(() => {
      const s = window.__r3fState
      const t = s.controls ? s.controls.target : { x: 0, y: 0, z: 0 }
      return Math.hypot(s.camera.position.x - t.x, s.camera.position.y - t.y, s.camera.position.z - t.z)
    })
  const controlsState = () =>
    page.evaluate(() => {
      const c = window.__r3fState.controls
      return c ? { enabled: c.enabled, minDistance: c.minDistance, maxDistance: c.maxDistance } : null
    })

  /** 指定座標を中心に 2 本指を広げる */
  const pinchAt = async (px, py) => {
    // 前のジェスチャの影響を消すため、毎回視点を既定へ戻す
    await page.locator('button').filter({ hasText: /^視点を戻す$/ }).first().tap()
    await page.waitForTimeout(400)
    const d0 = await camDist()
    await touch('touchStart', [
      { x: px - 40, y: py, id: 1 },
      { x: px + 40, y: py, id: 2 },
    ])
    for (let i = 1; i <= 14; i++) {
      const d = 40 + i * 8
      await touch('touchMove', [
        { x: px - d, y: py, id: 1 },
        { x: px + d, y: py, id: 2 },
      ])
      await page.waitForTimeout(16)
    }
    await touch('touchEnd', [])
    await page.waitForTimeout(500)
    return { before: d0, after: await camDist() }
  }

  console.log('   OrbitControls:', JSON.stringify(await controlsState()))

  // (a) 何も無い背景から始めるピンチ
  const bgPinch = await pinchAt(
    plugScreen.rect.left + plugScreen.rect.width * 0.15,
    plugScreen.rect.top + plugScreen.rect.height * 0.18,
  )
  log(
    `${deviceName}: 背景から始める 2 本指ピンチでカメラ距離が変わる`,
    Math.abs(bgPinch.after - bgPinch.before) > 0.5,
    `${bgPinch.before.toFixed(1)} → ${bgPinch.after.toFixed(1)}`,
  )

  // (b) プラグの上から始めるピンチ (1 本目がモデルに当たるケース)
  const onPlugPinch = await pinchAt(
    plugScreen.rect.left + plugScreen.rect.width / 2,
    plugScreen.rect.top + plugScreen.rect.height / 2,
  )
  log(
    `${deviceName}: プラグの上から始める 2 本指ピンチでもカメラ距離が変わる`,
    Math.abs(onPlugPinch.after - onPlugPinch.before) > 0.5,
    `${onPlugPinch.before.toFixed(1)} → ${onPlugPinch.after.toFixed(1)}`,
  )

  // --- 1 本指スワイプ (視点回転) ---
  // 視点を戻してから、確実に何も無い隅を使う (モデルの上だとプラグのドラッグが優先されるため)
  await page.locator('button').filter({ hasText: /^視点を戻す$/ }).first().tap()
  await page.waitForTimeout(400)
  const camPosBefore = await page.evaluate(() => window.__r3fState.camera.position.toArray())
  const bg = {
    x: plugScreen.rect.left + plugScreen.rect.width * 0.1,
    y: plugScreen.rect.top + plugScreen.rect.height * 0.12,
  }
  await touch('touchStart', [{ x: bg.x, y: bg.y, id: 1 }])
  for (let i = 1; i <= 10; i++) {
    await touch('touchMove', [{ x: bg.x + i * 9, y: bg.y + i * 3, id: 1 }])
    await page.waitForTimeout(16)
  }
  await touch('touchEnd', [])
  await page.waitForTimeout(500)
  const camPosAfter = await page.evaluate(() => window.__r3fState.camera.position.toArray())
  const moved = Math.hypot(...camPosAfter.map((v, i) => v - camPosBefore[i]))
  log(`${deviceName}: 何も無い所を 1 本指でなぞると視点が回る`, moved > 0.5, `カメラが ${moved.toFixed(1)} 移動`)

  // プラグの上を 1 本指でなぞったときは、視点ではなくプラグが動く (意図した優先順位)
  await page.locator('button').filter({ hasText: /^視点を戻す$/ }).first().tap()
  await page.waitForTimeout(400)
  await setDepth(8)
  const camBefore2 = await page.evaluate(() => window.__r3fState.camera.position.toArray())
  const d0 = await depthNow()
  await touch('touchStart', [{ x: plugScreen.x, y: plugScreen.y, id: 1 }])
  for (let i = 1; i <= 10; i++) {
    await touch('touchMove', [{ x: plugScreen.x + i * 5, y: plugScreen.y, id: 1 }])
    await page.waitForTimeout(16)
  }
  await touch('touchEnd', [])
  await page.waitForTimeout(400)
  const camAfter2 = await page.evaluate(() => window.__r3fState.camera.position.toArray())
  const camMoved2 = Math.hypot(...camAfter2.map((v, i) => v - camBefore2[i]))
  const d1 = await depthNow()
  log(
    `${deviceName}: プラグの上をなぞると視点は動かずプラグだけが動く`,
    Math.abs(d1 - d0) > 0.05 && camMoved2 < 0.5,
    `深度 ${d0.toFixed(2)}→${d1.toFixed(2)}mm / カメラ移動 ${camMoved2.toFixed(2)}`,
  )

  // --- タップでボタンが押せる ---
  await page.locator('button').filter({ hasText: /^故障$/ }).first().tap()
  await page.waitForTimeout(300)
  await page.locator('button').filter({ hasText: /^半挿し$/ }).first().tap()
  await page.waitForTimeout(400)
  const hud = await page.locator('.hud').innerText()
  log(`${deviceName}: タップでプリセットを切り替えられる`, hud.includes('9.80'), hud.split('\n')[0])

  // --- touch-action の確認 (キャンバス上でページがスクロールしない) ---
  const ta = await page.evaluate(() => getComputedStyle(document.querySelector('.viewport canvas')).touchAction)
  log(`${deviceName}: キャンバスに touch-action:none が効いている`, ta === 'none', ta)

  await page.screenshot({
    path: resolve(OUT, deviceName.startsWith('iPad') ? '17_touch_ipad.png' : '16_touch_iphone.png'),
  })

  log(`${deviceName}: JS エラーが無い`, errors.length === 0, errors.slice(0, 2).join(' | '))

  await ctx.close()
}

await browser.close()

writeFileSync(
  resolve(process.cwd(), 'artifacts/touch_verification.json'),
  JSON.stringify(
    {
      schemaVersion: 1,
      generatedAt: new Date().toISOString().slice(0, 10),
      runner: 'Playwright Chromium + iPhone/iPad ビューポート + CDP Input.dispatchTouchEvent',
      caveat:
        '物理的な iPhone / iPad ではない。ブラウザエンジンも Chromium であり Safari ではない。' +
        'タッチ入力は CDP で注入した本物のタッチイベントであり、OS が生成するのと同じ ' +
        'pointerdown/pointermove/pointerup を経てアプリのコードを通っている。',
      total: results.length,
      passed: results.filter((r) => r.ok).length,
      failed: results.filter((r) => !r.ok).length,
      results,
    },
    null,
    1,
  ),
)

const failed = results.filter((r) => !r.ok)
console.log(`\n${results.length - failed.length}/${results.length} passed`)
if (failed.length) process.exitCode = 1

/** scripts/validateProfiles.mjs の型。実体は .mjs 側にある（正本は 1 つ） */

export interface ValidationResult {
  artifact: string
  schema: string | null
  missing: boolean
  schemaErrors: string[]
  semanticErrors: string[]
}

/** 全対象を検証して結果を返す。CLI と release evidence の両方がここを使う */
export declare function validateAll(): ValidationResult[]

/** 検証対象の件数。**テストで直書きしないための正本** */
export declare const TARGET_COUNT: number

/**
 * 成果物を JSON Schema と意味規則の両方で検証する。
 *   npm run validate:profiles
 *
 * ## なぜ ajv を入れたか (統合オーダー 2026-08-03 P0-6)
 *
 * 2026-08-03 まで、schema の検証を自前で書いていた。
 * 実装していたのは required / type / enum / const / additionalProperties / $ref /
 * minItems / minimum だけで、**`pattern` を実装していなかった。**
 *
 * ところが同日の P0-1 で provenance に `pattern` 制約を 5 本足していた
 * (inputDigest の sha256、generatedFromCommit の 40 桁 hex、artifactDate の日付形式など)。
 * **そのどれも検証されていなかった。**
 * 意図的な違反 10 種で試すと、**5 種が自前の検証器を素通り**した。
 * 現物の artifact に違反は 0 件だったので誤った値は公開されていないが、
 * 「schema に書いたから守られている」は成り立っていなかった。
 *
 * ## 2 種類の検証を分ける
 *
 *   schema   … 型・必須・列挙・パターン。**ajv (draft-07 の完全実装) に任せる**
 *   semantic … schema では書けない規則。区間の連続性、ID の一意性、
 *              値どうしの整合 (profileId の末尾が inputDigest と一致するか等)
 *
 * 分ける理由は、落ちたときに**どちらの種類の問題か**が即座に分かるようにするため。
 * schema 違反は形の問題、semantic 違反は中身の問題で、直し方が違う。
 */

import Ajv from 'ajv'
import { createHash } from 'node:crypto'
import { existsSync, readFileSync, readdirSync, realpathSync, statSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { checkWindowInvariants } from './robustnessWindows.mjs'
import { checkRecord, evaluateGate, predictionsForValidation, REQUIRED_FOR_PROFILE, GATE_DOCUMENT, LEDGER_PATH, GATE_VERSION, CLAIM_SCOPE } from './measurementGate.mjs'

const ROOT = process.cwd()
const read = (p) => JSON.parse(readFileSync(resolve(ROOT, p), 'utf8'))
const sha256File = (p) => createHash('sha256').update(readFileSync(p)).digest('hex')

// strict:false は schema の `description` 等の注釈を許すため。検証の厳しさは落ちない
const ajv = new Ajv({ allErrors: true, strict: false })

// **同じ schema を 2 回 compile しない。** ajv は $id の重複を拒否する
// (profile は 2 つの artifact が同じ schema を使う)
const compiledCache = new Map()
const compile = (schemaPath) => {
  if (!compiledCache.has(schemaPath)) compiledCache.set(schemaPath, ajv.compile(read(schemaPath)))
  return compiledCache.get(schemaPath)
}

