  SLEEVE: 'Plug Sleeve',
}

export function buildCircuit(jack: ResolvedJack, contacts: ContactResult[]): CircuitResult {
  const uf = new UnionFind()
  const edges: CircuitEdge[] = []

  const terminalById = new Map(jack.terminals.map((t) => [t.id, t]))

  for (const t of jack.terminals) uf.find(termNode(t.id))

  for (const c of contacts) {
    const sp = springNode(c.contactId)
    uf.find(sp)

    // 接点ばね ↔ その端子 (内部配線。常に導通)
    edges.push({ from: sp, to: termNode(c.terminalId), kind: 'internal-wire', state: 'CLOSED' })
    uf.union(sp, termNode(c.terminalId))

    // 接点ばね ↔ プラグ導体
    if (CONDUCTING.includes(c.state)) {
      for (const net of c.connectedNets) {
        edges.push({
          from: sp,
          to: plugNode(net),
          kind: c.state === 'BRIDGED' ? 'bridge' : 'contact',
          state: c.state,
          quality: c.quality,
        })
        uf.union(sp, plugNode(net))
      }
    }

    // ブレーク接点
    if (c.breakContactId && c.breakState) {
      const def = jack.contacts.find((jc) => jc.id === c.contactId)?.breakContact
      if (def) {
        const closed = c.breakState === 'BREAK_CLOSED'
        edges.push({
          from: sp,
          to: termNode(def.terminalId),
          kind: 'break-switch',
          state: c.breakState,
        })
        if (closed) uf.union(sp, termNode(def.terminalId))
      }
    }
  }

  const groups = [...uf.groups().values()].map((nodes) => ({ nodes: nodes.sort() }))

  // 端子 → 実際に到達できるプラグ導体
  const terminalToPlugNet: Record<string, PlugNet[]> = {}
  for (const t of jack.terminals) {
    const root = uf.find(termNode(t.id))
    const nets: PlugNet[] = []
    for (const g of groups) {
      if (uf.find(g.nodes[0]) !== root) continue
      for (const n of g.nodes) {
        if (n.startsWith('PLUG:')) nets.push(n.slice(5) as PlugNet)
      }
    }
    terminalToPlugNet[t.id] = [...new Set(nets)]
  }

  // 人間可読の行
  const lines: string[] = []
  for (const t of jack.terminals) {
    const nets = terminalToPlugNet[t.id]
    const pin = t.pin ? `pin ${t.pin}` : 'pin 不明'
    if (nets.length === 0) {
      lines.push(`${t.label} (${pin}) → 未接続`)
    } else {
      lines.push(`${t.label} (${pin}) → ${nets.map((n) => netLabel[n]).join(' + ')}`)
    }
  }
  // プラグ導体どうしの橋絡
  const allNets: PlugNet[] = ['TIP', 'RING', 'RING2', 'SLEEVE']
  for (let i = 0; i < allNets.length; i++) {
    for (let j = i + 1; j < allNets.length; j++) {
      const a = plugNode(allNets[i])
      const b = plugNode(allNets[j])
      const has = (n: string) => groups.some((g) => g.nodes.includes(n))
      if (has(a) && has(b) && uf.find(a) === uf.find(b)) {
        lines.push(`${netLabel[allNets[i]]} ↔ ${netLabel[allNets[j]]} 橋絡`)
      }
    }
  }
  // ブレーク接点の開閉
  for (const c of contacts) {
    if (c.breakState) {
      const def = jack.contacts.find((jc) => jc.id === c.contactId)?.breakContact
      const term = def ? terminalById.get(def.terminalId) : undefined
      const pin = term?.pin ? ` (pin ${term.pin})` : ''
      lines.push(
        `${def?.label ?? c.breakContactId}${pin}: ${c.breakState === 'BREAK_OPEN' ? 'OPEN' : 'CLOSED'}`,
      )
    }
  }

  return { edges, nets: groups, lines, terminalToPlugNet }
}

// ---------------------------------------------------------------------------
// 音響予測 (仕様 §14)
// ---------------------------------------------------------------------------

/**
 * 接続グラフから、聴感上どうなるかを推定する。
 * これは回路接続からの簡易推定であり、特定製品の実際の音を保証するものではない。
 *
 * 「導体位置」ではなく「信号機能」で判定するため、CTIA / OMTP / 3極を混ぜても
 * 同じロジックで扱える。機器側 (ジャック端子) が期待する機能と、
 * 実際に届いたプラグ導体が担う機能を突き合わせる。
 */
export function predictAcoustic(
  jack: ResolvedJack,
  plug: ResolvedPlug,
  contacts: ContactResult[],
  circuit: CircuitResult,
): AcousticPrediction {
  const termFor = (fn: SignalFunction) => jack.terminals.find((t) => t.signalRole === fn)
  const reach = (id: string | undefined): PlugNet[] => (id ? circuit.terminalToPlugNet[id] ?? [] : [])

  /** その端子に届いているプラグ導体が担う機能の集合 */
  const fnOf = (nets: PlugNet[]): SignalFunction[] =>
    [...new Set(nets.map((n) => plug.netFunctions[n]).filter((f): f is SignalFunction => !!f))]

  // **電気的な事実は分類器から取る (統合オーダー P0-4)。**
  // ここで再計算すると、同じ判定がまた 2 か所になる。
  // この関数が独自に持つのは「どう聞こえるか」と表示文だけにする。
  const t = classifyFromEvaluation(jack.terminals, plug.netFunctions, { contacts, circuit })
  const { lNets, rNets, gndNets: gNets } = t

  const micT = termFor('MIC')
  const micNets = reach(micT?.id)

  // 「正しく届いている」= 届いた導体がちょうど 1 つで、その機能が期待どおり
  const okFor = (nets: PlugNet[], want: SignalFunction) =>
    nets.length === 1 && plug.netFunctions[nets[0]] === want
  const lOk = okFor(lNets, 'L')
  const rOk = okFor(rNets, 'R')
  const gOk = okFor(gNets, 'GND')

  const anyConnection = lNets.length + rNets.length + gNets.length > 0
  const lrShorted = t.shortsSignalToSignal
  const unstable = contacts.some((c) => c.state === 'TOUCH_UNSTABLE')

  const mk = (
    code: AcousticPrediction['code'],
    label: string,
    detail: string,
    severity: AcousticPrediction['severity'],
  ): AcousticPrediction => ({
    code,
    label,
    detail: unstable ? `${detail} / 接触が不安定なため断続的なノイズが乗り得る` : detail,
    severity,
  })

  if (!anyConnection) {
    return mk('SILENT', '無音', 'ジャック端子とプラグ導体がどこも導通していない', 'bad')
  }

  if (!gOk && gNets.length === 0) {
    // 帰線が浮いている。ここから先は **左右が別々の導体に届いているか** で分ける。
    //
    // 2026-08-02 まで、この 2 つを区別せず GROUND_OPEN にまとめていた。
    // しかも判定が lrShorted より先にあるため、**左右が同じ導体に落ちていても
    // 「左右差分が残る」と表示していた。** 実際にはその場合、両チャンネルが
    // 同じ節点に落ちて差分は生じない。構成探索で 318 件中 78 件しか
    // 本当の差分信号でなかったことから見つかった。
    //
    // 判定そのものは topology.ts が持つ。ここは表示文を選ぶだけにする。
    if (t.topologyClass === 'ground-open-differential') {
      return mk(
        'DIFFERENCE_SIGNAL',
        '共通帰線断 (左右差分が残る)',
        '帰線がプラグ Sleeve に届いていない。左右のドライバが直列になり、' +
          '音量が大きく落ちたうえで左右の差分成分だけが聞こえる状態になり得る',
        'bad',
      )
    }
    if (lNets.length > 0 && rNets.length > 0) {
      return mk(
        'GROUND_OPEN',
        '共通帰線断 (差分にはならない)',
        '帰線が届いていないうえ、左右が同じ導体に落ちている。' +
          '両チャンネルが同じ節点になるため差分は生じず、ほぼ無音になる',
        'bad',
      )
    }
    return mk('SILENT', '無音または極小音', '共通帰線が接続されていないため、回路が閉じない', 'bad')
  }

  if (lrShorted) {
    return mk(
      'LR_SHORTED',
      '左右短絡',
      `左右が同じ導体 (${lNets.filter((n) => rNets.includes(n)).join(', ')}) に落ちている。` +
        'モノラル化するか、アンプによっては保護動作で無音になり得る',
      'bad',
    )
  }

  // --- 左右が正しくつながっているケースを、帰線／マイクの状況で細分する ---
  if (lOk && rOk) {
    const bridged = contacts.some((c) => c.state === 'BRIDGED')
    if (bridged) {
      return mk('UNKNOWN', '接続は成立しているが橋絡あり', '正規接続に加えて余分な短絡がある', 'warn')
    }

    const gndReachesMic = gNets.some((n) => plug.netFunctions[n] === 'MIC')
    const micReachesGnd = micNets.some((n) => plug.netFunctions[n] === 'GND')

    // CTIA と OMTP の食い違い: 帰線とマイクが入れ替わっている
    if (gndReachesMic && micReachesGnd) {
      return mk(
        'UNKNOWN',
        '規格違い (CTIA ↔ OMTP)',
        'ステレオ再生はできるが、機器が帰線だと思っている端子にプラグのマイク線が、' +
          'マイクだと思っている端子に帰線が来ている。マイクは働かず、ボタン操作も検出されない',
        'warn',
      )
    }

    // 4極プラグ × 3極ジャック: 機器の帰線端子にプラグのマイク線が当たっている。
    //
    // このとき、プラグ側で帰線 (GND) を担う導体がどこにも触れていないことがある。
    // ドライバの帰り道が機器のグランドへ直接つながらないので、「左右の音は正常」とは
    // 言えない。位置ではなく機能で見る (この関数の設計原則) と、これは帰線断の一種。
    if (gndReachesMic && !micT) {
      const gndConductorReached = Object.entries(plug.netFunctions).some(
        ([net, fn]) =>
          fn === 'GND' &&
          Object.values(circuit.terminalToPlugNet).some((nets) => nets.includes(net as PlugNet)),
      )
      if (!gndConductorReached) {
        return mk(
          'GROUND_OPEN',
          '帰線がマイク線経由になる (音量が大きく落ちる)',
          '4極プラグを3極ジャックへ挿した状態。左右の信号は正しい導体に届いているが、' +
            'プラグ側で帰線を担う導体 (Ring2) がどの接点にも触れていない。' +
            'ドライバの帰り道はヘッドセット内部のマイク素子を経由することになり、' +
            'マイクの直流抵抗 (数 kΩ) がドライバ (16〜32 Ω) と直列に入るため音量が大きく落ちる。' +
            'マイクも働かない。※実機はこの状態を検出して内部で結線を切り替えることがある',
          'bad',
        )
      }
      return mk(
        'NORMAL',
        'ステレオ再生は正常 / マイクは機能しない',
        '4極プラグを3極ジャックへ挿した状態。帰線は正しく届いているが、' +
          'プラグのマイク線がジャックの帰線接点に当たって短絡するため、マイクは働かない',
        'warn',
      )
    }

    if (gOk) {
      if (micT && !okFor(micNets, 'MIC')) {
        return mk(
          'NORMAL',
          'ステレオ再生は正常 / マイク未接続',
          '機器側はマイク端子を持つが、挿さっているプラグにマイク導体が無いか届いていない',
          'warn',
        )
      }
      const withMic = !!micT && okFor(micNets, 'MIC')
      return mk(
        'NORMAL',
        withMic ? '正常 (ステレオ + マイク)' : '正常 (ステレオ)',
        '機器が期待する信号と、実際に届いているプラグ導体の機能が一致している',
        'ok',
      )
    }
  }

  if (lOk && !rOk && gOk) {
    return mk('LEFT_ONLY', '左のみ', '右チャンネルの接点が Ring に届いていない', 'warn')
  }
  if (!lOk && rOk && gOk) {
    return mk('RIGHT_ONLY', '右のみ', '左チャンネルの接点が Tip に届いていない', 'warn')
  }

  // 帰線が音声信号の導体につながっている (挿入途中に頻発する。最も害が大きい)
  const gndOnSignal = gNets.filter((n) => {
    const f = plug.netFunctions[n]
    return f === 'L' || f === 'R'
  })
  if (gndOnSignal.length > 0) {
    const wrong = gndOnSignal
    return mk(
      'LR_SHORTED',
      `帰線が信号導体 (${wrong.join(', ')}) に接触`,
      '共通帰線用の接点が、本来の Sleeve ではなく信号側の導体に触れている。' +
        'そのチャンネルの出力が帰線に落ちるため、アンプにとっては出力短絡に近い状態になる',
      'bad',
    )
  }

  // 誤セグメント接続 (例: Tip 用接点が Sleeve に触れている)
  const desc: string[] = []
  if (lNets.length === 0) desc.push('左: 未接続')
  else desc.push(`左: ${lNets.join('+')} に接続`)
  if (rNets.length === 0) desc.push('右: 未接続')
  else desc.push(`右: ${rNets.join('+')} に接続`)
  if (gNets.length === 0) desc.push('帰線: 未接続')
  else desc.push(`帰線: ${gNets.join('+')} に接続`)

  const lGrounded = fnOf(lNets).includes('GND')
  const rGrounded = fnOf(rNets).includes('GND')
  if (lGrounded && rGrounded) {
    return mk('SILENT', '両チャンネルが帰線に落ちている', desc.join(' / '), 'bad')
  }
  if (lGrounded) return mk('RIGHT_ONLY', '左が帰線に短絡 (右のみ)', desc.join(' / '), 'bad')
  if (rGrounded) return mk('LEFT_ONLY', '右が帰線に短絡 (左のみ)', desc.join(' / '), 'bad')

  return mk('UNKNOWN', '非標準の接続', desc.join(' / '), 'warn')
}

/**
 * 決定論的な接触判定エンジン。仕様 §6 / §7 / §19。
 *
 * 設計上の約束:
 *  - 3D メッシュ名・画面座標・物理エンジンの衝突イベントを一切参照しない。
 *  - 入力 (深度・故障パラメータ・モデル) が同じなら出力は必ず同じ。
 *  - 乱数は「深度と接点 ID とシードのハッシュ」からのみ生成する (時刻を使わない)。
 *
 * 座標系 (仕様 §5):
 *  - d = 挿入深度 [mm]。プラグ先端がジャック前面基準面より内側に入った距離。
 *    d < 0  : 未挿入 (プラグ先端は前面より外)
 *    d = 0  : プラグ先端がジャック前面基準面に到達
 *    d = xFull : 停止面に当たる完全挿入
 *  - xj = ジャック前面から奥への距離 [mm] (接点の軸位置)
 *  - s  = プラグ先端から肩に向かう距離 [mm] (セグメント境界)
 *  - 対応関係: s = d - xj
 */

import type {
  ContactResult,
  ContactState,
  FaultParams,
  Grade,
  PlugNet,
  SegmentOverlap,
} from './types'
import {
  Dimensions,
  intersectIntervals,
  intervalsWidth,
  plugRadiusAt,
  radiusAtLeastIntervals,
  weakerGrade,
  weakestGrade,
  type Interval,
  type ResolvedJack,
  type ResolvedJackContact,
  type ResolvedPlug,
} from './resolve'

// ---------------------------------------------------------------------------
// 判定パラメータ (全て contactModel.json 由来。ハードコードしない)
// ---------------------------------------------------------------------------

export interface ContactModelConfig {
  /** 品質スコアの重み: 有効接触幅の寄与 */
  qualityWeightOverlap: number
  /** 品質スコアの重み: 押付量の寄与 */
  qualityWeightForce: number
  /** これ以上で CLOSED、未満で TOUCH_UNSTABLE */
  closedQualityThreshold: number
  /** これ未満の重なり幅は導通とみなさない [mm] */
  minConductionOverlapMm: number
  /** 摩耗 1.0 のとき接触パッド自由半径がどれだけ広がるか [mm] */
  wearRadiusGainMm: number
  /** 摩耗 1.0 のときの品質低下率 0-1 */
  wearQualityLoss: number
  /** 汚れの円周方向の広がり (半値半幅) [deg] */
  contaminationSpanDeg: number
  /** 汚れパッチのプラグ側方位角 [deg] */
  contaminationAzimuthDeg: number
  /** 断続接触のノイズ量子化幅 [mm] */
  intermittentStepMm: number
  /** 軸ずれ・傾きが起きる円周方向 [deg]。0deg = +Y */
  misalignDirectionDeg: number
  /**
   * 接触ドームが、押し出された位置よりどれだけ低い面まで追従できるか [mm]。
   *
   * 接点はパッド範囲内で一番高い面に乗って押し開かれる。その状態では、
   * それより低い面には本来届かない。ただし実物のドームは点ではなく有限の
   * 曲率を持ち、梁もねじれるので、わずかに低い面へは追従しうる。その許容量。
   *
   * 0 にすると完全剛体になり、完全挿入時に Tip 接点が導通しなくなる。
   * 傾いた面 (Tip 後端の逆テーパ) の上では導通帯の幅が compliance/傾き に
   * なり、これが minConductionOverlapMm を割るため。
   * 逆に 0.15mm (Tip と Ring の半径差) を超えると、その段差を無視した
   * 誤った同時接触が復活する。実測した破綻点は 0.0008 と 0.1538。
   */
  contactComplianceMm: number
}

export const DEFAULT_FAULTS: FaultParams = {
  contamination: 0,
  wear: 0,
  lateralOffsetMm: 0,
  tiltDeg: 0,
  springForceScale: 1,
  intermittent: false,
  seed: 1,
  intermittentAmplitude: 0.6,
  rotationDeg: 0,
}

export function loadContactConfig(dims: Dimensions): ContactModelConfig {
  return {
    qualityWeightOverlap: dims.num('model.quality.weightOverlap'),
    qualityWeightForce: dims.num('model.quality.weightForce'),
    closedQualityThreshold: dims.num('model.quality.closedThreshold'),
    minConductionOverlapMm: dims.num('model.conduction.minOverlap'),
    wearRadiusGainMm: dims.num('model.wear.radiusGain'),
    wearQualityLoss: dims.num('model.wear.qualityLoss'),
    contaminationSpanDeg: dims.num('model.contamination.spanDeg'),
    contaminationAzimuthDeg: dims.num('model.contamination.azimuthDeg'),
    intermittentStepMm: dims.num('model.intermittent.stepMm'),
    misalignDirectionDeg: dims.num('model.misalign.directionDeg'),
    contactComplianceMm: dims.num('model.contact.complianceMm'),
  }
}

// ---------------------------------------------------------------------------
// 決定論的ノイズ
// ---------------------------------------------------------------------------

/** 文字列 + 整数 から 32bit ハッシュ。時刻に依存しない。 */
function hash32(str: string, a: number, b: number): number {
  let h = 2166136261 >>> 0
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i)
    h = Math.imul(h, 16777619) >>> 0
  }
  h ^= a | 0
  h = Math.imul(h, 16777619) >>> 0
  h ^= b | 0
  h = Math.imul(h, 16777619) >>> 0
  h ^= h >>> 15
  h = Math.imul(h, 2246822507) >>> 0
  h ^= h >>> 13
  return h >>> 0
}

/** 0..1 の決定論的ノイズ。同じ (接点, シード, 量子化深度) なら必ず同じ値。 */
export function deterministicNoise(contactId: string, seed: number, depthMm: number, stepMm: number): number {
  const q = Math.round(depthMm / Math.max(stepMm, 1e-6))
  return hash32(contactId, seed, q) / 0xffffffff
}

// ---------------------------------------------------------------------------
// 個々の接点の評価
// ---------------------------------------------------------------------------

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x)
const deg2rad = (d: number) => (d * Math.PI) / 180

/**
 * 接点 1 本の評価。
 *
 * 幾何:
 *   接触パッドは軸方向に padWidth の幅を持つ。パッドの軸方向範囲を
 *   プラグ座標に写し、「半径方向に届いている区間」と交差させ、
 *   その区間が導体セグメント / 絶縁セグメントとどれだけ重なるかを厳密に求める。
 */
export function evaluateContact(
  contact: ResolvedJackContact,
  plug: ResolvedPlug,
  depthMm: number,
  faults: FaultParams,
  cfg: ContactModelConfig,
): ContactResult {
  const expectedSeg = plug.segments.find((s) => s.id === contact.expectedSegment)
  const expectedNet = expectedSeg?.net
  // 極数の違うプラグでは、この接点が本来触れるべき導体そのものが存在しないことがある
  const expectedSegmentMissing = !expectedSeg

  // --- 1. 位置ずれを織り込んだ実効自由半径 -------------------------------
  // 摩耗すると接触ドームが減り、自由半径が広がる (= 押付が落ちる)
  const wornFreeRadius = contact.freeRadiusMm + cfg.wearRadiusGainMm * faults.wear

  // 傾き + 横ずれ。ジャック前面 (xj=0) を支点とした 1 次近似。
  const lateralAtContact =
    faults.lateralOffsetMm + contact.axialCenterMm * Math.tan(deg2rad(faults.tiltDeg))
  const angleDelta = deg2rad(contact.angularPositionDeg - cfg.misalignDirectionDeg)
  const effFreeRadius = wornFreeRadius - lateralAtContact * Math.cos(angleDelta)

  // --- 2. パッドの軸方向範囲をプラグ座標に写す ---------------------------
  const sCenter = depthMm - contact.axialCenterMm
  const padLo = sCenter - contact.padWidthMm / 2
  const padHi = sCenter + contact.padWidthMm / 2
  const padWindow: Interval[] = [{ lo: padLo, hi: padHi }]

  // プラグ指部の存在範囲
  const fingerWindow: Interval[] = [{ lo: 0, hi: plug.fingerLengthMm }]

  /** しきい値 r 以上の面と、パッド窓・指部との共通区間 */
  const touchingAt = (r: number): Interval[] =>
    intersectIntervals(
      intersectIntervals(padWindow, fingerWindow),
      r <= 0 ? fingerWindow : radiusAtLeastIntervals(plug.profile, r),
    )

  /** 区間内のプラグ最大半径 (区分線形なので端点と内部ブレークポイントだけ見れば足りる) */
  const maxRadiusIn = (ivs: Interval[]): number => {
    let m = 0
    for (const iv of ivs) {
      const candidates = [iv.lo, iv.hi, ...plug.profile.map((p) => p.s).filter((s) => s > iv.lo && s < iv.hi)]
      for (const s of candidates) m = Math.max(m, plugRadiusAt(plug.profile, s))
    }
    return m
  }

  // パッドがプラグに噛み合っている区間 (= プラグ外半径 >= 実効自由半径)。
  // たわみ量・押付力・品質スコア・画面表示はこちらを使う。
  const engaged = touchingAt(effFreeRadius)
  const maxPlugRadius = intervalsWidth(engaged) > 0 ? maxRadiusIn(engaged) : 0

  // --- 3. たわみ後の位置で「どの導体に導通するか」を判定し直す -----------
  //
  // 接点はパッド範囲内で一番高い面に乗って maxPlugRadius まで押し開かれる。
  // その状態では、それより低い面には本来届かない。噛み合い区間をそのまま
  // 導通判定に使うと、半径の段差をまたいだ「ありえない同時接触」ができてしまう
  // (プラグの Tip 導体は Ring/Sleeve より 0.15mm 細いため、ここが効く)。
  //
  // ドームの追従量 contactComplianceMm だけは低い面も拾う。
  // しきい値が自由半径を下回ることはない (それ以下は元々噛み合っていない)。
  //
  // 1 回で足りる: 新しい区間は元の区間の部分集合で、かつ最高点を必ず含むので、
  // その中の最大半径は maxPlugRadius のまま変わらない。だから 2 回目は同じ結果になる。
  const touching =
    maxPlugRadius > 0
      ? touchingAt(Math.max(effFreeRadius, maxPlugRadius - cfg.contactComplianceMm))
      : engaged

  const physicallyTouching = intervalsWidth(engaged) > 0
  const deflection = physicallyTouching ? Math.max(0, maxPlugRadius - effFreeRadius) : 0
  const overDeflected = deflection > contact.maxDeflectionMm + 1e-9
  const normalForce = deflection * contact.springRateNPerMm * faults.springForceScale

  // --- 4. 各セグメントとの重なり ----------------------------------------
  // 導通判定は「押し開かれた位置から届く帯」で、品質と表示は「パッドの噛み合い」で見る。
  // 傾斜面の上ではこの 2 つは一致しない。混ぜると品質スコアが compliance の値に
  // 引きずられてしまうので、分けて持つ。
  const overlaps: SegmentOverlap[] = []
  for (const seg of plug.segments) {
    const segWindow: Interval[] = [{ lo: seg.startMm, hi: seg.endMm }]
    const w = intervalsWidth(intersectIntervals(touching, segWindow))
    if (w > 1e-9) {
      overlaps.push({
        segmentId: seg.id,
        segmentLabel: seg.label,
        kind: seg.kind,
        net: seg.net,
        widthMm: w,
        engagedWidthMm: intervalsWidth(intersectIntervals(engaged, segWindow)),
        fraction: clamp01(intervalsWidth(intersectIntervals(engaged, segWindow)) / contact.padWidthMm),
      })
    }
  }
  overlaps.sort((a, b) => b.widthMm - a.widthMm)

  const conductorOverlaps = overlaps.filter(
    (o) => o.kind === 'conductor' && o.widthMm >= cfg.minConductionOverlapMm,
  )
  const insulatorOverlaps = overlaps.filter((o) => o.kind === 'insulator')

  // --- 5. 汚れ (回転角依存) ---------------------------------------------
  // 理想的な同心接点では軸回転で接続は変わらない。汚れパッチがある場合のみ、
  // パッチの方位と接点の方位の関係で効き方が変わる。仕様 §5。
  let contaminationApplied = 0
  if (faults.contamination > 0) {
    const patchAzimuth = cfg.contaminationAzimuthDeg + faults.rotationDeg
    let delta = ((contact.angularPositionDeg - patchAzimuth) % 360 + 540) % 360 - 180
    delta = Math.abs(delta)
    const span = Math.max(cfg.contaminationSpanDeg, 1e-6)
    // 半値半幅 span の raised-cosine 窓。span を超えると 0。
    const window = delta >= span ? 0 : 0.5 * (1 + Math.cos((Math.PI * delta) / span))
    contaminationApplied = faults.contamination * window
  }

  // --- 6. 品質スコア (仕様 §7) ------------------------------------------
  const bestConductor = conductorOverlaps[0]
  // 品質は「パッドがどれだけ噛み合っているか」で見る。導通判定用の帯幅を使うと、
  // 一次資料の無い contactComplianceMm が品質スコアと CLOSED/TOUCH_UNSTABLE の
  // 境界まで決めてしまう。
  const fOverlap = bestConductor ? clamp01(bestConductor.engagedWidthMm / contact.padWidthMm) : 0
  // 押付の寄与は「実際の押付力 / 公称押付力」で見る。ばねがへたれば (springForceScale が
  // 小さければ) たわみが同じでも接触は悪くなるので、ここに倍率を掛ける必要がある。
  const fForce = clamp01(
    (deflection * faults.springForceScale) / Math.max(contact.nominalDeflectionMm, 1e-9),
  )
  let quality =
    cfg.qualityWeightOverlap * fOverlap + cfg.qualityWeightForce * fForce
  quality *= 1 - contaminationApplied
  quality *= 1 - cfg.wearQualityLoss * faults.wear
  if (faults.intermittent) {
    const n = deterministicNoise(contact.id, faults.seed, depthMm, cfg.intermittentStepMm)
    quality *= 1 - faults.intermittentAmplitude * n
  }
  if (deflection <= 0 || !bestConductor) quality = 0
  quality = clamp01(quality)

  // --- 7. 状態判定 -------------------------------------------------------
  const connectedNets: PlugNet[] = []
  if (quality > 0) {
    for (const o of conductorOverlaps) {
      if (o.net && !connectedNets.includes(o.net)) connectedNets.push(o.net)
    }
  }

  let state: ContactState
  let reason: string
  if (!physicallyTouching) {
    state = 'OPEN'
    reason =
      sCenter < 0
        ? 'プラグ先端がまだこの接点まで届いていない'
        : 'プラグ表面に届いていない (半径不足または通過済み)'
  } else if (conductorOverlaps.length === 0) {
    state = 'INSULATED'
    const on = insulatorOverlaps[0]?.segmentLabel ?? '絶縁部'
    reason = `接点が${on}の上に乗っており、回路は開いている`
  } else if (quality <= 0) {
    state = 'OPEN'
    reason =
      contaminationApplied >= 1
        ? '導体には接しているが、絶縁性の汚れ膜で導通していない'
        : '接触しているが押付が無く導通していない'
  } else if (connectedNets.length >= 2) {
    state = 'BRIDGED'
    reason = `1 本の接点が ${connectedNets.join(' と ')} をまたいで短絡させている`
  } else if (expectedSegmentMissing) {
    state = 'WRONG_SEGMENT'
    reason =
      `このプラグには ${contact.expectedSegment} 導体が存在しない。` +
      `代わりに ${connectedNets[0]} に触れている`
  } else if (expectedNet && connectedNets[0] !== expectedNet) {
    state = 'WRONG_SEGMENT'
    reason = `本来 ${expectedNet} に触れるべき接点が ${connectedNets[0]} に触れている`
  } else if (quality < cfg.closedQualityThreshold) {
    state = 'TOUCH_UNSTABLE'
    reason =
      fOverlap < 0.5
        ? `接触幅が狭い (パッドの ${(fOverlap * 100).toFixed(0)}% のみ導体上)`
        : `押付が不足している (公称の ${(fForce * 100).toFixed(0)}%)`
  } else {
    state = 'CLOSED'
    reason = '正常接触'
  }
  if (overDeflected) {
    reason += ' / 許容たわみ超過'
  }

  // --- 8. ブレーク接点 ---------------------------------------------------
  let breakState: ContactResult['breakState'] = null
  let breakContactId: string | null = null
  if (contact.breakContact) {
    breakContactId = contact.breakContact.id
    const opened = deflection >= contact.breakContact.openDeflectionMm
    if (contact.breakContact.normalState === 'closed') {
      breakState = opened ? 'BREAK_OPEN' : 'BREAK_CLOSED'
    } else {
      breakState = opened ? 'BREAK_CLOSED' : 'BREAK_OPEN'
    }
  }

  // --- 9. 根拠区分の伝播 --------------------------------------------------
  const grade: Grade = weakestGrade([
    contact.grade,
    ...overlaps
      .map((o) => plug.segments.find((s) => s.id === o.segmentId)?.grade)
      .filter((g): g is Grade => !!g),
  ])

  return {
    contactId: contact.id,
    label: contact.label,
    terminalId: contact.terminalId,
    expectedSegment: contact.expectedSegment,
    state,
    physicallyTouching,
    deflectionMm: deflection,
    normalForceN: normalForce,
    overlaps,
    connectedNets,
    quality,
    breakState,
    breakContactId,
    overDeflected,
    contaminationApplied,
    padCenterSMm: sCenter,
    grade: weakerGrade(grade, faults.contamination > 0 || faults.wear > 0 ? 'ASSUMPTION' : grade),
    reason,
  }
}

/** 全接点をまとめて評価する。 */
export function evaluateAllContacts(
  jack: ResolvedJack,
  plug: ResolvedPlug,
  depthMm: number,
  faults: FaultParams,
  cfg: ContactModelConfig,
): ContactResult[] {
  return jack.contacts.map((c) => evaluateContact(c, plug, depthMm, faults, cfg))
}

/**
 * モデル全体のファサード。UI と 3D 表示はここだけを見る。
 * 接触判定・回路・力・イベントを 1 つの決定論的な評価にまとめる。
 */

import { evaluateAllContacts, loadContactConfig, DEFAULT_FAULTS, type ContactModelConfig } from './contact'
import { buildCircuit, predictAcoustic } from './circuit'
import { computeForce, loadForceConfig, type ForceModelConfig, type ForceBreakdown } from './force'
import {
  Dimensions,
  resolveJack,
  resolvePlug,
  type ResolvedJack,
  type ResolvedPlug,
} from './resolve'
import type {
  DimensionTable,
  EvaluationResult,
  FaultParams,
  FaultPreset,
  Grade,
  JackModelDef,
  MaterialDef,
  PlugModelDef,
  SourceReference,
} from './types'

export interface ModelBundle {
  dimensions: DimensionTable
  plug: PlugModelDef
  jack: JackModelDef
  materials: MaterialDef[]
  sources: SourceReference[]
  faultPresets: FaultPreset[]
}

export class TrsModel {
  readonly dims: Dimensions
  readonly plug: ResolvedPlug
  readonly jack: ResolvedJack
  readonly contactCfg: ContactModelConfig
  readonly forceCfg: ForceModelConfig
  readonly materials: Map<string, MaterialDef>
  readonly sources: Map<string, SourceReference>
  readonly faultPresets: FaultPreset[]

  constructor(bundle: ModelBundle) {
    this.dims = new Dimensions(bundle.dimensions)
    this.plug = resolvePlug(bundle.plug, this.dims)
    this.jack = resolveJack(bundle.jack, this.dims)
    this.contactCfg = loadContactConfig(this.dims)
    this.forceCfg = loadForceConfig(this.dims)
    this.materials = new Map(bundle.materials.map((m) => [m.id, m]))
    this.sources = new Map(bundle.sources.map((s) => [s.id, s]))
    this.faultPresets = bundle.faultPresets

    // 極数の違う組み合わせでは、ジャック側の接点に対応する導体がプラグに無いことがある
    // (例: 4極ジャックの Ring2 接点 × 3極プラグ)。これはエラーではなく、
    // まさに計算して見せるべき状態なので、記録だけして続行する。
    this.unmatchedContacts = this.jack.contacts
      .filter((c) => !this.plug.segments.some((s) => s.id === c.expectedSegment))
      .map((c) => c.id)
  }

  /** プラグ側に対応する導体が存在しないジャック接点の id */
  readonly unmatchedContacts: string[]

  /** 完全挿入深度 [mm] */
  get fullDepthMm(): number {
    return this.jack.fullInsertionDepthMm
  }

  /** 深度を百分率に変換 */
  toPercent(depthMm: number): number {
    return (depthMm / this.fullDepthMm) * 100
  }

  fromPercent(percent: number): number {
    return (percent / 100) * this.fullDepthMm
  }

  clampDepth(depthMm: number, minMm = -this.plug.fingerLengthMm - 2): number {
    return Math.max(minMm, Math.min(this.fullDepthMm, depthMm))
  }

  evaluate(depthMm: number, faults: FaultParams = DEFAULT_FAULTS): EvaluationResult {
    const contacts = evaluateAllContacts(this.jack, this.plug, depthMm, faults, this.contactCfg)
    const circuit = buildCircuit(this.jack, contacts)
    const acoustic = predictAcoustic(this.jack, this.plug, contacts, circuit)
    const force = computeForce(this.jack, this.plug, depthMm, faults, this.contactCfg, this.forceCfg)
    return {
      depthMm,
      depthPercent: this.toPercent(depthMm),
      contacts,
      circuit,
      acoustic,
      estimatedForceN: force.insertionN,
      anyBridged: contacts.some((c) => c.state === 'BRIDGED'),
      anyWrongSegment: contacts.some((c) => c.state === 'WRONG_SEGMENT'),
      anyUnstable: contacts.some((c) => c.state === 'TOUCH_UNSTABLE'),
    }
  }

  force(depthMm: number, faults: FaultParams = DEFAULT_FAULTS): ForceBreakdown {
    return computeForce(this.jack, this.plug, depthMm, faults, this.contactCfg, this.forceCfg)
  }

  /** 全モデルの最弱グレード。「この画面のどこまでが確実か」の表示に使う。 */
  overallGrade(): Grade {
    return this.plug.grade === 'FACT' && this.jack.grade === 'FACT' ? 'FACT' : 'ASSUMPTION'
  }

  materialOf(id: string): MaterialDef | undefined {
    return this.materials.get(id)
  }
}

/**
 * 挿抜力の近似モデル。仕様 §8。
 *
 * 重要: 有限要素解析はしていない。実物と同一のばね力を再現したとは主張しない。
 * ここで出す値は「推定挿抜力」であり、実測値ではない。
 *
 * 手法 (エネルギー法):
 *   接点ばね 1 本が半径方向に δ たわみ、押付力 N = k·δ を出しているとき、
 *   プラグを軸方向に dd 進めるのに必要な仕事は
 *       F·dd = μ·N·dd  (摩擦)  +  dU  (ばねに蓄えるエネルギーの増分)
 *   U = ½k·δ² より dU/dd = k·δ·(dδ/dd) = N·(dδ/dd) なので
 *       F = N·(μ + dδ/dd)
 *   dδ/dd はプラグ外形の傾きそのもの。テーパを登るときに局所ピークが出る。
 *   抜去時は運動方向が逆なので F = N·(μ_w − dδ/dd) となり、
 *   摩擦の符号が変わらない分ヒステリシスが生じる。
 */

import { evaluateContact, type ContactModelConfig } from './contact'
import type { Dimensions, ResolvedJack, ResolvedPlug } from './resolve'
import type { FaultParams } from './types'

export interface ForceModelConfig {
  /** 挿入時の摩擦係数 (ニッケルめっき CuZn / 銀めっき銅合金) */
  frictionInsert: number
  /** 抜去時の摩擦係数 */
  frictionWithdraw: number
  /** 入口ブッシング/絶縁ボアの摩擦 [N/mm of engaged length] */
  entryFrictionPerMm: number
  /** 入口摩擦の上限 [N] */
  entryFrictionMax: number
  /** 完全挿入付近の保持 (デテント) のピーク [N] */
  detentPeak: number
  /** デテントの軸方向の広がり (標準偏差) [mm] */
  detentSigma: number
  /** 全体スケール。公称 3〜20N レンジに合わせるための校正係数 */
  calibrationScale: number
  /** 数値微分の刻み [mm] */
  differentiationStep: number
  /**
   * ランプ項 dδ/dd の絶対値の上限。
   *
   * 導体と絶縁帯の境界は幅ゼロの垂直な段なので、そこでは たわみ δ が不連続に
   * なり dδ/dd が発散する。上限を置かないと、微分の刻みを変えるだけで
   * ピーク挿入力が 17N にも 28N にもなってしまい、物理量にならない。
   *
   * 実物の接触ドームは点ではなく有限の曲率を持つので、段を一定の距離をかけて
   * 登る。その分だけ傾きが頭打ちになる。値の根拠は dimensions.json を参照。
   */
  maxRampSlope: number
}

export function loadForceConfig(dims: Dimensions): ForceModelConfig {
  return {
    frictionInsert: dims.num('force.frictionInsert'),
    frictionWithdraw: dims.num('force.frictionWithdraw'),
    entryFrictionPerMm: dims.num('force.entryFrictionPerMm'),
    entryFrictionMax: dims.num('force.entryFrictionMax'),
    detentPeak: dims.num('force.detentPeak'),
    detentSigma: dims.num('force.detentSigma'),
    calibrationScale: dims.num('force.calibrationScale'),
    differentiationStep: dims.num('force.differentiationStep'),
    maxRampSlope: dims.num('force.maxRampSlope'),
  }
}

export interface ForceBreakdown {
  depthMm: number
  /** 挿入方向に押すのに必要な力 [N] */
  insertionN: number
  /** 引き抜くのに必要な力 [N] */
  withdrawalN: number
  /** 内訳 */
  parts: {
    entryFrictionN: number
    detentN: number
    perContact: { contactId: string; normalForceN: number; slope: number; insertionN: number; withdrawalN: number }[]
  }
}

function deflectionAt(
  contactIdx: number,
  jack: ResolvedJack,
  plug: ResolvedPlug,
  depth: number,
  faults: FaultParams,
  cfg: ContactModelConfig,
): number {
  return evaluateContact(jack.contacts[contactIdx], plug, depth, faults, cfg).deflectionMm
}

export function computeForce(
  jack: ResolvedJack,
  plug: ResolvedPlug,
  depthMm: number,
  faults: FaultParams,
  cfg: ContactModelConfig,
  fcfg: ForceModelConfig,
): ForceBreakdown {
  const h = fcfg.differentiationStep
  const perContact: ForceBreakdown['parts']['perContact'] = []
  let insertion = 0
  let withdrawal = 0

  for (let i = 0; i < jack.contacts.length; i++) {
    const c = jack.contacts[i]
    const res = evaluateContact(c, plug, depthMm, faults, cfg)
    const N = res.normalForceN
    // dδ/dd を中心差分で求める (プロファイルの区分線形性をそのまま反映する)
    const dPlus = deflectionAt(i, jack, plug, depthMm + h, faults, cfg)
    const dMinus = deflectionAt(i, jack, plug, depthMm - h, faults, cfg)
    // 垂直な段の上では δ が不連続で、この差分は h を変えるだけで値が変わる。
    // 接触ドームが有限の大きさを持つことを、傾きの頭打ちとして表す。
    const raw = (dPlus - dMinus) / (2 * h)
    const slope = Math.min(fcfg.maxRampSlope, Math.max(-fcfg.maxRampSlope, raw))

    const fi = Math.max(0, N * (fcfg.frictionInsert + slope))
    const fw = Math.max(0, N * (fcfg.frictionWithdraw - slope))
    insertion += fi
    withdrawal += fw
    perContact.push({ contactId: c.id, normalForceN: N, slope, insertionN: fi, withdrawalN: fw })
  }

  // 入口ブッシング/ボアの摩擦。噛み合い長さに比例し、上限で頭打ち。
  const engaged = Math.max(0, Math.min(depthMm, plug.fingerLengthMm))
  const entry = Math.min(fcfg.entryFrictionMax, fcfg.entryFrictionPerMm * engaged)

  // 完全挿入位置の保持 (デテント)。プロファイルに溝が無い部品のための明示項。
  const dz = depthMm - jack.fullInsertionDepthMm
  const detent = fcfg.detentPeak * Math.exp(-(dz * dz) / (2 * fcfg.detentSigma * fcfg.detentSigma))

  const scale = fcfg.calibrationScale
  const outsideBore = depthMm <= 0
  return {
    depthMm,
    insertionN: outsideBore ? 0 : (insertion + entry + detent) * scale,
    withdrawalN: outsideBore ? 0 : (withdrawal + entry + detent) * scale,
    parts: { entryFrictionN: entry * scale, detentN: detent * scale, perContact },
  }
}

/** 力曲線を一括で計算する (force_curve.json 用) */
export function computeForceCurve(
  jack: ResolvedJack,
  plug: ResolvedPlug,
  faults: FaultParams,
  cfg: ContactModelConfig,
  fcfg: ForceModelConfig,
  stepMm = 0.05,
  startMm = -2,
): ForceBreakdown[] {
  const out: ForceBreakdown[] = []
  const n = Math.round((jack.fullInsertionDepthMm - startMm) / stepMm)
  for (let i = 0; i <= n; i++) {
    const d = startMm + i * stepMm
    out.push(computeForce(jack, plug, Math.min(d, jack.fullInsertionDepthMm), faults, cfg, fcfg))
  }
  return out
}

/**
 * 寸法テーブル (dimensions.json) と各モデル定義 (plugSegments / jackContacts) を
 * 「数値 + 根拠区分」に解決するレイヤ。
 *
 * ここを通さずに生の数値を使う実装を書かないこと。根拠追跡が切れる。
 */

import type {
  DimensionEntry,
  DimensionTable,
  DimRef,
  Grade,
  JackContactDef,
  JackModelDef,
  JackTerminalDef,
  PlugModelDef,
  PlugNet,
  PlugSegmentDef,
  SegmentKind,
  SignalFunction,
} from './types'
import { GRADE_ORDER } from './types'

/** 2 つの根拠区分のうち「弱い方」を返す。判定結果のグレード伝播に使う。 */
export function weakerGrade(a: Grade, b: Grade): Grade {
  return GRADE_ORDER.indexOf(a) >= GRADE_ORDER.indexOf(b) ? a : b
}

export function weakestGrade(grades: Grade[]): Grade {
  return grades.reduce<Grade>((acc, g) => weakerGrade(acc, g), 'FACT')
}

export class DimensionResolutionError extends Error {}

/** 解決済みの寸法値。値と根拠がセットで動く。 */
export interface ResolvedValue {
  key: string | null
  value: number
  grade: Grade
  unit: string
  tolerance?: number
  sources: string[]
  note?: string
}

export class Dimensions {
  private readonly table: DimensionTable

  constructor(table: DimensionTable) {
    this.table = table
  }

  has(key: string): boolean {
    return Object.prototype.hasOwnProperty.call(this.table, key)
  }

  entry(key: string): DimensionEntry {
    const e = this.table[key]
    if (!e) throw new DimensionResolutionError(`未定義の寸法キー: ${key}`)
    return e
  }

  /** DimRef (キー文字列 or 直値) を解決する。直値は ASSUMPTION 扱い。 */
  resolve(ref: DimRef, contextForLiteral = 'inline literal'): ResolvedValue {
    if (typeof ref === 'number') {
      return {
        key: null,
        value: ref,
        grade: 'ASSUMPTION',
        unit: 'mm',
        sources: [],
        note: `JSON に直接書かれた値 (${contextForLiteral})`,
      }
    }
    const e = this.entry(ref)
    return {
      key: ref,
      value: e.value,
      grade: e.grade,
      unit: e.unit ?? 'mm',
      tolerance: e.tolerance,
      sources: e.sources ?? [],
      note: e.note,
    }
  }

  /** 値だけ欲しい場合 */
  num(ref: DimRef): number {
    return this.resolve(ref).value
  }

  keys(): string[] {
    return Object.keys(this.table).sort()
  }

  all(): DimensionTable {
    return this.table
  }
}

// ---------------------------------------------------------------------------
// プラグ
// ---------------------------------------------------------------------------

export interface ResolvedPlugSegment {
  id: string
  label: string
  kind: SegmentKind
  net?: PlugNet
  /** プラグ先端を 0 とした軸方向開始 [mm] */
  startMm: number
  endMm: number
  material: string
  grade: Grade
  sources: string[]
  def: PlugSegmentDef
}

export interface ResolvedPlug {
  variant: PlugModelDef['variant']
  poleCount: number
  partNumber: string
  manufacturer: string
  netFunctions: Partial<Record<PlugNet, SignalFunction>>
  netFunctionsGrade: Grade
  fingerLengthMm: number
  bodyDiameterMm: number
  bodyRadiusMm: number
  /** s 昇順の外形プロファイル */
  profile: { s: number; r: number }[]
  segments: ResolvedPlugSegment[]
  handle: {
    shoulderDiameterMm: number
    shoulderLengthMm: number
    bodyDiameterMm: number
    bodyLengthMm: number
    strainReliefLengthMm: number
    strainReliefDiameterMm: number
    cableDiameterMm: number
    cableLengthMm: number
  }
  grade: Grade
}

export function resolvePlug(def: PlugModelDef, dims: Dimensions): ResolvedPlug {
  const fingerLength = dims.resolve(def.fingerLength)
  const bodyDiameter = dims.resolve(def.bodyDiameter)

  const profile = def.radiusProfile
    .map((p) => ({ s: dims.num(p.s), r: dims.num(p.r) }))
    .sort((a, b) => a.s - b.s)

  if (profile.length < 2) {
    throw new DimensionResolutionError('プラグ外形プロファイルは 2 点以上必要')
  }

  const segments: ResolvedPlugSegment[] = def.segments.map((s) => {
    const start = dims.resolve(s.start, `${s.id}.start`)
    const end = dims.resolve(s.end, `${s.id}.end`)
    if (end.value <= start.value) {
      throw new DimensionResolutionError(
        `セグメント ${s.id} の幅が 0 以下 (${start.value} → ${end.value})。` +
          '絶縁帯を幅ゼロの境界として扱ってはならない (仕様 §4.2)。',
      )
    }
    return {
      id: s.id,
      label: s.label,
      kind: s.kind,
      net: s.net,
      startMm: start.value,
      endMm: end.value,
      material: s.material,
      grade: weakerGrade(start.grade, end.grade),
      sources: [...new Set([...start.sources, ...end.sources])],
      def: s,
    }
  })

  segments.sort((a, b) => a.startMm - b.startMm)

  // 連続性チェック: 隙間や重なりがあると接触判定が破綻する
  for (let i = 1; i < segments.length; i++) {
    const gap = segments[i].startMm - segments[i - 1].endMm
    if (Math.abs(gap) > 1e-9) {
      throw new DimensionResolutionError(
        `セグメント ${segments[i - 1].id} と ${segments[i].id} の間に ${gap.toFixed(4)}mm の` +
          '不整合がある。区間は隙間なく連続していなければならない。',
      )
    }
  }
  if (Math.abs(segments[0].startMm) > 1e-9) {
    throw new DimensionResolutionError('最初のセグメントは s=0 (プラグ先端) から始まる必要がある')
  }
  const last = segments[segments.length - 1]
  if (Math.abs(last.endMm - fingerLength.value) > 1e-6) {
    throw new DimensionResolutionError(
      `最後のセグメント末端 (${last.endMm}) が指部長 (${fingerLength.value}) と一致しない`,
    )
  }

  const h = def.handle
  return {
    variant: def.variant,
    poleCount: def.poleCount,
    partNumber: def.partNumber,
    manufacturer: def.manufacturer,
    netFunctions: def.netFunctions,
    netFunctionsGrade: def.netFunctionsGrade,
    fingerLengthMm: fingerLength.value,
    bodyDiameterMm: bodyDiameter.value,
    bodyRadiusMm: bodyDiameter.value / 2,
    profile,
    segments,
    handle: {
      shoulderDiameterMm: dims.num(h.shoulderDiameter),
      shoulderLengthMm: dims.num(h.shoulderLength),
      bodyDiameterMm: dims.num(h.bodyDiameter),
      bodyLengthMm: dims.num(h.bodyLength),
      strainReliefLengthMm: dims.num(h.strainReliefLength),
      strainReliefDiameterMm: dims.num(h.strainReliefDiameter),
      cableDiameterMm: dims.num(h.cableDiameter),
      cableLengthMm: dims.num(h.cableLength),
    },
    grade: weakestGrade([fingerLength.grade, bodyDiameter.grade, ...segments.map((s) => s.grade)]),
  }
}

// ---------------------------------------------------------------------------
// ジャック
// ---------------------------------------------------------------------------

export interface ResolvedBreakContact {
  id: string
  label: string
  terminalId: string
  normalState: 'closed' | 'open'
  openDeflectionMm: number
  grade: Grade
}

export interface ResolvedJackContact {
  id: string
  label: string
  expectedSegment: string
  terminalId: string
  axialCenterMm: number
  padWidthMm: number
  freeRadiusMm: number
  nominalDeflectionMm: number
  maxDeflectionMm: number
  springRateNPerMm: number
  angularPositionDeg: number
  rootAxialMm: number
  breakContact: ResolvedBreakContact | null
  grade: Grade
  sources: string[]
  note?: string
  def: JackContactDef
}

export interface ResolvedJack {
  partNumber: string
  manufacturer: string
  fullInsertionDepthMm: number
  entryBoreDiameterMm: number
  entryBushingLengthMm: number
  noseLengthMm: number
  nutDiameterMm: number
  housing: {
    widthMm: number
    heightMm: number
    depthMm: number
    axisHeightFromPcbMm: number
  }
  contacts: ResolvedJackContact[]
  terminals: ResolvedJackTerminal[]
  grade: Grade
}

/** 端子定義に、図面記載の実装位置を載せたもの */
export type ResolvedJackTerminal = JackTerminalDef & {
  /** 前面基準面からの軸位置 [mm]。読めなければ null */
  axialMm: number | null
  /** 軸中心からの横位置 [mm]。読めなければ null */
  lateralMm: number | null
}

export function resolveJack(def: JackModelDef, dims: Dimensions): ResolvedJack {
  const fullDepth = dims.resolve(def.fullInsertionDepth)

  const contacts: ResolvedJackContact[] = def.contacts.map((c) => {
    const axial = dims.resolve(c.axialCenter, `${c.id}.axialCenter`)
    const pad = dims.resolve(c.padWidth, `${c.id}.padWidth`)
    const free = dims.resolve(c.freeRadius, `${c.id}.freeRadius`)
    const nomDef = dims.resolve(c.nominalDeflection, `${c.id}.nominalDeflection`)
    const maxDef = dims.resolve(c.maxDeflection, `${c.id}.maxDeflection`)
    const rate = dims.resolve(c.springRate, `${c.id}.springRate`)

    if (pad.value <= 0) {
      throw new DimensionResolutionError(`接点 ${c.id} のパッド幅が 0 以下。幅を持つ接点として扱う必要がある。`)
    }

    let brk: ResolvedBreakContact | null = null
    if (c.breakContact) {
      const od = dims.resolve(c.breakContact.openDeflection, `${c.breakContact.id}.openDeflection`)
      brk = {
        id: c.breakContact.id,
        label: c.breakContact.label,
        terminalId: c.breakContact.terminalId,
        normalState: c.breakContact.normalState,
        openDeflectionMm: od.value,
        grade: od.grade,
      }
    }

    return {
      id: c.id,
      label: c.label,
      expectedSegment: c.expectedSegment,
      terminalId: c.terminalId,
      axialCenterMm: axial.value,
      padWidthMm: pad.value,
      freeRadiusMm: free.value,
      nominalDeflectionMm: nomDef.value,
      maxDeflectionMm: maxDef.value,
      springRateNPerMm: rate.value,
      angularPositionDeg: dims.num(c.angularPosition),
      rootAxialMm: dims.num(c.rootAxial),
      breakContact: brk,
      grade: weakestGrade([
        c.grade,
        axial.grade,
        pad.grade,
        free.grade,
        nomDef.grade,
        maxDef.grade,
        rate.grade,
        ...(brk ? [brk.grade] : []),
      ]),
      sources: [
        ...new Set([
          ...(c.sources ?? []),
          ...axial.sources,
          ...pad.sources,
          ...free.sources,
          ...rate.sources,
        ]),
      ],
      note: c.note,
      def: c,
    }
  })

  // 端子参照の整合性
  const terminalIds = new Set(def.terminals.map((t) => t.id))
  for (const c of contacts) {
    if (!terminalIds.has(c.terminalId)) {
      throw new DimensionResolutionError(`接点 ${c.id} が未定義の端子 ${c.terminalId} を参照している`)
    }
    if (c.breakContact && !terminalIds.has(c.breakContact.terminalId)) {
      throw new DimensionResolutionError(
        `ブレーク接点 ${c.breakContact.id} が未定義の端子 ${c.breakContact.terminalId} を参照している`,
      )
    }
  }

  const h = def.housing
  return {
    partNumber: def.partNumber,
    manufacturer: def.manufacturer,
    fullInsertionDepthMm: fullDepth.value,
    entryBoreDiameterMm: dims.num(def.entryBoreDiameter),
    entryBushingLengthMm: dims.num(def.entryBushingLength),
    noseLengthMm: dims.num(def.noseLength),
    nutDiameterMm: dims.num(def.nutDiameter),
    housing: {
      widthMm: dims.num(h.width),
      heightMm: dims.num(h.height),
      depthMm: dims.num(h.depth),
      axisHeightFromPcbMm: dims.num(h.axisHeightFromPcb),
    },
    contacts,
    // 端子の実位置 (jack.pinN.axial / .lateral) を載せる。
    // これが無いと 3D 表示が等間隔の合成位置になり、「端子3 が軸の左だから
    // Tip 接点は 270deg」という角度導出を画面で確かめられない。
    terminals: def.terminals.map((t) => {
      const num = t.pin
      const get = (suffix: string): number | null => {
        if (!num) return null
        try {
          return dims.num(`jack.pin${num}.${suffix}`)
        } catch {
          return null
        }
      }
      return { ...t, axialMm: get('axial'), lateralMm: get('lateral') }
    }),
    grade: weakestGrade([fullDepth.grade, ...contacts.map((c) => c.grade)]),
  }
}

// ---------------------------------------------------------------------------
// 幾何ユーティリティ
// ---------------------------------------------------------------------------

/** プラグ外形プロファイルから、先端距離 s における外半径を線形補間で求める。 */
export function plugRadiusAt(profile: { s: number; r: number }[], s: number): number {
  if (s <= profile[0].s) return profile[0].r
  const last = profile[profile.length - 1]
  if (s >= last.s) return last.r
  for (let i = 1; i < profile.length; i++) {
    const a = profile[i - 1]
    const b = profile[i]
    if (s <= b.s) {
      const t = b.s === a.s ? 0 : (s - a.s) / (b.s - a.s)
      return a.r + t * (b.r - a.r)
    }
  }
  return last.r
}

/** dr/ds (プロファイルの傾き)。挿抜力のランプ成分に使う。 */
export function plugSlopeAt(profile: { s: number; r: number }[], s: number): number {
  if (s < profile[0].s || s >= profile[profile.length - 1].s) return 0
  for (let i = 1; i < profile.length; i++) {
    const a = profile[i - 1]
    const b = profile[i]
    if (s <= b.s) {
      if (b.s === a.s) return 0
      return (b.r - a.r) / (b.s - a.s)
    }
  }
  return 0
}

export interface Interval {
  lo: number
  hi: number
}

/**
 * プロファイル上で r(s) >= rThreshold となる s の区間を厳密に求める。
 * (区分線形なので交点を解析的に解ける。サンプリング誤差を持ち込まない)
 */
export function radiusAtLeastIntervals(
  profile: { s: number; r: number }[],
  rThreshold: number,
): Interval[] {
  const out: Interval[] = []
  for (let i = 1; i < profile.length; i++) {
    const a = profile[i - 1]
    const b = profile[i]
    if (b.s <= a.s) continue
    const aIn = a.r >= rThreshold
    const bIn = b.r >= rThreshold
    if (aIn && bIn) {
      out.push({ lo: a.s, hi: b.s })
    } else if (!aIn && !bIn) {
      continue
    } else {
      // 1 回だけ交差する
      const t = (rThreshold - a.r) / (b.r - a.r)
      const sx = a.s + t * (b.s - a.s)
      if (aIn) out.push({ lo: a.s, hi: sx })
      else out.push({ lo: sx, hi: b.s })
    }
  }
  return mergeIntervals(out)
}

export function mergeIntervals(list: Interval[]): Interval[] {
  if (list.length === 0) return []
  const sorted = [...list].sort((x, y) => x.lo - y.lo)
  const out: Interval[] = [{ ...sorted[0] }]
  for (let i = 1; i < sorted.length; i++) {
    const cur = out[out.length - 1]
    const nxt = sorted[i]
    if (nxt.lo <= cur.hi + 1e-9) {
      cur.hi = Math.max(cur.hi, nxt.hi)
    } else {
      out.push({ ...nxt })
    }
  }
  return out.filter((iv) => iv.hi - iv.lo > 1e-12)
}

export function intersectIntervals(a: Interval[], b: Interval[]): Interval[] {
  const out: Interval[] = []
  for (const x of a) {
    for (const y of b) {
      const lo = Math.max(x.lo, y.lo)
      const hi = Math.min(x.hi, y.hi)
      if (hi - lo > 1e-12) out.push({ lo, hi })
    }
  }
  return mergeIntervals(out)
}

export function intervalsWidth(list: Interval[]): number {
  return list.reduce((sum, iv) => sum + (iv.hi - iv.lo), 0)
}

/**
 * 挿入経路の全域走査とイベント抽出。仕様 §11 / §17 / §18。
 *
 * 走査は 0.05mm 以下の刻みで行い、同じ入力なら必ず同じ結果になる。
 */

import type { TrsModel } from './engine'
import type { BreakState, ContactState, FaultParams, Grade, InsertionEvent } from './types'
import { DEFAULT_FAULTS } from './contact'

export interface SweepContactRow {
  contactId: string
  /** 接点パッドが重なっているセグメント id (幅の大きい順) */
  touchingSegments: string[]
  /** 導通していると判定したプラグ導体 */
  connectedNets: string[]
  state: ContactState
  breakState: BreakState | null
  quality: number
  deflectionMm: number
  grade: Grade
}

export interface SweepRow {
  depthMm: number
  depthPercent: number
  contacts: SweepContactRow[]
  bridged: boolean
  wrongSegment: boolean
  acoustic: string
  estimatedInsertionForceN: number
  estimatedWithdrawalForceN: number
}

export function sweep(
  model: TrsModel,
  opts: { stepMm?: number; startMm?: number; faults?: FaultParams } = {},
): SweepRow[] {
  const stepMm = opts.stepMm ?? 0.02
  const startMm = opts.startMm ?? -(model.plug.fingerLengthMm + 1)
  const faults = opts.faults ?? DEFAULT_FAULTS
  const end = model.fullDepthMm
  const n = Math.round((end - startMm) / stepMm)
  const rows: SweepRow[] = []
  for (let i = 0; i <= n; i++) {
    // 浮動小数の累積誤差を避けるため毎回 startMm から作り直す
    const depth = Math.min(end, Number((startMm + i * stepMm).toFixed(6)))
    const ev = model.evaluate(depth, faults)
    const f = model.force(depth, faults)
    rows.push({
      depthMm: depth,
      depthPercent: Number(ev.depthPercent.toFixed(4)),
      contacts: ev.contacts.map((c) => ({
        contactId: c.contactId,
        touchingSegments: c.overlaps.map((o) => o.segmentId),
        connectedNets: c.connectedNets,
        state: c.state,
        breakState: c.breakState,
        quality: Number(c.quality.toFixed(4)),
        deflectionMm: Number(c.deflectionMm.toFixed(4)),
        grade: c.grade,
      })),
      bridged: ev.anyBridged,
      wrongSegment: ev.anyWrongSegment,
      acoustic: ev.acoustic.code,
      estimatedInsertionForceN: Number(f.insertionN.toFixed(3)),
      estimatedWithdrawalForceN: Number(f.withdrawalN.toFixed(3)),
    })
  }
  return rows
}

// ---------------------------------------------------------------------------
// イベント抽出
// ---------------------------------------------------------------------------

const CONDUCTING: ContactState[] = ['CLOSED', 'TOUCH_UNSTABLE', 'WRONG_SEGMENT', 'BRIDGED']

export function extractEvents(model: TrsModel, rows: SweepRow[]): InsertionEvent[] {
  const events: InsertionEvent[] = []
  const seen = new Set<string>()

  const push = (
    kind: InsertionEvent['kind'],
    depthMm: number,
    label: string,
    detail: string,
    severity: InsertionEvent['severity'],
    once = true,
  ) => {
    if (once) {
      if (seen.has(kind)) return
      seen.add(kind)
    }
    events.push({ kind, depthMm, label, detail, severity })
  }

  const expectedNetOf = (contactId: string) => {
    const c = model.jack.contacts.find((x) => x.id === contactId)!
    return model.plug.segments.find((s) => s.id === c.expectedSegment)?.net
  }

  let prev: SweepRow | null = null

  for (const row of rows) {
    // 最初の物理接触
    if (row.contacts.some((c) => c.deflectionMm > 0)) {
      push(
        'FIRST_PHYSICAL_CONTACT',
        row.depthMm,
        '最初の物理接触',
        'ジャックの接点ばねがプラグ表面に触れ、たわみ始めた',
        'info',
      )
    }
    // 最初の電気接触
    if (row.contacts.some((c) => CONDUCTING.includes(c.state))) {
      push(
        'FIRST_ELECTRICAL_CONTACT',
        row.depthMm,
        '最初の電気接触',
        'いずれかの接点がプラグ導体と導通した',
        'info',
      )
    }
    // 最初のブレーク接点開放
    if (row.contacts.some((c) => c.breakState === 'BREAK_OPEN')) {
      push(
        'FIRST_BREAK_OPEN',
        row.depthMm,
        '最初のブレーク接点開放',
        '接点ばねが押し広げられ、内蔵スイッチが開いた (内蔵スピーカ等への切替が起きる位置)',
        'info',
      )
    }
    // 最初の誤セグメント接触
    if (row.wrongSegment) {
      const c = row.contacts.find((x) => x.state === 'WRONG_SEGMENT')!
      push(
        'FIRST_WRONG_SEGMENT',
        row.depthMm,
        '最初の誤セグメント接触',
        `${c.contactId} が本来の ${expectedNetOf(c.contactId)} ではなく ${c.connectedNets.join('+')} に触れた`,
        'warn',
      )
    }
    // 最初の橋絡
    if (row.bridged) {
      const c = row.contacts.find((x) => x.state === 'BRIDGED')!
      push(
        'FIRST_BRIDGE',
        row.depthMm,
        '最初の橋絡 (短絡)',
        `${c.contactId} が ${c.connectedNets.join(' と ')} を同時に短絡させた`,
        'bad',
      )
    }
    // 全信号接点が正しいセグメントに接触
    const allCorrect = row.contacts.every((c) => {
      const jc = model.jack.contacts.find((x) => x.id === c.contactId)!
      const expected = model.plug.segments.find((s) => s.id === jc.expectedSegment)?.net
      return c.state === 'CLOSED' && c.connectedNets.length === 1 && c.connectedNets[0] === expected
    })
    if (allCorrect) {
      push(
        'ALL_SIGNALS_CORRECT',
        row.depthMm,
        '全接点が正規接続',
        'Tip/Ring/Sleeve の全てが対応する導体に安定接触した',
        'ok',
      )
    }
    prev = row
  }

  // 完全挿入
  push(
    'FULL_INSERTION',
    model.fullDepthMm,
    '完全挿入',
    'プラグ肩がジャックの停止面に当たり、それ以上入らない位置',
    'ok',
  )

  // 抜去時に最後の接点が離れる位置。
  // 浅い側から走査し、最初に接触が生じる深度を取る。これより浅い側では常に非接触なので、
  // 抜いていく向きではここが「最後に離れる」位置になる。
  // 幾何は挿入方向と抜去方向で同一なので、この深度は最初の物理接触と一致する
  // (異なるのは力だけ。力のヒステリシスは force_curve.json 側に出る)。
  for (let i = 0; i < rows.length; i++) {
    if (rows[i].contacts.some((c) => c.deflectionMm > 0)) {
      events.push({
        kind: 'LAST_CONTACT_RELEASE',
        depthMm: rows[i].depthMm,
        label: '抜去時に最後の接点が離れる位置',
        detail:
          'これより浅いとジャックはプラグに一切触れていない。経路の幾何は挿入・抜去で同じなので最初の物理接触と同じ深度になる (違うのは力だけ)。',
        severity: 'info',
      })
      break
    }
  }

  // 状態が切り替わる位置 (接点ごと)
  prev = null
  for (const row of rows) {
    if (prev) {
      for (let i = 0; i < row.contacts.length; i++) {
        const a = prev.contacts[i]
        const b = row.contacts[i]
        if (a.state !== b.state) {
          events.push({
            kind: 'STATE_CHANGE',
            depthMm: row.depthMm,
            label: `${b.contactId}: ${a.state} → ${b.state}`,
            detail: `接触セグメント: ${b.touchingSegments.join(', ') || 'なし'}`,
            severity:
              b.state === 'BRIDGED' || b.state === 'WRONG_SEGMENT'
                ? 'bad'
                : b.state === 'CLOSED'
                  ? 'ok'
                  : 'info',
            // label とは別に持つ。文言を直しても識別子が変わらないようにする
            subject: {
              subjectType: 'contact',
              subjectId: b.contactId,
              fromState: a.state,
              toState: b.state,
            },
          })
        }
        if (a.breakState !== b.breakState) {
          events.push({
            kind: 'STATE_CHANGE',
            depthMm: row.depthMm,
            label: `${b.contactId} ブレーク接点: ${a.breakState} → ${b.breakState}`,
            detail: 'ジャック内蔵スイッチの開閉',
            severity: 'info',
            subject: {
              subjectType: 'break-contact',
              subjectId: b.contactId,
              fromState: String(a.breakState),
              toState: String(b.breakState),
            },
          })
        }
      }
    }
    prev = row
  }

  events.sort((a, b) => a.depthMm - b.depthMm)
  return events
}

/**
 * 電気トポロジーの分類。**このプロジェクトで唯一の正本。**
 *
 * ## なぜ切り出したか（統合オーダー 2026-08-03 P0-4）
 *
 * 「帰線が浮き、L と R が別々の導体に届いている」という同じ判定が、
 * 2026-08-03 の時点で **5 か所**に書かれていた。
 *
 *   1. `src/model/circuit.ts` の `predictAcoustic`
 *   2. `scripts/searchTopology.ts` の `isStrictDifferenceSignal`
 *   3. `scripts/compareRealJack.ts` の `differenceWindows`
 *   4. `test/realJackComparison.test.ts` の `differenceWindowCount`
 *   5. `test/trrs.test.ts` の左右差分カウンタ
 *
 * 5 つが揃って正しい保証はどこにも無かった。実際、2 と 1 は
 * **2026-08-02 に 1 だけが直り、2 の説明文が旧実装のまま取り残されていた**
 * （「判定順の都合で L と R が同じ導体でも GROUND_OPEN になる」という記述。
 * その挙動はもう存在しない）。
 *
 * ## 層を分ける
 *
 * ここが返すのは**電気的な事実**だけである。「どう聞こえるか」は別層
 * （`predictAcoustic`）が持つ。オーダーが求めている分離はこれ。
 *
 * ## 位置ではなく機能で見る
 *
 * 端子 ID を直書きしない。3極ジャックは T1/T2/T3、4極は P1〜P6 と番号体系が違い、
 * 直書きすると片方が常に判定不能になる（2026-08-02 に実際に起きた）。
 * `signalRoleMap`（端子 → 機器が期待する機能）と
 * `netFunctions`（プラグ導体 → その導体が担う機能）で引く。
 */

import type { BreakState, ContactState, PlugNet, SignalFunction } from './types'

/**
 * 区間に付ける電気トポロジーの分類。
 * Half-Plug Lab 側の受け取り表（docs/HALF_PLUG_ADAPTER.md §5.3）と 1 対 1 で対応する。
 */
export type TopologyClass =
  | 'all-expected-functions-match'
  | 'no-path'
  | 'one-sided'
  | 'on-insulator'
  | 'wrong-conductor'
  | 'signal-to-signal-short'
  | 'signal-to-return-short'
  | 'ground-open-differential'
  | 'ground-open-nondifferential'

/** 分類対象として調べた全クラス。`absentTopologies.searched` の正本 */
export const ALL_TOPOLOGY_CLASSES: readonly TopologyClass[] = [
  'all-expected-functions-match',
  'no-path',
  'one-sided',
  'on-insulator',
  'wrong-conductor',
  'signal-to-signal-short',
  'signal-to-return-short',
  'ground-open-differential',
  'ground-open-nondifferential',
]

export interface TopologyInput {
  /** 端子 ID → その端子に届いているプラグ導体 */
  terminalToPlugNet: Record<string, PlugNet[]>
  /** 端子 ID → 機器側がその端子に期待する機能 */
  signalRoleMap: Record<string, SignalFunction>
  /**
   * プラグ導体 → その導体が担う機能。
   *
   * **これが無いと分類できない。** 「Ring2 に届いた」だけでは、それが帰線なのか
   * マイクなのか決まらない（CTIA と OMTP で入れ替わる）。オーダーの引数一覧には
   * 挙がっていないが、位置ではなく機能で見るという原則にこれが要る。
   */
  netFunctions: Partial<Record<PlugNet, SignalFunction>>
  contactStates: readonly ContactState[]
  breakStates: readonly (BreakState | null)[]
}

export interface TopologyClassification {
  topologyClass: TopologyClass
  /** なぜその分類になったか。文言ではなく機械可読な符号 */
  reasonCode: string
  lNets: PlugNet[]
  rNets: PlugNet[]
  gndNets: PlugNet[]
  /** L と R が同じ導体に落ちている */
  shortsSignalToSignal: boolean
  /** 帰線用の端子が L / R を担う導体に触れている、または信号が帰線導体に落ちている */
  shortsSignalToReturn: boolean
  /** どこにも届いていない機能 */
  openSignals: SignalFunction[]
  /** 判定の境目に近いか。窓が狭い・接触が不安定なときに立つ */
  confidenceBoundary: boolean
}

/**
 * 純関数。**モデルにも I/O にも依存しない。**
 * 同じ入力からは必ず同じ結果を返す。
 */
export function classifyElectricalTopology(input: TopologyInput): TopologyClassification {
  const { terminalToPlugNet, signalRoleMap, netFunctions, contactStates, breakStates } = input

  const netsFor = (fn: SignalFunction): PlugNet[] => {
    const id = Object.keys(signalRoleMap).find((k) => signalRoleMap[k] === fn)
    return id === undefined ? [] : (terminalToPlugNet[id] ?? [])
  }
  const hasTerminal = (fn: SignalFunction) => Object.values(signalRoleMap).includes(fn)

  const lNets = netsFor('L')
  const rNets = netsFor('R')
  const gndNets = netsFor('GND')
  const micNets = netsFor('MIC')

  /** 届いた導体がちょうど 1 本で、その機能が期待どおり */
  const okFor = (nets: PlugNet[], want: SignalFunction) =>
    nets.length === 1 && netFunctions[nets[0]] === want
  const lOk = okFor(lNets, 'L')
  const rOk = okFor(rNets, 'R')
  const gOk = okFor(gndNets, 'GND')

  const openSignals: SignalFunction[] = []
  for (const [fn, nets] of [
    ['L', lNets],
    ['R', rNets],
    ['GND', gndNets],
    ['MIC', micNets],
  ] as const)
    if (hasTerminal(fn) && nets.length === 0) openSignals.push(fn)

  // --- 短絡の 2 種類を分ける -------------------------------------------------
  // **2026-08-03 まで、どちらも signal-to-return-short にしていた。**
  // L と R が同じ導体に落ちるのは信号どうしの短絡であって、帰線への短絡ではない。
  const shortsSignalToSignal = lNets.length > 0 && rNets.length > 0 && lNets.some((n) => rNets.includes(n))
  const signalOnReturnConductor = [...lNets, ...rNets].some((n) => netFunctions[n] === 'GND')
  const returnOnSignalConductor = gndNets.some((n) => {
    const f = netFunctions[n]
    return f === 'L' || f === 'R'
  })
  const shortsSignalToReturn = signalOnReturnConductor || returnOnSignalConductor

  const unstable = contactStates.includes('TOUCH_UNSTABLE')
  const anyInsulated = contactStates.includes('INSULATED')
  const anyWrong = contactStates.includes('WRONG_SEGMENT')
  const anyBridged = contactStates.includes('BRIDGED')
  const anyConducting = lNets.length + rNets.length + gndNets.length + micNets.length > 0

  const out = (topologyClass: TopologyClass, reasonCode: string): TopologyClassification => ({
    topologyClass,
    reasonCode,
    lNets,
    rNets,
    gndNets,
    shortsSignalToSignal,
    shortsSignalToReturn,
    openSignals,
    // 不安定な接触があるか、ブレーク接点が判定不能なら境目扱い
    confidenceBoundary: unstable || breakStates.includes('UNKNOWN'),
  })

  // --- 分類 ---------------------------------------------------------------
  // 順序に意味がある。**害の大きいものから見る。**
  if (!anyConducting) {
    // 触れてはいるが絶縁帯の上、という状態を「どこにも届かない」と区別する
    if (anyInsulated) return out('on-insulator', 'ALL_CONTACTS_ON_INSULATOR')
    return out('no-path', 'NO_CONDUCTING_PATH')
  }

  if (shortsSignalToSignal) return out('signal-to-signal-short', 'L_AND_R_ON_SAME_CONDUCTOR')
  if (returnOnSignalConductor) return out('signal-to-return-short', 'RETURN_TERMINAL_ON_SIGNAL_CONDUCTOR')
  if (signalOnReturnConductor && !lOk && !rOk) return out('signal-to-return-short', 'SIGNAL_TERMINAL_ON_RETURN_CONDUCTOR')

  // --- 帰線が浮いている ----------------------------------------------------
  if (!gOk && gndNets.length === 0) {
    // **ここが 5 か所に複製されていた判定である。**
    // L と R が別々の導体に 1 本ずつ届いていれば、左右の差分が残りうる。
    if (lNets.length === 1 && rNets.length === 1 && lNets[0] !== rNets[0])
      return out('ground-open-differential', 'RETURN_OPEN_L_AND_R_ON_DISTINCT_CONDUCTORS')
    if (lNets.length > 0 && rNets.length > 0)
      return out('ground-open-nondifferential', 'RETURN_OPEN_BUT_L_AND_R_NOT_DISTINCT')
    return out('no-path', 'RETURN_OPEN_AND_CIRCUIT_NOT_CLOSED')
  }

  // --- 帰線は届いている ----------------------------------------------------
  if (lOk && rOk) {
    if (anyBridged) return out('wrong-conductor', 'CORRECT_PATHS_PLUS_BRIDGE')
    // プラグ側で帰線を担う導体がどの接点にも触れていない (4極 × 3極)
    const gndConductorReached = Object.entries(netFunctions).some(
      ([net, fn]) => fn === 'GND' && Object.values(terminalToPlugNet).some((ns) => ns.includes(net as PlugNet)),
    )
    if (!gndConductorReached && gndNets.some((n) => netFunctions[n] === 'MIC'))
      return out('ground-open-nondifferential', 'RETURN_ROUTED_THROUGH_MIC_ELEMENT')
    if (gOk) return out('all-expected-functions-match', 'ALL_EXPECTED_FUNCTIONS_MATCH')
  }

  if ((lOk && !rOk && gOk) || (!lOk && rOk && gOk)) return out('one-sided', 'ONE_CHANNEL_NOT_REACHED')
  if (anyWrong) return out('wrong-conductor', 'CONTACT_ON_UNEXPECTED_CONDUCTOR')
  if (anyInsulated) return out('on-insulator', 'CONTACT_ON_INSULATOR_BAND')
  return out('wrong-conductor', 'NONSTANDARD_CONNECTION')
}

/**
 * モデルの評価結果から分類する薄い包み。
 *
 * **呼ぶ側が入力を組み立てないようにするため**にある。組み立てを各所へ書かせると、
 * 「signalRole ではなく端子 ID で引く」といった取り違えがまた 5 か所へ散る。
 */
export function classifyFromEvaluation(
  jackTerminals: readonly { id: string; signalRole?: SignalFunction }[],
  netFunctions: Partial<Record<PlugNet, SignalFunction>>,
  ev: {
    contacts: readonly { state: ContactState; breakState: BreakState | null }[]
    circuit: { terminalToPlugNet: Record<string, PlugNet[]> }
  },
): TopologyClassification {
  const signalRoleMap: Record<string, SignalFunction> = {}
  for (const t of jackTerminals) if (t.signalRole) signalRoleMap[t.id] = t.signalRole
  return classifyElectricalTopology({
    terminalToPlugNet: ev.circuit.terminalToPlugNet,
    signalRoleMap,
    netFunctions,
    contactStates: ev.contacts.map((c) => c.state),
    breakStates: ev.contacts.map((c) => c.breakState),
  })
}

/**
 * 3.5mm TRS プラグ/ジャック 接合機構モデル — 型定義
 *
 * 設計原則:
 *  - 数値は必ず「根拠区分(Grade)」を伴う。裸の number をモデル層に持ち込まない。
 *  - 接触判定は 3D メッシュ名・画面座標・物理エンジンに一切依存しない純粋関数で行う。
 *  - 単位は全て mm / N / 度 (deg)。3D 表示側で必要ならスケールする。
 */

/** 根拠区分。仕様 §3。 */
export type Grade =
  /** 一次資料に直接記載されている */
  | 'FACT'
  /** 一次資料の寸法から幾何学的に導出した */
  | 'DERIVED'
  /** 資料にないため明示的な仮定を置いた */
  | 'ASSUMPTION'
  /** 確認できていない */
  | 'UNKNOWN'

export const GRADE_ORDER: Grade[] = ['FACT', 'DERIVED', 'ASSUMPTION', 'UNKNOWN']

/** 根拠区分つきの寸法エントリ。dimensions.json の 1 行。 */
export interface DimensionEntry {
  /** 値 (mm / N / deg / 無次元) */
  value: number
  /** 単位。省略時 mm */
  unit?: string
  /** 公差 (± value)。分かっている場合のみ。左右対称なものに限る */
  tolerance?: number
  /**
   * 感度解析でこの値を振る範囲 [min, max]。要素は 2 個 (使う側で検査する)。
   *
   * `tolerance` が左右対称の公差しか表せないので、実測のばらつきのように
   * 非対称な幅はこちらに書く。両方ある場合はこちらが優先。
   * 用途は scripts/sensitivity.ts のみで、モデルの計算には入らない。
   */
  sweepRange?: number[]
  grade: Grade
  /** sourceReferences.json の id 配列 */
  sources?: string[]
  /** 導出方法や仮定の理由 */
  note?: string
}

export type DimensionTable = Record<string, DimensionEntry>

/** 寸法キー、または直値。JSON 側でどちらも書けるようにする。 */
export type DimRef = string | number

// ---------------------------------------------------------------------------
// プラグ
// ---------------------------------------------------------------------------

/**
 * プラグ導体の「位置」。機能ではない。
 * TIP=先端, RING=第1リング, RING2=第2リング, SLEEVE=スリーブ。
 */
export type PlugNet = 'TIP' | 'RING' | 'RING2' | 'SLEEVE'

/**
 * 信号としての「機能」。同じ導体位置でも規格 (CTIA / OMTP) で機能が変わるため、
 * 位置と機能を型として分ける。混同すると仕様 §19 に反する。
 */
export type SignalFunction = 'L' | 'R' | 'GND' | 'MIC'

export const SIGNAL_LABEL: Record<SignalFunction, string> = {
  L: '左チャンネル',
  R: '右チャンネル',
  GND: '共通帰線',
  MIC: 'マイク',
}

export type SegmentKind = 'conductor' | 'insulator'

/**
 * プラグ軸方向の 1 区間。
 * 座標 s はプラグ先端 (tip apex) を 0 とし、肩へ向かう向きを + とする [mm]。
 */
export interface PlugSegmentDef {
  id: string
  label: string
  kind: SegmentKind
  /** conductor のときのみ。insulator は undefined */
  net?: PlugNet
  start: DimRef
  end: DimRef
  /** materials.json の id */
  material: string
}

/** 回転体プロファイルの 1 点。s = 先端からの軸方向距離、r = 外半径。 */
export interface RadiusProfilePoint {
  s: DimRef
  r: DimRef
  /** この点が丸め (球面/フィレット) の一部かどうか。表示の分割数決定に使う */
  fillet?: boolean
}

export interface PlugModelDef {
  schemaVersion: number
  variant: 'TRS' | 'TRRS-CTIA' | 'TRRS-OMTP'
  poleCount: number
  partNumber: string
  manufacturer: string
  /** 導体位置 → 信号機能。CTIA と OMTP はここだけが違う。 */
  netFunctions: Partial<Record<PlugNet, SignalFunction>>
  /** 配列の根拠 */
  netFunctionsGrade: Grade
  netFunctionsSources?: string[]
  /** 金属指部の全長 (先端〜肩) */
  fingerLength: DimRef
  /** 指部の呼び径 */
  bodyDiameter: DimRef
  /** 外形プロファイル (指部のみ)。s 昇順 */
  radiusProfile: RadiusProfilePoint[]
  segments: PlugSegmentDef[]
  /** 肩から後ろのハンドル部 (表示専用、接触判定には使わない) */
  handle: {
    shoulderDiameter: DimRef
    shoulderLength: DimRef
    bodyDiameter: DimRef
    bodyLength: DimRef
    strainReliefLength: DimRef
    strainReliefDiameter: DimRef
    cableDiameter: DimRef
    cableLength: DimRef
  }
}

// ---------------------------------------------------------------------------
// ジャック
// ---------------------------------------------------------------------------

/** ブレーク接点 (ノーマルクローズのスイッチ) の定義 */
export interface BreakContactDef {
  id: string
  label: string
  /** ブレーク接点の相手側端子 (信号ばねが無挿入時に触れている端子) */
  terminalId: string
  /** 無挿入時の状態。データシート記載。 */
  normalState: 'closed' | 'open'
  /** 親接点ばねのたわみがこの値を超えるとブレーク接点が開く [mm] */
  openDeflection: DimRef
}

/** ジャック接点ばね 1 本の定義。仕様 §6。 */
export interface JackContactDef {
  id: string
  label: string
  /** この接点が本来触れるべきプラグセグメント id */
  expectedSegment: string
  /** この接点が内部配線でつながっている端子 id */
  terminalId: string
  /** ジャック前面基準面からの軸方向距離 (奥が +) [mm] */
  axialCenter: DimRef
  /** 接触パッドの軸方向有効幅 [mm] */
  padWidth: DimRef
  /** プラグ非挿入時の接触パッド中心半径 [mm]。プラグ半径 1.75 より小さい。 */
  freeRadius: DimRef
  /** 設計上の標準たわみ量 (完全挿入・正常時) [mm] */
  nominalDeflection: DimRef
  /** 機械的に許容される最大たわみ [mm] */
  maxDeflection: DimRef
  /** ばね定数 [N/mm] (半径方向) */
  springRate: DimRef
  /** 円周方向の配置角 [deg]。3D 表示とばね可視化に使う */
  angularPosition: DimRef
  /** 片持ち梁の根元位置 (前面基準、奥が +) [mm]。表示用 */
  rootAxial: DimRef
  /** このばねが駆動するブレーク接点。無い場合 null */
  breakContact: BreakContactDef | null
  grade: Grade
  sources?: string[]
  note?: string
}

/** 端子の役割。回路パネルと音響推定が参照する。 */
export type TerminalRole =
  | 'tip-signal'
  | 'ring-signal'
  | 'ring2-signal'
  | 'sleeve-signal'
  | 'tip-normal'
  | 'ring-normal'

/** ジャック端子 (はんだ付けピン) */
export interface JackTerminalDef {
  id: string
  /** データシート上のピン番号。推測しないこと。不明なら null */
  pin: string | null
  role: TerminalRole
  /**
   * 機器側の配線としてこの端子が担う信号。
   * ブレーク接点端子など信号を担わない端子は undefined。
   */
  signalRole?: SignalFunction
  label: string
  /** TRS 標準機能。Tip=Left, Ring=Right, Sleeve=Common return */
  functionLabel: string
  grade: Grade
  sources?: string[]
  note?: string
}

export interface JackModelDef {
  schemaVersion: number
  partNumber: string
  manufacturer: string
  /** 前面基準面から停止面 (プラグ肩が当たる面) までの距離 [mm] = 完全挿入深度 */
  fullInsertionDepth: DimRef
  /** 挿入口の内径 [mm] */
  entryBoreDiameter: DimRef
  /** 金属ブッシング/入口部の軸方向長さ [mm] */
  entryBushingLength: DimRef
  /** 前面基準面から絶縁ハウジング前面までの距離 (ローレットナットの突き出し長) [mm] */
  noseLength: DimRef
  /** ローレットナットの外径 [mm] */
  nutDiameter: DimRef
  /** 外装ハウジング寸法 (表示用) */
  housing: {
    width: DimRef
    height: DimRef
    depth: DimRef
    /** 基板面から軸中心までの高さ (アングル型) */
    axisHeightFromPcb: DimRef
  }
  contacts: JackContactDef[]
  terminals: JackTerminalDef[]
}

// ---------------------------------------------------------------------------
// 故障プリセット
// ---------------------------------------------------------------------------

/**
 * 故障は正常モデルを書き換えず、パラメータとして重ねる。仕様 §12。
 */
export interface FaultParams {
  /** 汚れ・酸化係数 0(清浄) 〜 1(絶縁膜で完全に導通不能) */
  contamination: number
  /** 接点摩耗 0(新品) 〜 1。freeRadius が広がり押付が落ちる */
  wear: number
  /** 軸ずれ (半径方向のオフセット) [mm] */
  lateralOffsetMm: number
  /** 傾き [deg] */
  tiltDeg: number
  /** ばね押付倍率。1 = 公称、0.3 = 押付不足 */
  springForceScale: number
  /** 断続接触を有効にする */
  intermittent: boolean
  /** 断続接触の乱数シード (再現可能) */
  seed: number
  /** 断続接触の強さ 0-1 */
  intermittentAmplitude: number
  /** プラグの軸回転 [deg]。理想同心接点では影響なし。汚れ/摩耗時のみ効く。 */
  rotationDeg: number
}

export interface FaultPreset {
  id: string
  label: string
  description: string
  /** 適用する挿入深度 [mm]。null なら現在深度を変えない */
  depthMm: number | null
  params: Partial<FaultParams>
}

// ---------------------------------------------------------------------------
// 接触判定の出力
// ---------------------------------------------------------------------------

/** 接触状態。仕様 §6。 */
export type ContactState =
  | 'OPEN'
  | 'INSULATED'
  | 'TOUCH_UNSTABLE'
  | 'CLOSED'
  | 'WRONG_SEGMENT'
  | 'BRIDGED'
  | 'UNKNOWN'

export type BreakState = 'BREAK_CLOSED' | 'BREAK_OPEN' | 'UNKNOWN'

/** 1 接点 × 1 セグメントの重なり */
export interface SegmentOverlap {
  segmentId: string
  segmentLabel: string
  kind: SegmentKind
  net?: PlugNet
  /**
   * 導通判定に使う重なり幅 [mm]。
   * 接点が押し開かれた位置から contactComplianceMm 以内にある面だけを数える。
   */
  widthMm: number
  /**
   * パッドがこのセグメントに噛み合っている幅 [mm]。
   * 押し開かれる前の自由半径で見た幅で、品質スコアと画面表示はこちらを使う。
   * 平坦面の上では widthMm と一致し、傾斜面の上では widthMm より広くなる。
   */
  engagedWidthMm: number
  /** パッド幅に対する噛み合いの比 0-1 (engagedWidthMm / padWidthMm) */
  fraction: number
}

/** 1 接点の判定結果 */
export interface ContactResult {
  contactId: string
  label: string
  terminalId: string
  expectedSegment: string
  state: ContactState
  /** 機械的に触れているか (半径方向に干渉しているか) */
  physicallyTouching: boolean
  /** ばねのたわみ [mm] */
  deflectionMm: number
  /** 半径方向の押付力 [N] */
  normalForceN: number
  /** 各セグメントとの重なり (幅 > 0 のみ) */
  overlaps: SegmentOverlap[]
  /** 導通していると判定したプラグネット (複数なら橋絡) */
  connectedNets: PlugNet[]
  /** 接触品質スコア 0-1。仕様 §7。 */
  quality: number
  /** ブレーク接点の状態 */
  breakState: BreakState | null
  breakContactId: string | null
  /** 機械的許容たわみを超えているか */
  overDeflected: boolean
  /** この接点に実際に適用された汚れ係数 (回転角により変わる) */
  contaminationApplied: number
  /** 接点パッド中心が対応するプラグ座標 s [mm]。デバッグ・表示用 */
  padCenterSMm: number
  /** 判定の根拠区分。入力寸法の最低グレードが伝播する */
  grade: Grade
  /** 人間向けの一言説明 */
  reason: string
}

/** 回路の 1 本の接続 */
export interface CircuitEdge {
  from: string
  to: string
  kind: 'contact' | 'internal-wire' | 'break-switch' | 'bridge'
  state: ContactState | BreakState
  quality?: number
}

export interface CircuitNet {
  /** 同電位のノード集合 */
  nodes: string[]
}

export interface CircuitResult {
  edges: CircuitEdge[]
  nets: CircuitNet[]
  /** 「Jack Tip terminal → Plug Ring」のような人間可読の行 */
  lines: string[]
  /** 端子 → 実際につながっているプラグネット */
  terminalToPlugNet: Record<string, PlugNet[]>
}

/** 音響上の予測 (簡易推定)。仕様 §14。 */
export interface AcousticPrediction {
  code:
    | 'NORMAL'
    | 'LEFT_ONLY'
    | 'RIGHT_ONLY'
    | 'GROUND_OPEN'
    | 'LR_SHORTED'
    | 'DIFFERENCE_SIGNAL'
    | 'MONO'
    | 'SILENT'
    | 'INTERMITTENT'
    | 'UNKNOWN'
  label: string
  detail: string
  severity: 'ok' | 'warn' | 'bad'
}

/** 1 フレーム分の完全な評価結果 */
export interface EvaluationResult {
  depthMm: number
  depthPercent: number
  contacts: ContactResult[]
  circuit: CircuitResult
  acoustic: AcousticPrediction
  /** 推定挿抜力 [N]。実測値ではない。 */
  estimatedForceN: number
  /** 橋絡が 1 つでもあるか */
  anyBridged: boolean
  /** 誤セグメント接触があるか */
  anyWrongSegment: boolean
  /** 不安定接触があるか */
  anyUnstable: boolean
}

// ---------------------------------------------------------------------------
// イベント
// ---------------------------------------------------------------------------

export type EventKind =
  | 'FIRST_PHYSICAL_CONTACT'
  | 'FIRST_ELECTRICAL_CONTACT'
  | 'FIRST_BREAK_OPEN'
  | 'FIRST_WRONG_SEGMENT'
  | 'FIRST_BRIDGE'
  | 'ALL_SIGNALS_CORRECT'
  | 'FULL_INSERTION'
  | 'LAST_CONTACT_RELEASE'
  | 'STATE_CHANGE'

export interface InsertionEvent {
  kind: EventKind
  depthMm: number
  label: string
  detail: string
  severity: 'info' | 'ok' | 'warn' | 'bad'
  /**
   * 何が、どの状態からどの状態へ変わったか。
   *
   * `kind` だけでは事象を区別できない。STATE_CHANGE は 1 回の挿入で 29 件出るのに、
   * どれも kind が同じなので、感度解析の「kind ごとの幅」を引くと
   * **Ring のブレーク接点に帰線接点用の幅 (−0.88〜14mm) が付く**という誤りが起きた
   * (統合オーダー 2026-08-03 P0-3)。
   *
   * label から作らないこと。**文言を直しただけで ID が変わってはいけない。**
   * kind が 1 回しか出ない事象では省略する (kind そのものが識別子になる)。
   */
  subject?: {
    subjectType: 'contact' | 'break-contact'
    subjectId: string
    fromState: string
    toState: string
  }
}

// ---------------------------------------------------------------------------
// 資料参照
// ---------------------------------------------------------------------------

export interface SourceReference {
  id: string
  title: string
  publisher: string
  partNumber?: string
  docDate?: string
  url?: string
  accessed?: string
  reliability: 'standard' | 'manufacturer' | 'manufacturer-tech' | 'distributor' | 'secondary'
  /** 図面/CAD/画像の利用条件 */
  usageTerms?: string
  /** どの部分に使ったか */
  usedFor?: string
  /** 本文を実際に取得できたか */
  fetchStatus?: 'full-text-read' | 'partial' | 'blocked' | 'not-attempted'
}

export interface MaterialDef {
  id: string
  label: string
  /** 表示色 (hex) */
  color: string
  metalness: number
  roughness: number
  /** 導体か */
  conductive: boolean
  /** 実材料名 */
  spec?: string
  grade: Grade
  sources?: string[]
}
